    function scan() {
        const scene = getScene(findGame());
        if (!scene) return 0;
        let added = 0;
        const MAX_NEW_PER_SCAN = 10;
        for (const mesh of collectMeshes(scene)) {
            const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
            for (const m of mats) {
                if (m && hookMaterial(m)) {
                    added++;
                    if (added >= MAX_NEW_PER_SCAN) return added;
                }
            }
        }

        if (added > 0) {
            void 0;
        }
        return added;
    }

