        game: null,
        player: null,
        renderEntity: null,
        renderMesh: null,
        entityMap: null,

        enabled: false,
        bind: '',
        scale: CONFIG.defaultScale,
        width: CONFIG.defaultWidth,
        groundOffset: CONFIG.defaultGroundOffset,
        baseScale: null,
        serverCap: null,

        panelOpen: false,
        lastGameScan: 0,
        lastEntityScan: 0,

        renderHooks: [],

        hitboxEnabled: true,
        hitboxTargets: [],
        hitboxSignature: null,
        hitboxPlayer: null,
        hitboxRenderEntity: null,
        lastHitboxScan: 0,

        cameraHeightEnabled: true,
        camera: null,
        cameraPath: null,
        cameraBaseEyeHeight: null,
        cameraHook: null,
        cameraHookDepth: 0,
        eyeHeightHook: null,
        lastCameraScan: 0,

        nameTagEnabled: true,
        nameTagObject: null,
        nameTagPath: null,
        nameTagBase: null,
        nameTagPatchedMesh: null,
        nameTagOffsetMethod: null,
        nameTagRenderMethod: null,
        nameTagOriginalOffsetFn: null,
        nameTagHadOwnOffset: false,
        nameTagOwnOffsetValue: undefined,
        nameTagCurrentOffset: null,
