    scanInterval: 120,
    maxItems: 240,
    airAngularDrag: 0.52,
    flatAirAngularDrag: 0.82,
    waterAngularDrag: 3.8,
    lavaAngularDrag: 5.6,
    groundAngularDrag: 8.2,
    flatGroundAngularDrag: 13.5,
    groundSettle: 13.5,
    flatGroundSettle: 20.0,
