  const FULLBRIGHT_SETTINGS_VERSION = 1;

  const GLOBAL_KEY = '__MINIFEATHER_FULLBRIGHT__';
  const EVENT_CONFIG = 'minifeather:fullbright-config';
  const DEFAULT_FLOOR = 0.16;
  const SCAN_INTERVAL_MS = 900;
