            position: 'fixed',
            left: '50%',
            top: '14%',
            transform: 'translate(-50%, -50%)',
            zIndex: '2147483647',
            padding: '8px 13px',
            borderRadius: '10px',
            background: 'rgba(10, 10, 13, .82)',
