                        [-d4, d4, 0],
                        [d4, -d4, 0],
                        [-d4, -d4, 0],

                        [0, d4, d4],
                        [0, -d4, d4],
                        [0, d4, -d4],
                        [0, -d4, -d4],

                        [d4, 0, d4],
                        [-d4, 0, d4],
                        [d4, 0, -d4],
                        [-d4, 0, -d4]
