                        [d5, d5, d5],
                        [-d5, d5, d5],
                        [d5, -d5, d5],
                        [-d5, -d5, d5],

                        [d5, d5, -d5],
                        [-d5, d5, -d5],
                        [d5, -d5, -d5],
                        [-d5, -d5, -d5]
