                        [d9, -d9, 0],
                        [-d9, -d9, 0],

                        [0, d9, d9],
                        [0, -d9, d9],
                        [0, d9, -d9],
                        [0, -d9, -d9],

                        [d9, 0, d9],
                        [-d9, 0, d9],
                        [d9, 0, -d9],
                        [-d9, 0, -d9]
