            const dtL = Math.max(0.001, Math.min(0.1, s2.frameTime || 0.05));
            const leanTarget = s2.sprinting ? -(18 * Math.PI / 180) : 0;
            const leanPrev = mesh.__mfSprintLean ?? 0;
