        nfpurk:      { key: 'uNfPurkinje', max: 1 },
        nffog:       { key: 'uNfFog',      max: 1 },
        nfnoise:     { key: 'uNfNoise',    max: 1 },
        nfstars:     { key: 'uNfStars',    max: 1 }
