/* ==== mf module: src/Experimental/Realistic/RealisticMode.js ==== */
(() => {
  'use strict';

  const REALISTIC_PLAYER_FEATURES_VERSION = 1;
  const W = globalThis;
  const EVENT_NAME = 'minifeather:realistic-config';
  try { W.MF_RealisticMode?.destroy?.(); } catch (_) {}

  const state = {
    enabled: false,
    level: 'medium',
    custom: null,
    skinLayers: true,
    armorRelief: true,
    firstPersonBody: true,
    adaptiveScale: 1,
    fpsEma: 60,
    lastFrameAt: 0,
    lastAdaptiveAt: 0,
    lastAdaptiveChangeAt: 0,
    profileCache: null,
    profileCacheLevel: '',
    profileCacheCustom: null,
    profileCacheScale: -1,
    wetDrySeconds: 180,
    game: null,
    lastGameMiss: 0,
    stars: new Map(),
    raf: 0,
    timer: 0,
    lastScan: 0,
    lastBiomeScan: 0,
    snowy: true,
    auroraApplied: null,
    baseLeafEnabled: false,
    baseLeafStrength: 0.085,
    baseAuroraEnabled: false,
    baseAuroraLevel: 'medium',
    fluidCount: 0,
    shadowMaterials: 0,
    destroyed: false
  };

  const profiles = () => W.MF_RealisticProfiles;
  function invalidateProfile() {
    state.profileCache = null;
    state.profileCacheLevel = '';
    state.profileCacheCustom = null;
    state.profileCacheScale = -1;
  }

  function currentProfile() {
    const source = profiles();
    if (!source?.get) return null;
    const scale = state.level === 'custom' ? state.adaptiveScale : 1;
    if (state.profileCache && state.profileCacheLevel === state.level && state.profileCacheScale === scale &&
        (state.level !== 'custom' || state.profileCacheCustom === state.custom)) return state.profileCache;
    state.profileCache = source.get(state.level, state.custom, scale);
    state.profileCacheLevel = state.level;
    state.profileCacheCustom = state.custom;
    state.profileCacheScale = scale;
    return state.profileCache;
  }

  function findGame() {
    if (state.game?.player && state.game?.world) return state.game;
    const now = performance.now();
    if (now - state.lastGameMiss < 1500) return null;
    state.lastGameMiss = now;
    for (const candidate of [W.__MINIBLOX_GAME__, W.miniblox, W.__MB?.game, W.game]) {
      if (candidate?.player && candidate?.world) return (state.game = candidate);
    }
    for (const root of [document.querySelector('#react'), document.querySelector('#root')]) {
      if (!root) continue;
      let keys = [];
      try { keys = Object.keys(root); } catch (_) {}
      for (const key of keys) {
        if (!key.startsWith('__react')) continue;
        const queue = [root[key]], seen = new Set();
        let visited = 0, head = 0;
        while (head < queue.length && visited++ < 1400) {
          const fiber = queue[head++];
          if (!fiber || seen.has(fiber)) continue;
          seen.add(fiber);
          for (const c of [fiber.stateNode, fiber.stateNode?.game, fiber.memoizedProps?.game, fiber.pendingProps?.game, fiber.memoizedState?.game]) {
            const g = c?.player && c?.world ? c : c?.game;
            if (g?.player && g?.world) {
              W.__MINIBLOX_GAME__ = g;
              return (state.game = g);
            }
          }
          if (fiber.child) queue.push(fiber.child);
          if (fiber.sibling) queue.push(fiber.sibling);
        }
      }
    }
    return null;
  }

  function collect(root, limit = 5000) {
    const out = [], queue = root ? [root] : [], seen = new WeakSet();
    let head = 0;
    while (head < queue.length && out.length < limit) {
      const o = queue[head++];
      if (!o || typeof o !== 'object' || seen.has(o)) continue;
      seen.add(o); out.push(o);
      if (Array.isArray(o.children)) for (const c of o.children) queue.push(c);
    }
    return out;
  }

  function scanFluids(game) {
    let count = 0;
    for (const o of collect(game?.gameScene?.scene)) {
      const list = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of list) if (W.MF_RealisticFluid?.isFluidMaterial?.(m) && W.MF_RealisticFluid.patch(m)) count++;
    }
    state.fluidCount = count;
  }

  function snapshotStars(game) {
    const p = currentProfile();
    if (!p) return;
    for (const root of [game?.gameScene?.stars, game?.gameScene?.sky?.stars].filter(Boolean)) {
      for (const o of collect(root, 500)) {
        for (const m of (Array.isArray(o.material) ? o.material : [o.material])) {
          if (!m || state.stars.has(m)) continue;
          state.stars.set(m, { opacity: m.opacity, size: m.size, toneMapped: m.toneMapped, color: m.color?.clone?.() || null });
          if (Number.isFinite(m.opacity)) m.opacity = Math.min(1, m.opacity * 1.12 + 0.05);
          if (Number.isFinite(m.size)) m.size *= p.starScale;
          if ('toneMapped' in m) m.toneMapped = false;
          m.needsUpdate = true;
        }
      }
    }
  }

  function restoreStars() {
    for (const [m, s] of state.stars) {
      try {
        if (s.opacity !== undefined) m.opacity = s.opacity;
        if (s.size !== undefined) m.size = s.size;
        if (s.toneMapped !== undefined) m.toneMapped = s.toneMapped;
        if (s.color && m.color?.copy) m.color.copy(s.color);
        m.needsUpdate = true;
      } catch (_) {}
    }
    state.stars.clear();
  }

  function emit(name, detail) {
    document.dispatchEvent(new CustomEvent(name, { detail: JSON.stringify(detail) }));
  }

  function applyCompanions(force = false) {
    const p = currentProfile();
    if (!p) return;
    emit('minifeather:leaf-wind-config', { enabled: state.enabled || state.baseLeafEnabled, strength: state.enabled ? p.leafWind : state.baseLeafStrength });
    const auroraEnabled = state.baseAuroraEnabled || (state.enabled && state.snowy);
    const auroraLevel = state.enabled ? ((state.level === 'ultra' || state.level === 'custom') ? 'high' : state.level) : state.baseAuroraLevel;
    const sig = `${auroraEnabled}:${auroraLevel}`;
    if (force || sig !== state.auroraApplied) {
      state.auroraApplied = sig;
      emit('minifeather:aurora-config', { enabled: auroraEnabled, level: auroraLevel });
    }
  }

  function applyPlayerFeatures() {
    W.MF_BetterPlayerLayers?.setRealisticOptions?.({ enabled: state.enabled && state.skinLayers });
    W.MF_BetterPlayerLayersArmor?.setRealisticOptions?.({ enabled: state.enabled && state.armorRelief });
    W.MF_RealisticFirstPerson?.configure?.({ enabled: state.enabled && state.firstPersonBody });
  }

  function playerPosition(game) {
    const p = game?.player?.pos || game?.player?.position || game?.player?.getPosition?.() || game?.player?.mesh?.position;
    if (!p) return null;
    const x = Number(p.x), y = Number(p.y), z = Number(p.z);
    return Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z) ? { x, y, z } : null;
  }

  function biomeValue(game, p) {
    for (const call of [
      () => game?.world?.getBiomeAt?.(p.x, p.y, p.z),
      () => game?.world?.getBiome?.(p.x, p.y, p.z),
      () => game?.world?.getChunk?.(p)?.getBiomeAt?.(p.x, p.y, p.z),
      () => game?.world?.getChunkAt?.(p.x, p.z)?.getBiomeAt?.(p.x, p.y, p.z)
    ]) {
      try { const v = call(); if (v !== undefined && v !== null) return v; } catch (_) {}
    }
    return null;
  }

  function isSnowBiome(v) {
    if (v == null) return null;
    let text = '';
    if (typeof v === 'string' || typeof v === 'number') text = String(v);
    else try { text = `${v.name || ''} ${v.id || ''} ${v.key || ''} ${JSON.stringify(v)}`; } catch (_) {}
    return text.trim() ? /snow|ice|frozen|tundra|taiga|glacier|polar|alpine|frigid/i.test(text) : null;
  }

  function customDrySeconds(p) {
    return state.level === 'custom' ? (p?.wetness?.drySeconds || state.wetDrySeconds) : state.wetDrySeconds;
  }

  function applyProfile() {
    const p = currentProfile();
    if (!p) return;
    W.MF_RealisticFluid?.setProfile?.(p);
    W.MF_RealisticClouds?.setProfile?.(p);
    W.MF_RealisticShadowFilter?.setProfile?.(p);
    W.MF_RealisticWetness?.enable?.();
    W.MF_RealisticWetness?.setProfile?.(p, customDrySeconds(p));
    const game = findGame();
    if (game) {
      W.MF_RealisticShadows?.apply?.(game, p);
      if (state.level === 'custom') W.MF_RealisticRenderDistance?.apply?.(game, p.world?.renderBlocks || 96);
      else W.MF_RealisticRenderDistance?.restore?.();
    }
  }

  function scan(force = false) {
    if (!state.enabled) return;
    const now = performance.now();
    if (!force && now - state.lastScan < 1800) return;
    state.lastScan = now;
    applyPlayerFeatures();
    const game = findGame();
    const p = currentProfile();
    if (!game || !p) return;
    W.MF_RealisticFluid?.setProfile?.(p);
    W.MF_RealisticClouds?.setProfile?.(p);
    W.MF_RealisticShadowFilter?.setProfile?.(p);
    W.MF_RealisticWetness?.setProfile?.(p, customDrySeconds(p));
    scanFluids(game);
    state.shadowMaterials = W.MF_RealisticShadowFilter?.scan?.(game) || 0;
    W.MF_RealisticClouds?.scan?.(game);
    W.MF_RealisticWetness?.scan?.(game);
    W.MF_RealisticShadows?.apply?.(game, p);
    if (state.level === 'custom') W.MF_RealisticRenderDistance?.apply?.(game, p.world?.renderBlocks || 96);
    snapshotStars(game);
  }

  function updateAdaptive(now) {
    if (state.level !== 'custom' || !(state.custom?.optimizeFps ?? state.custom?.adaptive)) {
      if (state.adaptiveScale !== 1) {
        state.adaptiveScale = 1;
        invalidateProfile();
        applyProfile();
      }
      return;
    }
    if (now - state.lastAdaptiveAt < 1500) return;
    state.lastAdaptiveAt = now;
    const target = Math.max(30, Math.min(144, Number(state.custom.targetFps) || 60));
    const fps = state.fpsEma;
    let next = state.adaptiveScale;

    if (fps < target * 0.78) next -= 0.12;
    else if (fps < target * 0.90) next -= 0.06;
    else if (fps > target * 1.08 && now - state.lastAdaptiveChangeAt > 3500) next += 0.035;
    else return;

    next = Math.max(0.40, Math.min(1, next));
    if (Math.abs(next - state.adaptiveScale) < 0.02) return;
    state.adaptiveScale = next;
    state.lastAdaptiveChangeAt = now;
    invalidateProfile();
    applyProfile();
  }

  function tick(now) {
    if (!state.enabled || state.destroyed) return void (state.raf = 0);
    if (state.lastFrameAt) {
      const dt = Math.max(1, now - state.lastFrameAt);
      const fps = Math.min(240, 1000 / dt);
      state.fpsEma += (fps - state.fpsEma) * 0.06;
    }
    state.lastFrameAt = now;
    updateAdaptive(now);
    const game = findGame();
    const p = currentProfile();
    if (game && p) {
      W.MF_RealisticShadows?.update?.(game, p);
      W.MF_RealisticWetness?.update?.(game, now);
    }
    if (now - state.lastBiomeScan > 2500) {
      state.lastBiomeScan = now;
      const pos = playerPosition(game);
      if (game && pos) {
        const snowy = isSnowBiome(biomeValue(game, pos));
        if (snowy !== null && snowy !== state.snowy) { state.snowy = snowy; applyCompanions(); }
      }
    }
    state.raf = requestAnimationFrame(tick);
  }

  function setEnabled(value) {
    const next = !!value;
    if (state.enabled === next) {
      applyPlayerFeatures();
      applyCompanions(true);
      return;
    }
    state.enabled = next;
    applyPlayerFeatures();
    if (next) {
      state.lastFrameAt = 0;
      applyProfile(); scan(true); applyCompanions(true);
      if (!state.raf) state.raf = requestAnimationFrame(tick);
      if (!state.timer) state.timer = setInterval(scan, 2200);
    } else {
      if (state.raf) cancelAnimationFrame(state.raf);
      state.raf = 0;
      if (state.timer) { clearInterval(state.timer); state.timer = 0; }
      W.MF_RealisticFluid?.restore?.();
      W.MF_RealisticClouds?.restore?.();
      W.MF_RealisticWetness?.restore?.();
      W.MF_RealisticShadowFilter?.restore?.();
      W.MF_RealisticShadows?.restore?.();
      W.MF_RealisticRenderDistance?.restore?.();
      restoreStars(); applyCompanions(true);
    }
  }

  function configure(detail) {
    let c = detail;
    if (typeof c === 'string') try { c = JSON.parse(c); } catch (_) { return; }
    if (!c || typeof c !== 'object') return;

    const wasEnabled = state.enabled;
    if ('skinLayers' in c) state.skinLayers = !!c.skinLayers;
    if ('armorRelief' in c) state.armorRelief = !!c.armorRelief;
    if ('firstPersonBody' in c) state.firstPersonBody = !!c.firstPersonBody;
    state.level = profiles()?.normalizeLevel?.(c.level) || 'medium';
    state.custom = profiles()?.clampCustom?.(c.custom || state.custom || {}) || c.custom || null;
    if (!(state.custom?.optimizeFps ?? state.custom?.adaptive)) state.adaptiveScale = 1;
    invalidateProfile();

    const profile = currentProfile();
    state.wetDrySeconds = Math.max(10, Math.min(900, Number(c.wetDrySeconds) || profile?.wetness?.drySeconds || 180));
    if (state.level === 'custom' && state.custom) {
      state.custom.drySeconds = Math.max(10, Math.min(900, Number(state.custom.drySeconds) || state.wetDrySeconds));
      invalidateProfile();
    }
    state.baseLeafEnabled = !!c.leafEnabled;
    state.baseLeafStrength = Math.max(0, Math.min(1, Number(c.leafStrength) || 0.085));
    state.baseAuroraEnabled = !!c.auroraEnabled;
    state.baseAuroraLevel = ['low', 'medium', 'high'].includes(String(c.auroraLevel)) ? String(c.auroraLevel) : 'medium';

    setEnabled(!!c.enabled);
    if (wasEnabled && state.enabled) {
      applyProfile();
      applyCompanions(true);
    }
  }

  function destroy() {
    if (state.destroyed) return;
    setEnabled(false); state.destroyed = true;
    document.removeEventListener(EVENT_NAME, onConfig, true);
    if (state.timer) clearInterval(state.timer);
    try { delete W.MF_RealisticMode; } catch (_) {}
  }

  function onConfig(e) { configure(e.detail); }
  document.addEventListener(EVENT_NAME, onConfig, true);

  W.MF_RealisticMode = Object.freeze({
    configure, setEnabled, destroy,
    getState: () => ({
      enabled: state.enabled, level: state.level, optimizeFps: !!(state.custom?.optimizeFps ?? state.custom?.adaptive), targetFps: Math.round(Number(state.custom?.targetFps) || 60), adaptiveScale: state.adaptiveScale, fps: Math.round(state.fpsEma),
      fluids: state.fluidCount, shadowMaterials: state.shadowMaterials, clouds: W.MF_RealisticClouds?.count?.() || 0,
      renderDistance: W.MF_RealisticRenderDistance?.getState?.() || null,
      playerFeatures: {
        skinLayers: state.enabled && state.skinLayers,
        armorRelief: state.enabled && state.armorRelief,
        firstPersonBody: state.enabled && state.firstPersonBody
      },
      wetness: W.MF_RealisticWetness?.getState?.() || null, stars: state.stars.size, snowy: state.snowy
    })
  });
})();

