/* ==== mf module: src/Studio/MF_SkinEditor.js ==== */

(function () {
    'use strict';
    if (window.__MF_SkinEditor) return;
    const TAG = 'minifeather skineditor';

    const HEAD = { x: 0, y: 0, w: 64, h: 16 };
    const OVERLAY_X = 32;

    const BODY_PARTS = [
        { n: 'cabeza', base: { x: 0, y: 0, w: 32, h: 16 } },
        { n: 'cuerpo', base: { x: 16, y: 16, w: 24, h: 16 } },
        { n: 'brazo D', base: { x: 40, y: 16, w: 16, h: 16 } },
        { n: 'brazo I', base: { x: 32, y: 48, w: 16, h: 16 } },
        { n: 'pierna D', base: { x: 0, y: 16, w: 16, h: 16 } },
        { n: 'pierna I', base: { x: 16, y: 48, w: 16, h: 16 } }
    ];
    const LS_KEY = 'minifeather_headskins_v1';
    const ID = 'mf-skineditor';

    const REGIONS = [
        { n: 'arriba', x: 8, y: 0, ov: 40 }, { n: 'abajo', x: 16, y: 0, ov: 48 },
        { n: 'der', x: 0, y: 8, ov: 32 }, { n: 'CARA', x: 8, y: 8, ov: 40 },
        { n: 'izq', x: 16, y: 8, ov: 48 }, { n: 'atrás', x: 24, y: 8, ov: 56 }
    ];

    const state = {
        open: false,
        mode: 'head',

        zoom: 10,

        tool: 'pencil',

        color: '#1a1a1a',
        brush: 1,
        grid: true,
        layer: 'both',

        mats: [],

        orig: new Map(),

        tex: null, texCanvas: null,
        watchdog: null,
        undo: [], redo: [],
        painting: false, lastCell: null,
        p2pCells: []

    };

    function zone() {
        if (state.mode === 'full') {
            const c = state.texCanvas;
            const w = c ? c.width : 64, h = c ? c.height : 64;
            return { x: 0, y: 0, w, h };
        }
        return HEAD;
    }

    function getGame() {
        if (globalThis.miniblox?.player) return globalThis.miniblox;
        try {
            const react = document.querySelector('#react');
            if (react) for (const root of Object.values(react)) {
                const g = root?.updateQueue?.baseState?.element?.props?.game;
                if (g?.player) return g;
            }
        } catch {}
        return null;
    }

    function getMesh() {
        const g = getGame();
        const me = g?.player;
        if (!me) return null;
        try { const e = g.world?.getPlayerById?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        try { const e = g.world?.players?.get?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        try { const e = g.world?.entities?.get?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        return me?.mesh || null;
    }

    function skinCanvasFromTexture(tex) {
        const img = tex?.image;
        if (!img) return null;
        if (img instanceof HTMLCanvasElement) return img;
        try {
            if ((img instanceof HTMLImageElement) && img.complete && img.naturalWidth) {
                const c = document.createElement('canvas');
                c.width = img.naturalWidth; c.height = img.naturalHeight;
                c.getContext('2d').drawImage(img, 0, 0);
                return c;
            }
            if (typeof ImageBitmap !== 'undefined' && img instanceof ImageBitmap) {
                const c = document.createElement('canvas');
                c.width = img.width; c.height = img.height;
                c.getContext('2d').drawImage(img, 0, 0);
                return c;
            }
        } catch {}
        return null;
    }

    function findSkinMaterials(mesh) {
        const out = [];
        if (!mesh) return out;
        const seen = new Set();
        mesh.traverse(o => {
            if (!o?.material) return;
            const list = Array.isArray(o.material) ? o.material : [o.material];
            for (const m of list) {
                if (m?.map && !seen.has(m)) { seen.add(m); out.push(m); }
            }
        });

        const skins = out.filter(m => {
            const w = m.map?.image?.width, h = m.map?.image?.height;
            return w === 64 && (h === 64 || h === 32);
        });
        return skins.length ? skins : out;
    }

    function ensureWorkCanvas() {
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador no disponible (entra al mundo primero)');

        if (state.tex?.userData?.__mfSkinEditor && state.texCanvas) {
            const mats = findSkinMaterials(mesh);
            const alive = mats.some(m => m.map === state.tex);
            if (alive) { state.mats = mats; return true; }

            for (const m of mats) { state.orig.set(m, m.map); m.map = state.tex; m.needsUpdate = true; }
            state.mats = mats;
            startWatchdog();
            return true;
        }

        const mats = findSkinMaterials(mesh);
        if (!mats.length) throw new Error('no se encontró material de skin');
        const src = mats[0].map;
        const base = skinCanvasFromTexture(src);
        if (!base) throw new Error('no se pudo leer la skin actual');

        const c = document.createElement('canvas');
        c.width = base.width; c.height = base.height;
        c.getContext('2d', { willReadFrequently: true }).drawImage(base, 0, 0);

        let tex = null;
        try { tex = new src.constructor(c); } catch {}
        if (!tex) {
            try {
                tex = new src.constructor();
                tex.image = c;
            } catch { throw new Error('no se pudo crear textura editable'); }
        }
        try {
            tex.magFilter = src.magFilter;
            tex.minFilter = src.minFilter;
            if (src.colorSpace !== undefined && 'colorSpace' in tex) tex.colorSpace = src.colorSpace;
            tex.flipY = src.flipY;
            tex.wrapS = src.wrapS; tex.wrapT = src.wrapT;
            tex.repeat?.copy?.(src.repeat);
            tex.offset?.copy?.(src.offset);
        } catch {}
        tex.userData = { __mfSkinEditor: true };
        tex.__mfLocalCanvas = true;
        tex.needsUpdate = true;

        state.orig.clear();
        for (const m of mats) { state.orig.set(m, m.map); m.map = tex; m.needsUpdate = true; }
        state.mats = mats; state.tex = tex; state.texCanvas = c;
        startWatchdog();
        return true;
    }

    function startWatchdog() {
        stopWatchdog();
        state.watchdog = setInterval(() => {
            if (!state.tex) return;
            const mesh = getMesh();
            if (!mesh) return;
            const mats = findSkinMaterials(mesh);
            let rebind = 0;
            for (const m of mats) {
                if (m.map !== state.tex) {
                    if (!state.orig.has(m)) state.orig.set(m, m.map);
                    m.map = state.tex;
                    m.needsUpdate = true;
                    rebind++;
                }
            }
            state.mats = mats;
            if (rebind) renderUI();
        }, 250);
    }

    function stopWatchdog() {
        if (state.watchdog) { clearInterval(state.watchdog); state.watchdog = null; }
    }

    function layerAllows(sx) {
        if (state.mode === 'full') return true;
        if (state.layer === 'both') return true;
        return state.layer === 'base' ? sx < OVERLAY_X : sx >= OVERLAY_X;
    }

    function inZone(x, y) {
        const z = zone();
        return x >= z.x && y >= z.y && x < z.x + z.w && y < z.y + z.h;
    }

    function paintCell(sx, sy, erase) {
        if (!state.texCanvas || !state.tex) return;
        const ctx = state.texCanvas.getContext('2d');
        const b = state.brush;
        for (let i = 0; i < b; i++) {
            for (let j = 0; j < b; j++) {
                const x = sx + i, y = sy + j;
                if (!inZone(x, y) || !layerAllows(x)) continue;
                if (erase) ctx.clearRect(x, y, 1, 1);
                else { ctx.fillStyle = state.color; ctx.fillRect(x, y, 1, 1); }

                state.p2pCells.push([x, y, erase ? null : state.color]);
            }
        }
        state.tex.needsUpdate = true;
    }

    function floodFill(sx, sy) {
        if (!state.texCanvas || !state.tex || !inZone(sx, sy) || !layerAllows(sx)) return;
        const Z = zone();
        const ctx = state.texCanvas.getContext('2d');
        const img = ctx.getImageData(Z.x, Z.y, Z.w, Z.h);
        const d = img.data;
        const W = Z.w, H = Z.h;
        const idx = (x, y) => (y * W + x) * 4;
        const lx = sx - Z.x, ly = sy - Z.y;
        const t = idx(lx, ly);
        const tr = d[t], tg = d[t + 1], tb = d[t + 2], ta = d[t + 3];

        const hex = state.color.replace('#', '');
        const fr = parseInt(hex.substr(0, 2), 16), fg = parseInt(hex.substr(2, 2), 16), fb = parseInt(hex.substr(4, 2), 16);
        if (tr === fr && tg === fg && tb === fb && ta === 255) return;
        const stack = [[lx, ly]];
        while (stack.length) {
            const [x, y] = stack.pop();
            if (x < 0 || y < 0 || x >= W || y >= H) continue;
            const sxTex = x + Z.x;
            if (!layerAllows(sxTex)) continue;
            const i = idx(x, y);
            if (d[i] !== tr || d[i + 1] !== tg || d[i + 2] !== tb || d[i + 3] !== ta) continue;
            d[i] = fr; d[i + 1] = fg; d[i + 2] = fb; d[i + 3] = 255;
            stack.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
        }
        ctx.putImageData(img, Z.x, Z.y);
        state.tex.needsUpdate = true;

        emitZoneRect();
    }

    function pickColorAt(sx, sy) {
        if (!state.texCanvas || !inZone(sx, sy)) return null;
        const d = state.texCanvas.getContext('2d').getImageData(sx, sy, 1, 1).data;
        if (d[3] === 0) return null;
        const h = (v) => v.toString(16).padStart(2, '0');
        return '#' + h(d[0]) + h(d[1]) + h(d[2]);
    }

    function snapshot() {
        if (!state.texCanvas) return;
        const Z = zone();
        const ctx = state.texCanvas.getContext('2d');
        state.undo.push(ctx.getImageData(Z.x, Z.y, Z.w, Z.h));
        if (state.undo.length > 40) state.undo.shift();
        state.redo.length = 0;
    }
    function restoreFrom(stackA, stackB) {
        if (!state.texCanvas || !stackA.length) return;
        const Z = zone();
        const ctx = state.texCanvas.getContext('2d');
        stackB.push(ctx.getImageData(Z.x, Z.y, Z.w, Z.h));
        ctx.putImageData(stackA.pop(), Z.x, Z.y);
        state.tex.needsUpdate = true;

        emitZoneRect();
    }

    function emitZoneRect() {
        try {
            if (!state.texCanvas) return;
            if (state.mode === 'full') {
                window.MF_Peer?.sendLook?.({ a: 'skin', name: 'edit', dataURL: state.texCanvas.toDataURL('image/png') });
            } else {
                const c = document.createElement('canvas');
                c.width = HEAD.w; c.height = HEAD.h;
                c.getContext('2d').drawImage(state.texCanvas, HEAD.x, HEAD.y, HEAD.w, HEAD.h, 0, 0, HEAD.w, HEAD.h);
                window.MF_Peer?.sendLook?.({ a: 'head-rect', png: c.toDataURL() });
            }
        } catch {}
    }

    function lineCells(x0, y0, x1, y1, cb) {
        const dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
        const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
        let err = dx - dy;
        for (;;) {
            cb(x0, y0);
            if (x0 === x1 && y0 === y1) break;
            const e2 = 2 * err;
            if (e2 > -dy) { err -= dy; x0 += sx; }
            if (e2 < dx) { err += dx; y0 += sy; }
        }
    }

    const W = () => zone().w * state.zoom;
    const H = () => zone().h * state.zoom;

    function resizeCanvasUI() {
        const cv = document.querySelector('#' + ID + ' canvas.mfse-cv');
        if (!cv) return;
        cv.width = W(); cv.height = H();

        cv.style.maxHeight = '60vh';
        cv.style.width = 'auto';
        renderUI();
    }

    function setMode(m) {
        if (state.mode === m) return;
        state.mode = m;
        state.undo.length = 0; state.redo.length = 0;
        document.querySelectorAll('#' + ID + ' [data-mode]').forEach(b =>
            b.classList.toggle('on', b.dataset.mode === m));
        const lay = document.querySelector('#' + ID + ' [data-row="layers"]');
        if (lay) lay.style.display = (m === 'full') ? 'none' : 'flex';
        resizeCanvasUI();
    }

    function buildUI() {
        if (document.getElementById(ID)) return;
        const style = document.createElement('style');
        style.id = ID + '-style';
        style.textContent = `
            #${ID} { position:fixed; top:70px; right:16px; z-index:2147483000;
  background:#14141a; border:1px solid #32323a; border-radius:8px;
  box-shadow:0 8px 32px rgba(0,0,0,.6); color:#e8e8ee;
  font:12px/1.4 system-ui,sans-serif; user-select:none; }
  #${ID} .mfse-head { display:flex; align-items:center; gap:8px; padding:8px 10px;
  border-bottom:1px solid #26262e; font-weight:700; letter-spacing:.5px; }
  #${ID} .mfse-head .dot { width:8px; height:8px; border-radius:50%;
  background:#4dff88; animation:mfse-pulse 1.5s infinite; }
  @keyframes mfse-pulse { 50% { opacity:.35; } }
  #${ID} .mfse-head button { margin-left:auto; }
  #${ID} .mfse-row { display:flex; align-items:center; gap:6px; padding:6px 10px; flex-wrap:wrap; }
  #${ID} .mfse-row + .mfse-row { border-top:1px solid #202028; }
  #${ID} canvas.mfse-cv { display:block; margin:6px 10px; border:1px solid #32323a;
  image-rendering:pixelated; cursor:crosshair; background:#0c0c10; }
  #${ID} button { background:#23232c; color:#e8e8ee; border:1px solid #3a3a44;
  border-radius:4px; padding:3px 8px; cursor:pointer; font:inherit; }
  #${ID} button:hover { background:#2e2e3a; }
  #${ID} button.on { background:#ff6b2b; color:#14141a; border-color:#ff6b2b; font-weight:700; }
  #${ID} input[type=color] { width:34px; height:24px; padding:0; border:1px solid #3a3a44;
  border-radius:4px; background:none; cursor:pointer; }
  #${ID} select { background:#23232c; color:#e8e8ee; border:1px solid #3a3a44;
  border-radius:4px; padding:3px; font:inherit; max-width:130px; }
  #${ID} label { color:#9a9aa6; }
  #${ID} .mfse-err { color:#ff7d7d; padding:4px 10px; display:none; }
        `;
        const root = document.createElement('div');
        root.id = ID;
        root.innerHTML = `
            <div class="mfse-head"><span class="dot"></span>🎨 EDITOR DE SKIN — en vivo
    <button data-act="close" title="Cerrar (el dibujo se mantiene)">✕</button></div>
        <canvas class="mfse-cv" width="${W()}" height="${H()}" style="max-height:60vh;width:auto;"></canvas>
            <div class="mfse-row" data-row="mode">
    <label>Modo:</label>
    <button data-mode="head" class="on" title="Editar solo la cabeza (64x16), con filtro de capa">Cabeza</button>
    <button data-mode="full" title="Editar la skin completa: cuerpo, brazos, piernas">Skin completa</button>
        </div>
            <div class="mfse-row" data-row="tools">
    <button data-tool="pencil" class="on" title="Lápiz">✏️</button>
    <button data-tool="eraser" title="Borrador (transparente)">🧽</button>
    <button data-tool="picker" title="Cuentagotas">💧</button>
    <button data-tool="fill" title="Relleno">🪣</button>
    <input type="color" value="${state.color}" title="Color">
    <span title="Tamaño de pincel">Pincel
        <button data-brush="1" class="on">1</button>
        <button data-brush="2">2</button>
        <button data-brush="3">3</button>
    </span>
    <button data-act="undo" title="Deshacer">↩</button>
    <button data-act="redo" title="Rehacer">↪</button>
        </div>
            <div class="mfse-row" data-row="layers">
    <label>Capa:</label>
    <button data-layer="both" class="on">Ambas</button>
    <button data-layer="base" title="La de abajo del overlay">Base</button>
    <button data-layer="overlay" title="Hat layer">Overlay</button>
    <button data-act="grid" class="on" title="Rejilla">▦</button>
        </div>
            <div class="mfse-row" data-row="files">
    <button data-act="revert" title="Volver a la skin original (sin ediciones)">↺ Skin original</button>
    <button data-act="save" title="Guardar el dibujo de cabeza como preset">💾 Guardar</button>
    <select id="mfse-preset"><option value="">— presets —</option></select>
    <button data-act="apply" title="Aplicar preset">Aplicar</button>
    <button data-act="delete" title="Borrar preset">🗑</button>
    <button data-act="export" title="Descargar PNG de la cabeza">⬇ PNG</button>
        </div>
            <div class="mfse-row" data-row="live">
    <span style="font-size:10px;color:#8a8a96;">Arrastra al timeline (V2):</span>
    <img id="mfse-live-thumb" draggable="true" title="Cabeza ACTUAL (con tus ediciones) — arrástrala al timeline como clip"
         style="height:26px;image-rendering:pixelated;cursor:grab;border:1px solid #32323a;border-radius:3px;background:#0c0c10;">
             </div>
                 <div class="mfse-err" id="mfse-err"></div>
        `;
        document.body.appendChild(style);
        document.body.appendChild(root);
        bindUI(root);
    }

    function err(msg) {
        const e = document.getElementById('mfse-err');
        if (!e) return;
        e.textContent = msg;
        e.style.display = msg ? 'block' : 'none';
    }

    function bindUI(root) {

        const setActive = (sel, btn) => {
            root.querySelectorAll(sel).forEach(b => b.classList.toggle('on', b === btn));
        };
        root.querySelectorAll('[data-mode]').forEach(b => b.onclick = () => setMode(b.dataset.mode));
        root.querySelectorAll('[data-tool]').forEach(b => b.onclick = () => {
            state.tool = b.dataset.tool;
            setActive('[data-tool]', b);
        });
        root.querySelectorAll('[data-brush]').forEach(b => b.onclick = () => {
            state.brush = +b.dataset.brush;
            setActive('[data-brush]', b);
        });
        root.querySelectorAll('[data-layer]').forEach(b => b.onclick = () => {
            state.layer = b.dataset.layer;
            setActive('[data-layer]', b);
        });
        const colorInput = root.querySelector('input[type=color]');
        colorInput.oninput = () => { state.color = colorInput.value; };

        root.querySelectorAll('[data-act]').forEach(b => b.onclick = () => {
            switch (b.dataset.act) {
                case 'close': close(); break;
                case 'undo': restoreFrom(state.undo, state.redo); renderUI(); break;
                case 'redo': restoreFrom(state.redo, state.undo); renderUI(); break;
                case 'grid': state.grid = !state.grid; b.classList.toggle('on', state.grid); renderUI(); break;
                case 'revert': revert(); renderUI(); break;
                case 'save': savePreset(); break;
                case 'apply': applyPresetSel(); break;
                case 'delete': deletePresetSel(); break;
                case 'export': exportPNG(); break;
            }
        });

        const thumb = root.querySelector('#mfse-live-thumb');
        if (thumb) {
            thumb.addEventListener('dragstart', (ev) => {
                if (!state.texCanvas) return;
                thumb.dataset.dragging = '1';

                const c = document.createElement('canvas');
                c.width = HEAD.w; c.height = HEAD.h;
                const cx = c.getContext('2d');
                cx.imageSmoothingEnabled = false;
                cx.drawImage(state.texCanvas, HEAD.x, HEAD.y, HEAD.w, HEAD.h, 0, 0, HEAD.w, HEAD.h);
                const name = 'live-' + Date.now().toString(36);
                try {
                    const p = loadPresets();
                    p[name] = c.toDataURL('image/png');
                    storePresets(p);
                } catch { ev.preventDefault(); return; }
                ev.dataTransfer.setData('text/mf-head', name);
                ev.dataTransfer.setData('text/plain', name);
                ev.dataTransfer.effectAllowed = 'copy';

                try { ev.dataTransfer.setDragImage(thumb, 13, 13); } catch {}
            });
            thumb.addEventListener('dragend', () => { delete thumb.dataset.dragging; });
        }

        const cv = root.querySelector('canvas.mfse-cv');
        const cellOf = (e) => {
            const Z = zone();
            const r = cv.getBoundingClientRect();
            const x = Math.floor((e.clientX - r.left) / (r.width / Z.w));
            const y = Math.floor((e.clientY - r.top) / (r.height / Z.h));
            return { x: x + Z.x, y: y + Z.y };
        };
        cv.addEventListener('pointerdown', (e) => {
            e.preventDefault();
            const { x, y } = cellOf(e);
            if (!inZone(x, y)) return;
            if (state.tool === 'picker') {
                const c = pickColorAt(x, y);
                if (c) { state.color = c; colorInput.value = c; err(''); }
                else err('píxel transparente');
                return;
            }
            snapshot();
            if (state.tool === 'fill') { floodFill(x, y); renderUI(); return; }
            state.painting = true;
            state.lastCell = { x, y };
            cv.setPointerCapture(e.pointerId);
            paintCell(x, y, state.tool === 'eraser');
            renderUI();
        });
        cv.addEventListener('pointermove', (e) => {
            if (!state.painting) return;
            const { x, y } = cellOf(e);
            const l = state.lastCell;
            if (l && (l.x !== x || l.y !== y)) {
                lineCells(l.x, l.y, x, y, (cx, cy) => paintCell(cx, cy, state.tool === 'eraser'));
                state.lastCell = { x, y };
                renderUI();
            }
        });
        const stop = () => {
            state.painting = false;
            state.lastCell = null;

            if (state.p2pCells.length) {
                try {
                    window.MF_Peer?.sendLook?.({
                        a: 'stroke',
                        cells: state.p2pCells.length > 400 ? state.p2pCells.slice(-400) : state.p2pCells
                    });
                } catch {}
                state.p2pCells = [];
            }
        };
        cv.addEventListener('pointerup', stop);
        cv.addEventListener('pointercancel', stop);
    }

    function renderUI() {
        const cv = document.querySelector('#' + ID + ' canvas.mfse-cv');
        if (!cv || !state.texCanvas) return;
        const ctx = cv.getContext('2d');
        const Z = zone();
        const z = state.zoom, w = W(), h = H();
        ctx.imageSmoothingEnabled = false;

        for (let y = 0; y < h; y += 8) {
            for (let x = 0; x < w; x += 8) {
                ctx.fillStyle = ((x / 8 + y / 8) % 2) ? '#1b1b22' : '#22222b';
                ctx.fillRect(x, y, 8, 8);
            }
        }

        ctx.drawImage(state.texCanvas, Z.x, Z.y, Z.w, Z.h, 0, 0, w, h);

        if (state.grid) {
            ctx.strokeStyle = 'rgba(255,255,255,.06)';
            ctx.beginPath();
            for (let x = 0; x <= w; x += z) { ctx.moveTo(x + .5, 0); ctx.lineTo(x + .5, h); }
            for (let y = 0; y <= h; y += z) { ctx.moveTo(0, y + .5); ctx.lineTo(w, y + .5); }
            ctx.stroke();
        }

        if (state.mode === 'full') {

            ctx.font = '9px system-ui';
            for (const p of BODY_PARTS) {
                for (const ox of [0, 32]) {
                    const r = p.base;
                    if (r.x + ox + r.w > Z.w) continue;
                    ctx.strokeStyle = 'rgba(255,255,255,.28)';
                    ctx.strokeRect(r.x * z + .5, r.y * z + .5, r.w * z - 1, r.h * z - 1);
                    ctx.fillStyle = 'rgba(0,0,0,.55)';
                    ctx.fillRect(r.x * z + 1, r.y * z + 1, p.n.length * 5.5 + 4, 11);
                    ctx.fillStyle = '#c8c8d2';
                    ctx.fillText(p.n, r.x * z + 3, r.y * z + 10);
                }
            }
        } else {

            ctx.strokeStyle = 'rgba(255,255,255,.28)';
            ctx.beginPath();
            for (const gx of [0, 8, 16, 24, 40, 48, 56, 64]) { ctx.moveTo(gx * z + .5, 0); ctx.lineTo(gx * z + .5, h); }
            for (const gy of [0, 8, 16]) { ctx.moveTo(0, gy * z + .5); ctx.lineTo(w, gy * z + .5); }
            ctx.stroke();

            ctx.strokeStyle = '#ff6b2b';
            ctx.setLineDash([4, 3]);
            ctx.beginPath();
            ctx.moveTo(OVERLAY_X * z + .5, 0); ctx.lineTo(OVERLAY_X * z + .5, h);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.font = '9px system-ui';
            for (const r of REGIONS) {
                for (const rx of [r.x, r.ov]) {
                    const isCara = r.n === 'CARA';
                    ctx.fillStyle = isCara ? 'rgba(255,107,43,.9)' : 'rgba(0,0,0,.55)';
                    ctx.fillRect(rx * z + 1, (r.y === 0 ? 0 : 8 * z) + 1, r.n.length * 5.5 + 4, 11);
                    ctx.fillStyle = isCara ? '#14141a' : '#c8c8d2';
                    ctx.fillText(r.n, rx * z + 3, (r.y === 0 ? 0 : 8 * z) + 10);
                }
            }
        }

        updateLiveThumb();
    }

    function updateLiveThumb() {
        const thumb = document.getElementById('mfse-live-thumb');
        if (!thumb || !state.texCanvas) return;

        if (thumb.dataset.dragging === '1') return;
        const c = document.createElement('canvas');
        c.width = HEAD.w; c.height = HEAD.h;
        const cx = c.getContext('2d');
        cx.imageSmoothingEnabled = false;
        cx.drawImage(state.texCanvas, HEAD.x, HEAD.y, HEAD.w, HEAD.h, 0, 0, HEAD.w, HEAD.h);
        thumb.src = c.toDataURL('image/png');
    }

    function loadPresets() {
        try { return JSON.parse(localStorage.getItem(LS_KEY) || '{}'); } catch { return {}; }
    }
    function storePresets(p) {
        try { localStorage.setItem(LS_KEY, JSON.stringify(p)); } catch (e) { err('no se pudo guardar: ' + e.message); }
    }
    function refreshPresetList() {
        const sel = document.getElementById('mfse-preset');
        if (!sel) return;
        const names = Object.keys(loadPresets());
        sel.innerHTML = '<option value="">— presets —</option>' +
            names.map(n => `<option value="${n}">${n}</option>`).join('');
    }
    function savePreset() {
        if (!state.texCanvas) return;
        const name = prompt('Nombre del preset de cabeza:', 'cabeza-' + (Object.keys(loadPresets()).length + 1));
        if (!name) return;

        const c = document.createElement('canvas');
        c.width = HEAD.w; c.height = HEAD.h;
        c.getContext('2d').drawImage(state.texCanvas, HEAD.x, HEAD.y, HEAD.w, HEAD.h, 0, 0, HEAD.w, HEAD.h);
        const p = loadPresets();
        p[name] = c.toDataURL('image/png');
        storePresets(p);
        refreshPresetList();

        window.dispatchEvent(new CustomEvent('mf:skineditor-presets'));
        err('');
    }
    function applyPresetSel() {
        const sel = document.getElementById('mfse-preset');
        const name = sel?.value;
        if (!name) { err('elige un preset primero'); return; }
        const data = loadPresets()[name];
        if (!data) return;
        const img = new Image();
        img.onload = () => {
            if (!state.texCanvas) return;
            snapshot();
            const ctx = state.texCanvas.getContext('2d');
            ctx.clearRect(HEAD.x, HEAD.y, HEAD.w, HEAD.h);
            ctx.imageSmoothingEnabled = false;
            ctx.drawImage(img, 0, 0, img.width, img.height, HEAD.x, HEAD.y, HEAD.w, HEAD.h);
            state.tex.needsUpdate = true;
            emitZoneRect();
            renderUI();
        };
        img.src = data;
    }
    function deletePresetSel() {
        const sel = document.getElementById('mfse-preset');
        const name = sel?.value;
        if (!name) return;
        const p = loadPresets();
        delete p[name];
        storePresets(p);
        refreshPresetList();
        window.dispatchEvent(new CustomEvent('mf:skineditor-presets'));
    }
    function exportPNG() {
        if (!state.texCanvas) return;
        const a = document.createElement('a');
        const c = document.createElement('canvas');
        c.width = HEAD.w; c.height = HEAD.h;
        c.getContext('2d').drawImage(state.texCanvas, HEAD.x, HEAD.y, HEAD.w, HEAD.h, 0, 0, HEAD.w, HEAD.h);
        a.href = c.toDataURL('image/png');
        a.download = 'mf-cabeza-' + Date.now() + '.png';
        a.click();
    }

    function listPresets() {
        const p = loadPresets();
        return Object.entries(p).map(([name, dataURL]) => ({ name, thumb: dataURL }));
    }

    function applyPresetByName(name) {
        const data = loadPresets()[name];
        if (!data) return { ok: false, error: 'preset "' + name + '" no existe' };
        try { ensureWorkCanvas(); } catch (e) { return { ok: false, error: e.message }; }
        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => {
                try {
                    const ctx = state.texCanvas.getContext('2d');
                    snapshot();
                    ctx.clearRect(HEAD.x, HEAD.y, HEAD.w, HEAD.h);
                    ctx.imageSmoothingEnabled = false;
                    ctx.drawImage(img, 0, 0, img.width, img.height, HEAD.x, HEAD.y, HEAD.w, HEAD.h);
                    state.tex.needsUpdate = true;
                    emitZoneRect();
                    resolve({ ok: true, name });
                } catch (e) { resolve({ ok: false, error: e.message }); }
            };
            img.onerror = () => resolve({ ok: false, error: 'no se pudo cargar el preset' });
            img.src = data;
        });
    }

    function open() {
        if (state.open) { renderUI(); return; }
        try {
            ensureWorkCanvas();
        } catch (e) {
            console.warn(TAG, e.message);

            state.open = true;
            buildUI();
            err(e.message);
            return;
        }
        state.open = true;
        state.undo.length = 0; state.redo.length = 0;
        buildUI();
        refreshPresetList();
        renderUI();
        void 0;
    }

    function close() {

        document.getElementById(ID)?.remove();
        document.getElementById(ID + '-style')?.remove();
        state.open = false;
        state.painting = false;
    }

    function revert() {
        if (!state.mats.length) { err('no hay original guardado'); return; }
        try {
            for (const m of state.mats) {
                const o = state.orig.get(m);
                if (o) { m.map = o; m.needsUpdate = true; }
            }
        } catch {}
        state.tex = null; state.texCanvas = null;
        state.orig.clear(); state.mats = [];
        stopWatchdog();
        try { ensureWorkCanvas(); } catch (e) { err(e.message); return; }
        state.undo.length = 0; state.redo.length = 0;
        renderUI();
        err('');

        try { window.MF_Peer?.sendLook?.({ a: 'revert', what: 'head' }); } catch {}
    }

    window.MF_SkinEditor = {
        open, close, revert,
        presets: listPresets,

        applyPreset: applyPresetByName,
        __tex: () => state.tex,

        get isOpen() { return state.open; }
    };
    window.__MF_SkinEditor = true;

    void 0;
})();

//# sourceURL=MF:src/Studio/MF_SkinEditor.js

/* ==== mf module: src/Studio/MF_PbrEditor.js ==== */

(function () {
    'use strict';
    if (window.__MF_PbrEditor) return;
    const TAG = 'minifeather pbreditor';
    const ID = 'mf-pbreditor';
    const LS_MANUAL = 'mf_pbr_manual';

    const TILE = 16;

    const ZOOM = 14;

    const KINDS = [
        { id: 'n', label: '⛰ Relieve', hint: 'blanco = alto' },
        { id: 's', label: '✨ Brillo', hint: 'blanco = refleja' },
        { id: 'e', label: '🔥 Emisivo', hint: 'blanco = emite luz' }
    ];

    const state = {
        open: false,
        grid: true,
        frames: null,

        tiles: [],

        filtered: [],
        sel: null,

        kind: 'n',
        work: null,

        stampN: new Map(),

        stampS: new Map(),

        stampE: new Map(),
        tool: 'height',

        strength: 1.0,

        brush: 2,

        painting: false, lastCell: null,
        undo: [], redo: []
    };

    function el(id) { return document.getElementById(id); }

    function err(input) {
        const e = el(ID + '-err');
        if (!input) {
            state.errKey = null; state.errVars = null;
            if (e) { e.textContent = ''; e.style.display = 'none'; }
            return;
        }
        if (typeof input === 'string') {
            state.errKey = null; state.errVars = null;
            if (e) { e.textContent = input; e.style.display = 'block'; }
            return;
        }
        state.errKey = input.key; state.errVars = input.vars || {};
        if (e) { e.textContent = t(input.key, input.vars || {}); e.style.display = 'block'; }
    }

    function stampsOf(kind) {
        return kind === 'n' ? state.stampN : (kind === 's' ? state.stampS : state.stampE);
    }

    function texOf(kind) { return window.MF_PBR?.__tex?.(kind) || null; }

    let atlasCv = { n: null, s: null, e: null };
    function atlasCanvas(kind) {
        if (atlasCv[kind]) return atlasCv[kind];
        const tex = texOf(kind);
        const img = tex?.image;
        if (!img) return null;
        const c = document.createElement('canvas');
        c.width = img.width || 1024;
        c.height = img.height || 1024;
        c.getContext('2d', { willReadFrequently: true }).drawImage(img, 0, 0);
        tex.image = c;
        tex.needsUpdate = true;
        atlasCv[kind] = c;
        return c;
    }

    function needsUpdate(kind) {
        const tex = texOf(kind);
        if (tex) tex.needsUpdate = true;
    }

    async function loadFrames() {
        if (state.frames) return state.frames;
        try {
            if (typeof chrome !== 'undefined' && chrome.runtime?.getURL) {
                const res = await fetch(chrome.runtime.getURL('assets/frames.json'));
                state.frames = await res.json();
            }
        } catch (e) {
            console.warn(TAG, 'direct frames.json fetch failed (waiting for panel):', e);
        }
        return state.frames;
    }

    document.addEventListener('minifeather:pbr-editor-frames', (ev) => {
        try {
            const frames = JSON.parse(ev.detail);
            if (!frames || typeof frames !== 'object') return;
            if (state.frames) return;
            state.frames = frames;
            buildTiles();
            const q = el(ID + '-search')?.value || '';
            filterTiles(q);
            err('');
        } catch (e) {
            console.warn(TAG, 'panel frames unreadable:', e);
        }
    });

    document.addEventListener('minifeather:pbr-editor-open', (ev) => {
        try {
            const d = JSON.parse(ev.detail);
            if (d.strings && typeof d.strings === 'object') {

                const i18n = globalThis.MiniFeatherI18n;
                if (i18n) {
                    i18n.register(d.strings);
                    if (d.language) i18n.setLanguage(d.language);
                } else {

                    state.i18n = state.i18n || { lang: d.language || 'en', strings: {} };
                    Object.assign(state.i18n.strings, d.strings);
                    if (d.language) state.i18n.lang = d.language;
                }
            }
            if (d.language && globalThis.MiniFeatherI18n) {
                globalThis.MiniFeatherI18n.setLanguage(d.language);
            }

            if (state.open) {
                refreshTexts();
            }
        } catch (e) {
            console.warn(TAG, 'panel i18n unreadable:', e);
        }
    });

    function t(key, vars) {
        const i18n = globalThis.MiniFeatherI18n;
        if (i18n?.t) {
            try { return i18n.t(key, vars); } catch (_) {}
        }
        if (state.i18n?.strings?.[key]) {
            const v = state.i18n.strings[key][state.i18n.lang] || state.i18n.strings[key].en || key;
            return String(v).replace(/\{(\w+)\}/g, (_, k) => (vars && k in vars) ? vars[k] : '');
        }
        return key;
    }

    function buildTiles() {
        state.tiles = [];
        if (!state.frames) return;
        for (const [fileName, data] of Object.entries(state.frames)) {
            const f = data.frame || {};
            const w = f.w || 16, h = f.h || 16;
            if (w !== 16 || h !== 16) continue;

            state.tiles.push({
                name: fileName.replace(/\.png$/, ''),
                x: f.x || 0, y: f.y || 0, w, h
            });
        }
        state.tiles.sort((a, b) => a.name.localeCompare(b.name));
    }

    function filterTiles(q) {
        const needle = String(q || '').toLowerCase().trim();
        state.filtered = !needle
            ? state.tiles.slice()
            : state.tiles.filter(t => t.name.includes(needle));
        renderTileList();
    }

    function heightToNormal(srcData, strength) {
        const w = srcData.width, h = srcData.height;
        const src = srcData.data;
        const out = new ImageData(w, h);
        const at = (x, y) => {
            const xx = ((x % w) + w) % w, yy = ((y % h) + h) % h;
            return src[(yy * w + xx) * 4];
        };
        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                const gx = (at(x + 1, y - 1) + 2 * at(x + 1, y) + at(x + 1, y + 1))
                    - (at(x - 1, y - 1) + 2 * at(x - 1, y) + at(x - 1, y + 1));
                const gy = (at(x - 1, y + 1) + 2 * at(x, y + 1) + at(x + 1, y + 1))
                    - (at(x - 1, y - 1) + 2 * at(x, y - 1) + at(x + 1, y - 1));
                const nx = -gx * strength / 255;
                const ny = -gy * strength / 255;
                const len = Math.sqrt(nx * nx + ny * ny + 1);
                const p = (y * w + x) * 4;
                out.data[p] = Math.round((nx / len * 0.5 + 0.5) * 255);
                out.data[p + 1] = Math.round((ny / len * 0.5 + 0.5) * 255);
                out.data[p + 2] = Math.round((1 / len * 0.5 + 0.5) * 255);
                out.data[p + 3] = 255;
            }
        }
        return out;
    }

    function tileHeightFromAtlas(tile) {
        const c = document.createElement('canvas');
        c.width = tile.w; c.height = tile.h;
        const ctx = c.getContext('2d', { willReadFrequently: true });
        const cv = atlasCanvas('n');
        if (cv) ctx.drawImage(cv, tile.x, tile.y, tile.w, tile.h, 0, 0, tile.w, tile.h);
        else { ctx.fillStyle = '#808080'; ctx.fillRect(0, 0, tile.w, tile.h); }
        const d = ctx.getImageData(0, 0, tile.w, tile.h);
        const w = tile.w, h = tile.h;
        const nx = new Float32Array(w * h), ny = new Float32Array(w * h);
        for (let i = 0; i < w * h; i++) {
            nx[i] = (d.data[i * 4] / 255) * 2 - 1;
            ny[i] = (d.data[i * 4 + 1] / 255) * 2 - 1;
        }
        const height = new Float32Array(w * h);
        for (let y = 0; y < h; y++) {
            let acc = 0;
            for (let x = 0; x < w; x++) {
                const i = y * w + x;
                if (x > 0) acc += -nx[i] * 3;

                height[i] = acc;
            }
        }
        let mn = Infinity, mx = -Infinity;
        for (const v of height) { if (v < mn) mn = v; if (v > mx) mx = v; }
        const rng = (mx - mn) || 1;
        const out = ctx.createImageData(w, h);
        for (let i = 0; i < w * h; i++) {
            const g = Math.round((height[i] - mn) / rng * 255);
            out.data[i * 4] = g; out.data[i * 4 + 1] = g; out.data[i * 4 + 2] = g;
            out.data[i * 4 + 3] = 255;
        }
        return out;
    }

    function snapshot() {
        if (!state.work) return;
        const ctx = state.work.getContext('2d', { willReadFrequently: true });
        state.undo.push(ctx.getImageData(0, 0, state.work.width, state.work.height));
        if (state.undo.length > 40) state.undo.shift();
        state.redo.length = 0;
    }

    function restoreFrom(a, b) {
        if (!state.work || !a.length) return;
        const ctx = state.work.getContext('2d', { willReadFrequently: true });
        b.push(ctx.getImageData(0, 0, state.work.width, state.work.height));
        ctx.putImageData(a.pop(), 0, 0);
        commitTile();
        renderCanvas();
    }

    function paintCell(x, y, dig) {
        if (!state.work) return;
        const ctx = state.work.getContext('2d', { willReadFrequently: true });
        const r = state.brush;
        if (state.tool === 'smooth') { smoothAt(ctx, x, y, r); return; }

        if (state.tool === 'flat') {
            ctx.fillStyle = state.kind === 'n' ? 'rgb(128,128,128)' : 'rgb(0,0,0)';
            for (let dy = -r; dy <= r; dy++) {
                for (let dx = -r; dx <= r; dx++) {
                    if (dx * dx + dy * dy > r * r) continue;
                    ctx.fillRect(x + dx, y + dy, 1, 1);
                }
            }
            return;
        }

        const W = state.work.width, H = state.work.height;
        const x0 = Math.max(0, x - r), y0 = Math.max(0, y - r);
        const x1 = Math.min(W - 1, x + r), y1 = Math.min(H - 1, y + r);
        if (x1 < x0 || y1 < y0) return;
        const img = ctx.getImageData(x0, y0, x1 - x0 + 1, y1 - y0 + 1);
        const d = img.data;
        const amount = Math.round(70 * state.strength);
        for (let yy = y0; yy <= y1; yy++) {
            for (let xx = x0; xx <= x1; xx++) {
                const dx = xx - x, dy = yy - y;
                if (dx * dx + dy * dy > r * r) continue;
                const p = ((yy - y0) * (x1 - x0 + 1) + (xx - x0)) * 4;
                const v = d[p];
                const nv = dig ? Math.max(0, v - amount) : Math.min(255, v + amount);
                d[p] = d[p + 1] = d[p + 2] = nv; d[p + 3] = 255;
            }
        }
        ctx.putImageData(img, x0, y0);
    }

    function smoothAt(ctx, x, y, r) {

        if (r === 0) return;
        const W = state.work.width, H = state.work.height;
        const src = ctx.getImageData(0, 0, W, H);
        const dst = ctx.createImageData(W, H);
        dst.data.set(src.data);
        const at = (xx, yy) => {
            const xi = Math.max(0, Math.min(W - 1, xx));
            const yi = Math.max(0, Math.min(H - 1, yy));
            return src.data[(yi * W + xi) * 4];
        };
        for (let dy = -r; dy <= r; dy++) {
            for (let dx = -r; dx <= r; dx++) {
                if (dx * dx + dy * dy > r * r) continue;
                const xx = x + dx, yy = y + dy;
                if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;
                const v = Math.round(
                    (at(xx - 1, yy) + at(xx + 1, yy) + at(xx, yy - 1) + at(xx, yy + 1) + 2 * at(xx, yy)) / 6);
                const p = (yy * W + xx) * 4;
                dst.data[p] = v; dst.data[p + 1] = v; dst.data[p + 2] = v; dst.data[p + 3] = 255;
            }
        }
        ctx.putImageData(dst, 0, 0);
    }

    function lineCells(x0, y0, x1, y1, cb) {
        const dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
        const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
        let e = dx - dy;
        for (;;) {
            cb(x0, y0);
            if (x0 === x1 && y0 === y1) break;
            const e2 = 2 * e;
            if (e2 > -dy) { e -= dy; x0 += sx; }
            if (e2 < dx) { e += dx; y0 += sy; }
        }
    }

    function commitTile() {
        const t = state.sel;
        if (!t || !state.work) return;
        const ctx = state.work.getContext('2d', { willReadFrequently: true });
        const data = ctx.getImageData(0, 0, t.w, t.h);
        if (state.kind === 'n') {
            state.stampN.set(t.name, data);
            const cv = atlasCanvas('n');
            if (!cv) return;
            cv.getContext('2d', { willReadFrequently: true })
                .putImageData(heightToNormal(data, state.strength), t.x, t.y);
            needsUpdate('n');
        } else {
            stampsOf(state.kind).set(t.name, data);
            const cv = atlasCanvas(state.kind);
            if (!cv) return;
            cv.getContext('2d', { willReadFrequently: true }).putImageData(data, t.x, t.y);
            needsUpdate(state.kind);
        }
    }

    function selectTile(name) {
        const t = state.tiles.find(x => x.name === name);
        if (!t) return;
        state.sel = t;
        state.undo = []; state.redo = [];
        state.work = document.createElement('canvas');
        state.work.width = t.w; state.work.height = t.h;
        const ctx = state.work.getContext('2d', { willReadFrequently: true });
        if (state.kind === 'n') {
            const cached = state.stampN.get(name);
            if (cached) ctx.putImageData(cached, 0, 0);
            else ctx.putImageData(tileHeightFromAtlas(t), 0, 0);
        } else {
            const cached = stampsOf(state.kind).get(name);
            if (cached) ctx.putImageData(cached, 0, 0);
            else {
                const cv = atlasCanvas(state.kind);
                if (cv) ctx.drawImage(cv, t.x, t.y, t.w, t.h, 0, 0, t.w, t.h);
                else { ctx.fillStyle = '#000'; ctx.fillRect(0, 0, t.w, t.h); }
            }
        }
        renderTileList();
        renderCanvas();
        renderRef();
    }

    function setKind(k) {
        state.kind = k;
        document.querySelectorAll('#' + ID + ' [data-kind]').forEach(b =>
            b.classList.toggle('on', b.dataset.kind === k));
        const hint = document.querySelector('#' + ID + ' [data-kind-hint]');
        if (hint) hint.textContent = KINDS.find(x => x.id === k)?.hint || '';
        if (state.sel) selectTile(state.sel.name);
        else renderTileList();
    }

    function renderCanvas() {
        const cv = el(ID + '-cv');
        if (!cv) return;
        const ctx = cv.getContext('2d');
        const t = state.sel;
        const w = t ? t.w * ZOOM : TILE * ZOOM;
        const h = t ? t.h * ZOOM : TILE * ZOOM;
        if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
        ctx.imageSmoothingEnabled = false;
        ctx.fillStyle = '#0c0c10';
        ctx.fillRect(0, 0, w, h);
        if (!t || !state.work) {
            ctx.fillStyle = '#4a4a55';
            ctx.font = '11px system-ui';
            ctx.fillText('← elige una textura de la lista', 14, h / 2);
            return;
        }

        ctx.drawImage(state.work, 0, 0, w, h);
        if (state.grid) {
            ctx.strokeStyle = 'rgba(255,255,255,.07)';
            ctx.beginPath();
            for (let x = 0; x <= t.w; x++) { ctx.moveTo(x * ZOOM + .5, 0); ctx.lineTo(x * ZOOM + .5, h); }
            for (let y = 0; y <= t.h; y++) { ctx.moveTo(0, y * ZOOM + .5); ctx.lineTo(w, y * ZOOM + .5); }
            ctx.stroke();
        }

        ctx.font = '9px system-ui';
        ctx.fillStyle = 'rgba(0,0,0,.6)';
        ctx.fillRect(2, 2, t.name.length * 5.5 + 4, 11);
        ctx.fillStyle = '#c8c8d2';
        ctx.fillText(t.name, 4, 11);
    }

    function renderTileList() {
        const list = el(ID + '-list');
        if (!list) return;
        const max = 80;
        const items = state.filtered.slice(0, max);
        list.innerHTML = items.map(t => `
            <div class="mfpe-item ${state.sel?.name === t.name ? 'sel' : ''}" data-tile="${t.name}" title="${t.name}">
                <canvas width="16" height="16" data-thumb="${t.name}"></canvas>
                <span>${t.name}</span>
            </div>`).join('') +
            (state.filtered.length > max
                ? `<div class="mfpe-more">+${state.filtered.length - max} más — afina la búsqueda</div>`
                : '');
        const cv = atlasCanvas(state.kind);
        for (const item of list.querySelectorAll('[data-thumb]')) {
            const t = state.tiles.find(x => x.name === item.dataset.thumb);
            const ictx = item.getContext('2d');
            ictx.imageSmoothingEnabled = false;
            if (t && cv) ictx.drawImage(cv, t.x, t.y, t.w, t.h, 0, 0, 16, 16);
            else {
                ictx.fillStyle = state.kind === 'n' ? '#8080ff' : '#000';
                ictx.fillRect(0, 0, 16, 16);
            }
        }
        list.querySelectorAll('[data-tile]').forEach(d => {
            d.onclick = () => selectTile(d.dataset.tile);
        });
    }

    function renderRef() {
        const ref = el(ID + '-ref');
        if (!ref) return;
        const t = state.sel;
        const ictx = ref.getContext('2d');
        ictx.imageSmoothingEnabled = false;
        ictx.fillStyle = '#111';
        ictx.fillRect(0, 0, ref.width, ref.height);
        if (!t) return;
        const diff = window.MF_PBR?.__diffuse?.();
        if (diff) ictx.drawImage(diff, t.x, t.y, t.w, t.h, 0, 0, ref.width, ref.height);
    }

    function idbPut(key, value) {
        return new Promise((resolve) => {
            const req = indexedDB.open('mf_pbr_store', 1);
            req.onupgradeneeded = () => {
                if (!req.result.objectStoreNames.contains('atlases')) {
                    req.result.createObjectStore('atlases');
                }
            };
            req.onsuccess = () => {
                const db = req.result;
                try {
                    const tx = db.transaction('atlases', 'readwrite');
                    tx.objectStore('atlases').put(value, key);
                    tx.oncomplete = () => resolve(true);
                    tx.onerror = () => resolve(false);
                } catch (_) { resolve(false); }
            };
            req.onerror = () => resolve(false);
        });
    }

    async function applyPack() {
        let saved = 0;
        for (const kind of ['n', 's', 'e']) {
            const cv = atlasCanvas(kind);
            if (!cv) continue;
            const placed = Math.max(stampsOf(kind).size, 1);
            const ok = await idbPut('atlas_' + kind, { dataUrl: cv.toDataURL('image/png'), placed });
            if (ok) saved++;
        }
        if (saved) {
            try { localStorage.setItem(LS_MANUAL, '1'); } catch (_) {}
            err({ key: 'pbrEditorSavedOk', vars: { n: saved } });
        } else {
            err({ key: 'pbrEditorSaveEmpty' });
        }
    }

    function crc32(buf) {
        let table = crc32.table;
        if (!table) {
            table = crc32.table = new Int32Array(256);
            for (let n = 0; n < 256; n++) {
                let c = n;
                for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
                table[n] = c;
            }
        }
        let crc = -1;
        for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ table[(crc ^ buf[i]) & 0xFF];
        return (crc ^ -1) >>> 0;
    }

    function dataUrlToBytes(dataUrl) {
        const b64 = dataUrl.split(',')[1];
        const bin = atob(b64);
        const out = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
        return out;
    }

    function makeZip(files) {

        const enc = new TextEncoder();
        const parts = [];
        const central = [];
        let offset = 0;
        const date = ((2024 - 1980) << 9) | (1 << 5) | 1;
        const time = 0;
        for (const f of files) {
            const nameB = enc.encode(f.name);
            const crc = crc32(f.bytes);
            const lh = new DataView(new ArrayBuffer(30));
            lh.setUint32(0, 0x04034b50, true);
            lh.setUint16(4, 20, true);
            lh.setUint16(8, 0, true);
            lh.setUint16(10, time, true);
            lh.setUint16(12, date, true);
            lh.setUint32(14, crc, true);
            lh.setUint32(18, f.bytes.length, true);
            lh.setUint32(22, f.bytes.length, true);
            lh.setUint16(26, nameB.length, true);
            parts.push(new Uint8Array(lh.buffer), nameB, f.bytes);
            const ch = new DataView(new ArrayBuffer(46));
            ch.setUint32(0, 0x02014b50, true);
            ch.setUint16(4, 20, true);
            ch.setUint16(6, 20, true);
            ch.setUint16(12, time, true);
            ch.setUint16(14, date, true);
            ch.setUint32(16, crc, true);
            ch.setUint32(20, f.bytes.length, true);
            ch.setUint32(24, f.bytes.length, true);
            ch.setUint16(28, nameB.length, true);
            ch.setUint32(42, offset, true);
            central.push(new Uint8Array(ch.buffer), nameB);
            offset += 30 + nameB.length + f.bytes.length;
        }
        let cdSize = 0;
        for (const c of central) cdSize += c.length;
        const eocd = new DataView(new ArrayBuffer(22));
        eocd.setUint32(0, 0x06054b50, true);
        eocd.setUint16(8, files.length, true);
        eocd.setUint16(10, files.length, true);
        eocd.setUint32(12, cdSize, true);
        eocd.setUint32(16, offset, true);
        const all = [...parts, ...central, new Uint8Array(eocd.buffer)];
        let total = 0;
        for (const a of all) total += a.length;
        const out = new Uint8Array(total);
        let pos = 0;
        for (const a of all) { out.set(a, pos); pos += a.length; }
        return out;
    }

    async function exportPack() {
        const files = [];
        for (const kind of ['n', 's', 'e']) {
            const stamps = stampsOf(kind);
            if (!stamps.size) continue;
            for (const [name, data] of stamps) {
                const t = state.tiles.find(x => x.name === name);
                if (!t) continue;
                const c = document.createElement('canvas');
                c.width = t.w; c.height = t.h;
                const cx = c.getContext('2d');
                if (kind === 'n') {
                    cx.putImageData(heightToNormal(data, state.strength), 0, 0);
                } else {
                    cx.putImageData(data, 0, 0);
                }
                files.push({ name: name + '_' + kind + '.png', bytes: dataUrlToBytes(c.toDataURL('image/png')) });
            }
        }
        if (!files.length) { err('nada que exportar — pinta algo primero'); return; }
        const blob = new Blob([makeZip(files)], { type: 'application/zip' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'mf-pbr-pack.zip';
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
        err('');
    }

    function resetTile() {
        const t = state.sel;
        if (!t) return;
        state.stampN.delete(t.name);
        state.stampS.delete(t.name);
        state.stampE.delete(t.name);
        for (const kind of ['n', 's', 'e']) {
            const cv = atlasCanvas(kind);
            if (!cv) continue;
            const ctx = cv.getContext('2d', { willReadFrequently: true });
            ctx.fillStyle = kind === 'n' ? '#8080ff' : '#000';
            ctx.fillRect(t.x, t.y, t.w, t.h);
            needsUpdate(kind);
        }
        selectTile(t.name);
    }

    function buildUI() {
        if (el(ID)) return;
        const style = document.createElement('style');
        style.id = ID + '-style';
        style.textContent = `
            #${ID} { position:fixed; top:70px; right:16px; z-index:2147483000;
  background:#14141a; border:1px solid #32323a; border-radius:8px;
  box-shadow:0 8px 32px rgba(0,0,0,.6); color:#e8e8ee;
  font:12px/1.4 system-ui,sans-serif; user-select:none;
  width:660px; max-width:calc(100vw - 32px); max-height:calc(100vh - 100px);
  display:flex; flex-direction:column; }
  #${ID} .mfpe-head { display:flex; align-items:center; gap:8px; padding:8px 10px;
  border-bottom:1px solid #26262e; font-weight:700; letter-spacing:.5px; }
  #${ID} .mfpe-head .dot { width:8px; height:8px; border-radius:50%;
  background:#4dff88; animation:mfpe-pulse 1.5s infinite; }
  @keyframes mfpe-pulse { 50% { opacity:.35; } }
  #${ID} .mfpe-head button { margin-left:auto; }
  #${ID} .mfpe-body { display:flex; flex:1; min-height:0; }
  #${ID} .mfpe-side { width:225px; border-right:1px solid #202028; display:flex;
  flex-direction:column; min-height:0; }
  #${ID} .mfpe-side input { margin:8px; padding:4px 8px; background:#1c1c24;
  color:#e8e8ee; border:1px solid #3a3a44; border-radius:4px; font:inherit; }
  #${ID} .mfpe-list { flex:1; overflow-y:auto; padding:0 8px 8px; }
  #${ID} .mfpe-item { display:flex; align-items:center; gap:6px; padding:3px 4px;
  border-radius:4px; cursor:pointer; }
  #${ID} .mfpe-item:hover { background:#1e1e26; }
  #${ID} .mfpe-item.sel { background:#2a2a34; outline:1px solid #ff6b2b; }
  #${ID} .mfpe-item canvas { width:20px; height:20px; flex:none;
  image-rendering:pixelated; border:1px solid #2a2a32; border-radius:2px; }
  #${ID} .mfpe-item span { font-size:11px; overflow:hidden; text-overflow:ellipsis;
  white-space:nowrap; }
  #${ID} .mfpe-more { padding:6px; color:#6a6a76; font-size:10px; }
  #${ID} .mfpe-main { flex:1; padding:8px 10px; display:flex; flex-direction:column;
  min-height:0; overflow-y:auto; }
  #${ID} canvas.mfpe-cv { display:block; border:1px solid #32323a;
  image-rendering:pixelated; cursor:crosshair; background:#0c0c10; }
  #${ID} .mfpe-row { display:flex; align-items:center; gap:6px; padding:6px 0;
  flex-wrap:wrap; }
  #${ID} .mfpe-row + .mfpe-row { border-top:1px solid #202028; }
  #${ID} button { background:#23232c; color:#e8e8ee; border:1px solid #3a3a44;
  border-radius:4px; padding:3px 8px; cursor:pointer; font:inherit; }
  #${ID} button:hover { background:#2e2e3a; }
  #${ID} button.on { background:#ff6b2b; color:#14141a; border-color:#ff6b2b;
  font-weight:700; }
  #${ID} button.warn { background:#5a2020; color:#ff8080; border-color:#804040; }
  #${ID} input[type=range] { accent-color:#ff6b2b; width:100px; }
  #${ID} label { color:#9a9aa6; }
  #${ID} .mfpe-err { color:#8adf8a; padding:4px 10px; display:none;
  border-top:1px solid #202028; }
        `;
        const root = document.createElement('div');
        root.id = ID;
        root.innerHTML = `
            <div class="mfpe-head"><span class="dot"></span><span data-i18n="pbrEditorTitle">⛰ EDITOR PBR — relieve en vivo</span>
    <button data-act="close" data-i18n-title="pbrEditorClose" title="Cerrar">✕</button></div>
        <div class="mfpe-body">
    <div class="mfpe-side">
        <input type="text" id="${ID}-search" data-i18n-placeholder="pbrEditorSearch" placeholder="buscar (stone, dirt…)" autocomplete="off">
        <div class="mfpe-list" id="${ID}-list"></div>
    </div>
    <div class="mfpe-main">
        <div class="mfpe-row">
            <label data-i18n="pbrEditorChannel">Canal:</label>
            ${KINDS.map(k => `<button data-kind="${k.id}" class="${k.id === 'n' ? 'on' : ''}" data-i18n-title="pbrEditorKind_${k.id}" title="${k.hint}">${k.label}</button>`).join('')}
            <span data-kind-hint style="color:#6a6a76;font-size:10px;">${t('pbrEditorHintN')}</span>
        </div>
        <div class="mfpe-row">
            <button data-tool="height" class="on" data-i18n-title="pbrEditorReliefUp" title="Elevar (clic derecho o Alt = hundir)">⛰</button>
            <button data-tool="smooth" data-i18n-title="pbrEditorReliefSmooth" title="Suavizar relieve">🌊</button>
            <button data-tool="flat" data-i18n-title="pbrEditorReliefFlat" title="Aplanar (neutral)">▭</button>
            <button data-tool="picker" data-i18n-title="pbrEditorReliefPicker" title="Cuentagotas">💧</button>
            <span style="color:#9a9aa6;" data-i18n="pbrEditorBrush">Pincel</span>
            <button data-brush="0" data-i18n-title="pbrEditorBrush1" title="1 px (preciso)">1px</button>
            <button data-brush="1" data-i18n-title="pbrEditorBrush3" title="3×3 (3 px)">3</button>
            <button data-brush="2" class="on" data-i18n-title="pbrEditorBrush5" title="5×5 (5 px)">5</button>
            <button data-brush="3" data-i18n-title="pbrEditorBrush7" title="7×7 (7 px)">7</button>
            <label data-i18n="pbrEditorStrength">Intensidad <input type="range" min="0.3" max="3" step="0.1" value="1" data-str></label>
            <button data-act="undo" data-i18n-title="pbrEditorUndo" title="Deshacer">↩</button>
            <button data-act="redo" data-i18n-title="pbrEditorRedo" title="Rehacer">↪</button>
            <button data-act="grid" class="on" data-i18n-title="pbrEditorGrid" title="Rejilla">▦</button>
        </div>
        <div class="mfpe-row" style="justify-content:center; gap:14px;">
            <canvas class="mfpe-cv" id="${ID}-cv" width="${TILE * ZOOM}" height="${TILE * ZOOM}"></canvas>
            <div style="display:flex; flex-direction:column; gap:4px; align-items:center;">
                <canvas id="${ID}-ref" width="16" height="16" style="width:112px;height:112px;
                    image-rendering:pixelated; border:1px solid #32323a; border-radius:4px; background:#0c0c10;"></canvas>
                <span style="font-size:9px;color:#6a6a76;" data-i18n="pbrEditorDiffuse">textura del juego</span>
            </div>
        </div>
        <div class="mfpe-row">
            <button data-act="apply" data-i18n-title="pbrEditorApply" title="Guardar el pack editado (persiste tras F5)">💾 <span data-i18n="pbrEditorApplyLabel">Aplicar</span></button>
            <button data-act="export" data-i18n-title="pbrEditorExport" title="Descargar ZIP con PNGs _n/_s/_e (re-importable)">⬇ ZIP</button>
            <button data-act="reset-tile" class="warn" data-i18n-title="pbrEditorResetTile" title="Restaurar este tile a neutro">↺ <span data-i18n="pbrEditorResetTileLabel">tile</span></button>
        </div>
    </div>
        </div>
            <div class="mfpe-err" id="${ID}-err"></div>
        `;
        document.body.appendChild(style);
        document.body.appendChild(root);
        bindUI(root);
        refreshTexts();
    }

    function refreshTexts() {
        const root = el(ID);
        if (!root) return;

        root.querySelectorAll('[data-i18n]').forEach(node => {
            const k = node.getAttribute('data-i18n');
            if (!k) return;

            const childEls = [...node.childNodes].filter(n => n.nodeType === 1);
            if (childEls.length === 0) {
                node.textContent = t(k);
            } else {

                const txt = t(k);
                let placed = false;
                childEls.forEach((c, i) => {
                    if (c.tagName === 'INPUT' || c.tagName === 'CANVAS') {
                        if (!placed && i > 0) {
                            c.textContent = txt;
                            placed = true;
                        }
                    } else if (c.hasAttribute && c.hasAttribute('data-i18n')) {

                    } else {
                        c.textContent = '';
                    }
                });
                if (!placed) {

                    node.insertBefore(document.createTextNode(txt), node.firstChild);
                }
            }
        });

        root.querySelectorAll('[data-i18n-title]').forEach(node => {
            const k = node.getAttribute('data-i18n-title');
            if (k) node.setAttribute('title', t(k));
        });
        root.querySelectorAll('[data-i18n-placeholder]').forEach(node => {
            const k = node.getAttribute('data-i18n-placeholder');
            if (k) node.setAttribute('placeholder', t(k));
        });

        const hint = root.querySelector('[data-kind-hint]');
        if (hint) hint.textContent = t('pbrEditorKind_' + state.kind) || hint.textContent;

        const e = el(ID + '-err');
        if (e && e.textContent && state.errKey) e.textContent = t(state.errKey, state.errVars);
    }

    function bindUI(root) {
        const setActive = (sel, btn) => {
            root.querySelectorAll(sel).forEach(b => b.classList.toggle('on', b === btn));
        };
        root.querySelectorAll('[data-kind]').forEach(b => b.onclick = () => setKind(b.dataset.kind));
        root.querySelectorAll('[data-tool]').forEach(b => b.onclick = () => {
            state.tool = b.dataset.tool;
            setActive('[data-tool]', b);
        });
        root.querySelectorAll('[data-brush]').forEach(b => b.onclick = () => {
            state.brush = +b.dataset.brush;
            setActive('[data-brush]', b);
        });
        root.querySelector('[data-str]').oninput = (e) => {
            state.strength = +e.target.value;
            if (state.sel && state.stampN.has(state.sel.name)) {

                const t = state.sel;
                const cv = atlasCanvas('n');
                if (cv) {
                    cv.getContext('2d', { willReadFrequently: true })
                        .putImageData(heightToNormal(state.stampN.get(t.name), state.strength), t.x, t.y);
                    needsUpdate('n');
                }
            }
        };
        root.querySelectorAll('[data-act]').forEach(b => b.onclick = () => {
            switch (b.dataset.act) {
                case 'close': close(); break;
                case 'undo': restoreFrom(state.undo, state.redo); break;
                case 'redo': restoreFrom(state.redo, state.undo); break;
                case 'grid': state.grid = !state.grid; b.classList.toggle('on', state.grid); renderCanvas(); break;
                case 'apply': applyPack(); break;
                case 'reset-tile': resetTile(); break;
                case 'export': exportPack(); break;
            }
        });
        const search = root.querySelector('#' + ID + '-search');
        search.oninput = () => filterTiles(search.value);

        const cv = root.querySelector('canvas.mfpe-cv');
        const cellOf = (e) => {
            const t = state.sel;
            const r = cv.getBoundingClientRect();
            const x = Math.floor((e.clientX - r.left) / (r.width / t.w));
            const y = Math.floor((e.clientY - r.top) / (r.height / t.h));
            return { x, y };
        };
        cv.addEventListener('contextmenu', (e) => e.preventDefault());
        cv.addEventListener('pointerdown', (e) => {
            if (!state.sel || !state.work) return;
            e.preventDefault();
            const { x, y } = cellOf(e);
            if (state.tool === 'picker') {
                const d = state.work.getContext('2d').getImageData(x, y, 1, 1).data;
                err({ key: 'pbrEditorPickerInfo', vars: { v: d[0], p: Math.round(d[0] / 2.55) } });
                return;
            }
            snapshot();
            state.painting = true;
            state.lastCell = { x, y };
            try { cv.setPointerCapture(e.pointerId); } catch (_) {}
            const dig = e.button === 2 || e.altKey;
            paintCell(x, y, dig);
            commitTile();
            renderCanvas();
        });
        cv.addEventListener('pointermove', (e) => {
            if (!state.painting || !state.sel) return;
            const { x, y } = cellOf(e);
            const l = state.lastCell;
            if (l && (l.x !== x || l.y !== y)) {
                const dig = e.buttons === 2 || e.altKey;
                lineCells(l.x, l.y, x, y, (cx, cy) => paintCell(cx, cy, dig));
                state.lastCell = { x, y };
                commitTile();
                renderCanvas();
            }
        });
        const stop = () => { state.painting = false; state.lastCell = null; };
        cv.addEventListener('pointerup', stop);
        cv.addEventListener('pointercancel', stop);
    }

    function pbrReady() {
        try {
            const st = window.MF_PBR?.status?.();
            return !!(st && (st.kinds?.n || st.kinds?.s || st.kinds?.e));
        } catch (_) { return false; }
    }

    async function open() {
        if (state.open) return;
        if (!pbrReady()) {
            console.warn(TAG, 'PBR not ready — enable PBR Textures and install a pack first');
        }
        state.open = true;
        buildUI();
        await loadFrames();
        buildTiles();
        filterTiles('');
        renderCanvas();
        if (!state.tiles.length) {
            err('sin lista de texturas — cierra/abre de nuevo desde el botón de la GUI');
        }
        void 0;
    }

    function close() {
        el(ID)?.remove();
        el(ID + '-style')?.remove();
        state.open = false;
        state.painting = false;
    }

    document.addEventListener('minifeather:pbr-editor-open', () => open());

    window.MF_PbrEditor = { open, close, get isOpen() { return state.open; } };
    window.__MF_PbrEditor = true;
    void 0;
})();

//# sourceURL=MF:src/Studio/MF_PbrEditor.js

/* ==== mf module: src/Studio/MF_SkinChanger.js ==== */

(function () {
    'use strict';
    if (window.__MF_SkinChanger) return;
    const TAG = 'minifeather skinchanger';

    const ID = 'mf-skinchanger';
    const DB_NAME = 'minifeather_skins';
    const STORE = 'skins';
    const SKIN_FACE = { x: 8, y: 8, w: 8, h: 8 };

    const state = {
        open: false,
        items: [],

        current: null,

        origCanvas: null,

        origMats: [],

        watchdog: null
    };

    function getGame() {
        if (globalThis.miniblox?.player) return globalThis.miniblox;
        try {
            const react = document.querySelector('#react');
            if (react) for (const root of Object.values(react)) {
                const g = root?.updateQueue?.baseState?.element?.props?.game;
                if (g?.player) return g;
            }
        } catch {}
        return null;
    }

    function getMesh() {
        const g = getGame();
        const me = g?.player;
        if (!me) return null;
        try { const e = g.world?.getPlayerById?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        try { const e = g.world?.players?.get?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        try { const e = g.world?.entities?.get?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        return me?.mesh || null;
    }

    function findSkinMaterials(mesh) {
        const out = [];
        if (!mesh) return out;
        const seen = new Set();
        mesh.traverse(o => {
            if (!o?.material) return;
            const list = Array.isArray(o.material) ? o.material : [o.material];
            for (const m of list) {
                if (m?.map && !seen.has(m)) { seen.add(m); out.push(m); }
            }
        });
        const skins = out.filter(m => {
            const w = m.map?.image?.width, h = m.map?.image?.height;
            if (!w || !h) return false;

            const k64 = w / 64;
            return Number.isInteger(k64) && (h === w || h === w / 2);
        });
        return skins.length ? skins : out;
    }

    function dbOpen() {
        return new Promise((resolve, reject) => {
            const req = indexedDB.open(DB_NAME, 1);
            req.onupgradeneeded = () => {
                const db = req.result;
                if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE, { keyPath: 'name' });
            };
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error || new Error('indexedDB error'));
        });
    }

    async function dbAll() {
        const db = await dbOpen();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE, 'readonly');
            const req = tx.objectStore(STORE).getAll();
            req.onsuccess = () => resolve(req.result || []);
            req.onerror = () => reject(req.error);
        });
    }

    async function dbPut(item) {
        const db = await dbOpen();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE, 'readwrite');
            tx.objectStore(STORE).put(item);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        });
    }

    async function dbDelete(name) {
        const db = await dbOpen();
        return new Promise((resolve) => {
            const tx = db.transaction(STORE, 'readwrite');
            tx.objectStore(STORE).delete(name);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => resolve(false);
        });
    }

    function loadImage(src) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error('could not load the image'));
            img.src = src;
        });
    }

    function faceThumb(img) {
        const k = Math.max(1, Math.round(img.width / 64));
        const c = document.createElement('canvas');
        c.width = 32; c.height = 32;
        const ctx = c.getContext('2d');
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(img, SKIN_FACE.x * k, SKIN_FACE.y * k, SKIN_FACE.w * k, SKIN_FACE.h * k, 0, 0, 32, 32);
        return c.toDataURL();
    }

    function bodyThumb(img) {
        const k = Math.max(1, Math.round(img.width / 64));
        const c = document.createElement('canvas');
        c.width = 32; c.height = 32;
        const ctx = c.getContext('2d');
        ctx.imageSmoothingEnabled = false;

        ctx.drawImage(img, 16 * k, 16 * k, 24 * k, 16 * k, 4, 8, 24, 16);
        ctx.drawImage(img, 40 * k, 0, 24 * k, 16 * k, 4, -8, 24, 16);
        return c.toDataURL();
    }

    function ensureTextureSession() {
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador no disponible (entra al mundo primero)');
        const mats = findSkinMaterials(mesh);
        if (!mats.length) throw new Error('no se encontró material de skin');

        const seTex = window.MF_SkinEditor?.__tex?.();
        if (seTex && mats.some(m => m.map === seTex) && seTex.image instanceof HTMLCanvasElement) {
            return { canvas: seTex.image, tex: seTex, mats, shared: true };
        }

        const src = mats[0].map;
        const base = src?.image;
        if (!base) throw new Error('textura de skin no legible');
        const c = document.createElement('canvas');
        c.width = base.width; c.height = base.height;
        c.getContext('2d').drawImage(base, 0, 0);

        let tex = null;
        try { tex = new src.constructor(c); } catch {}
        if (!tex) {
            try { tex = new src.constructor(); tex.image = c; } catch {
                throw new Error('no se pudo crear textura editable');
            }
        }
        try {
            tex.magFilter = src.magFilter;
            tex.minFilter = src.minFilter;
            if (src.colorSpace !== undefined && 'colorSpace' in tex) tex.colorSpace = src.colorSpace;
            tex.flipY = src.flipY;
            tex.wrapS = src.wrapS; tex.wrapT = src.wrapT;
            tex.repeat?.copy?.(src.repeat);
            tex.offset?.copy?.(src.offset);
        } catch {}

        if (!state.origCanvas) {
            try {
                const oc = document.createElement('canvas');
                oc.width = base.width; oc.height = base.height;
                oc.getContext('2d').drawImage(base, 0, 0);
                state.origCanvas = oc;
            } catch {}
        }
        for (const m of mats) { m.map = tex; m.needsUpdate = true; }
        tex.__mfLocalCanvas = true;
        state.origMats = mats;
        state.ownTex = tex;
        return { canvas: c, tex, mats, shared: false };
    }

    async function apply(name, opts) {
        const item = state.items.find(i => i.name === name);
        if (!item && !opts?.dataURL) throw new Error('skin "' + name + '" no está en la biblioteca');
        const dataURL = opts?.dataURL || item.dataURL;
        const img = await loadImage(dataURL);

        const canvas = normalizeSkinCanvas(img);
        if (!canvas) {
            throw new Error('PNG inválido (' + img.width + 'x' + img.height + ') — debe ser 64x64/64x32 o múltiplo');
        }

        const session = ensureTextureSession();
        const ctx = session.canvas.getContext('2d');
        ctx.imageSmoothingEnabled = false;
        ctx.clearRect(0, 0, session.canvas.width, session.canvas.height);

        const tw = session.canvas.width, th = session.canvas.height;
        const cs = canvas.width / 64;
        if (tw === th * 2) {
            ctx.drawImage(canvas, 0, 0, 64 * cs, 32 * cs, 0, 0, tw, th);
        } else {
            ctx.drawImage(canvas, 0, 0, 64 * cs, 64 * cs, 0, 0, tw, th);
        }
        session.tex.needsUpdate = true;
        state.current = name;
        startWatchdog();

        try {
            window.MF_Peer?.sendLook?.({
                a: 'skin', name,
                dataURL: opts?.dataURL || item?.dataURL || null
            });
        } catch {}
        return { ok: true, skin: name, mode: session.shared ? 'shared' : 'own' };
    }

    function normalizeSkinCanvas(img) {
        const w = img.width, h = img.height;
        const isModern = w === h;

        const isLegacy = w === h * 2;

        if (!isModern && !isLegacy) return null;
        const scale = w / 64;
        if (!Number.isInteger(scale)) return null;

        if (isModern) return img;

        const out = document.createElement('canvas');
        out.width = w; out.height = w;
        const cx = out.getContext('2d');
        cx.imageSmoothingEnabled = false;
        cx.drawImage(img, 0, 0, w, h, 0, 0, w, h);
        const mirror = (sx, dx) => {
            cx.save();
            cx.translate((dx + 16) * scale, 48 * scale);
            cx.scale(-1, 1);
            cx.drawImage(img, sx * scale, h / 2, 16 * scale, h / 2, 0, 0, 16 * scale, 16 * scale);
            cx.restore();
        };
        mirror(0, 16);
        mirror(40, 32);
        return out;
    }

    function revert() {
        if (!state.origCanvas) {
            const session = tryCurrentCanvas();
            if (session) {

                return { ok: false, error: 'no hay original guardado (¿skin ya restaurada?)' };
            }
            return { ok: false, error: 'no hay original guardado' };
        }
        const session = tryCurrentCanvas();
        if (!session) return { ok: false, error: 'sin textura activa' };
        const ctx = session.canvas.getContext('2d');
        ctx.clearRect(0, 0, session.canvas.width, session.canvas.height);
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(state.origCanvas, 0, 0);
        session.tex.needsUpdate = true;
        state.current = null;
        stopWatchdog();

        try { window.MF_Peer?.sendLook?.({ a: 'revert', what: 'skin' }); } catch {}
        return { ok: true };
    }

    function tryCurrentCanvas() {
        const mesh = getMesh();
        const mats = findSkinMaterials(mesh);
        if (!mats.length) return null;

        for (const m of mats) {
            if (state.ownTex && m.map === state.ownTex) {
                return { canvas: state.ownTex.image, tex: state.ownTex };
            }
        }
        const seTex = window.MF_SkinEditor?.__tex?.();
        if (seTex && mats.some(m => m.map === seTex) && seTex.image instanceof HTMLCanvasElement) {
            return { canvas: seTex.image, tex: seTex };
        }

        const t = mats[0].map;
        if (t?.image instanceof HTMLCanvasElement) return { canvas: t.image, tex: t };
        return null;
    }

    function startWatchdog() {
        stopWatchdog();
        state.watchdog = setInterval(() => {
            if (!state.current) return;
            const mesh = getMesh();
            if (!mesh) return;
            const mats = findSkinMaterials(mesh);
            const item = state.items.find(i => i.name === state.current);
            if (!item) return;
            const mounted = mats.some(m => m.map === state.ownTex) ||
                mats.some(m => m.map === window.MF_SkinEditor?.__tex?.());
            if (!mounted) {

                state.origCanvas = null;
                apply(state.current).catch(() => {});
            }
        }, 500);
    }

    function stopWatchdog() {
        if (state.watchdog) { clearInterval(state.watchdog); state.watchdog = null; }
    }

    async function importFiles(files) {
        const out = [];
        for (const file of files) {
            if (!/\.png$/i.test(file.name)) continue;
            const dataURL = await new Promise((resolve) => {
                const r = new FileReader();
                r.onload = () => resolve(r.result);
                r.onerror = () => resolve(null);
                r.readAsDataURL(file);
            });
            if (!dataURL) continue;
            try {
                const img = await loadImage(dataURL);

                if (!normalizeSkinCanvas(img)) {
                    console.warn(TAG + ' "' + file.name + '" proporciones no válidas (' + img.width + 'x' + img.height + ')');
                    continue;
                }
                const name = file.name.replace(/\.png$/i, '');
                const item = { name, dataURL, thumb: faceThumb(img), w: img.width, h: img.height };
                await dbPut(item);
                state.items = state.items.filter(i => i.name !== name);
                state.items.push(item);
                out.push(item);
            } catch (e) {
                console.warn(TAG + ' import ' + file.name + ': ' + e.message);
            }
        }
        if (out.length) {
            registerFaces();
            renderUI();
            document.dispatchEvent(new CustomEvent('mf:skinchanger-items'));
        }
        return out;
    }

    async function removeItem(name) {
        await dbDelete(name);
        state.items = state.items.filter(i => i.name !== name);
        if (state.current === name) state.current = null;
        registerFaces();
        renderUI();
        document.dispatchEvent(new CustomEvent('mf:skinchanger-items'));
    }

    async function registerFaces() {
        const FS = window.MF_FaceSwap;
        if (!FS?.registerSource) return;
        const faces = [];
        for (const item of state.items) {
            faces.push({
                name: 'skin_' + item.name,
                thumb: item.thumb,
                dataURL: item.dataURL,
                region: SKIN_FACE
            });
        }
        try { await FS.registerSource('skinchanger', faces); } catch (e) {
            console.warn(TAG + ' registerFaces: ' + e.message);
        }
    }

    function applyAtTick(tick, name, durationTicks) {
        const FS = window.MF_FaceSwap;
        const TPS = 20;
        const dur = Math.max(1, Math.round(durationTicks || TPS));
        if (FS?.applyAtTick) {
            FS.applyAtTick(tick, 'skin_' + name, 'skin', dur);
            return { ok: true };
        }
        return { ok: false, error: 'FaceSwap no disponible' };
    }

    function buildUI() {
        if (document.getElementById(ID)) { renderUI(); return; }
        const style = document.createElement('style');
        style.id = ID + '-style';
        style.textContent = `
            #${ID} { position:fixed; top:70px; right:16px; z-index:2147483000;
  background:#14141a; border:1px solid #32323a; border-radius:8px;
  box-shadow:0 8px 32px rgba(0,0,0,.6); color:#e8e8ee;
  font:12px/1.4 system-ui,sans-serif; user-select:none; width:280px; }
  #${ID} .mfsch-head { display:flex; align-items:center; gap:8px; padding:8px 10px;
  border-bottom:1px solid #26262e; font-weight:700; letter-spacing:.5px; }
  #${ID} .mfsch-head .dot { width:8px; height:8px; border-radius:50%;
  background:#4dff88; animation:mfsch-pulse 1.5s infinite; }
  @keyframes mfsch-pulse { 50% { opacity:.35; } }
  #${ID} .mfsch-drop { margin:8px 10px; padding:12px 8px; text-align:center;
  border:1px dashed #3a3a44; border-radius:6px; color:#9a9aa6; cursor:pointer; font-size:11px; }
  #${ID} .mfsch-drop:hover, #${ID} .mfsch-drop.over { border-color:#4dff88; color:#4dff88; }
  #${ID} .mfsch-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:6px;
  padding:4px 10px 8px; max-height:260px; overflow-y:auto; }
  #${ID} .mfsch-item { position:relative; border:1px solid #32323a; border-radius:6px;
  padding:4px 2px 2px; cursor:pointer; text-align:center; background:#191921; }
  #${ID} .mfsch-item:hover { border-color:#4dff88; }
  #${ID} .mfsch-item.on { border-color:#ff6b2b; background:#241d16; }
  #${ID} .mfsch-item img { width:40px; height:40px; image-rendering:pixelated; border-radius:4px; }
  #${ID} .mfsch-item .nm { display:block; font-size:9px; color:#9a9aa6;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  #${ID} .mfsch-item .del { position:absolute; top:2px; right:2px; display:none;
  background:#3a1c1c; color:#ff7d7d; border:none; border-radius:3px;
  font-size:9px; padding:1px 4px; cursor:pointer; }
  #${ID} .mfsch-item:hover .del { display:block; }
  #${ID} button { background:#23232c; color:#e8e8ee; border:1px solid #3a3a44;
  border-radius:4px; padding:3px 8px; cursor:pointer; font:inherit; }
  #${ID} button:hover { background:#2e2e3a; }
  #${ID} .mfsch-foot { display:flex; gap:6px; padding:6px 10px 10px; }
        `;
        document.body.appendChild(style);
        const root = document.createElement('div');
        root.id = ID;
        root.innerHTML = `
            <div class="mfsch-head"><span class="dot"></span>👕 SKINS — en vivo
    <button data-act="close" style="margin-left:auto" title="Cerrar">✕</button></div>
        <div class="mfsch-drop" title="Importar PNGs de skin (64x64 o 64x32)">📂 Suelta skins .png aquí<br>o haz click para elegir</div>
            <div class="mfsch-grid" id="mfsch-grid"></div>
                <div class="mfsch-foot">
    <button data-act="revert" title="Volver a la skin original del juego">↺ Original</button>
    <button data-act="help" title="Cómo usar">?</button>
        </div>
        `;
        document.body.appendChild(root);
        bindUI(root);
    }

    function renderUI() {
        const root = document.getElementById(ID);
        if (!root) return;
        const grid = root.querySelector('#mfsch-grid');
        if (!grid) return;
        grid.innerHTML = '';
        if (!state.items.length) {
            grid.innerHTML = '<div style="grid-column:1/-1;color:#8a8a96;font-size:11px;text-align:center;padding:8px;">No imported skins yet</div>';
            return;
        }
        for (const item of state.items) {
            const d = document.createElement('div');
            d.className = 'mfsch-item' + (state.current === item.name ? ' on' : '');
            d.title = item.name + ' (' + item.w + 'x' + item.h + ') — click = apply · drag to V2 timeline';
            d.draggable = true;
            d.innerHTML = `<img src="${item.thumb}" alt=""><span class="nm">${item.name}</span><button class="del" title="Remove from library">✕</button>`;
            d.ondragstart = (ev) => {
                ev.dataTransfer.setData('text/mf-skin', item.name);
                ev.dataTransfer.setData('text/plain', item.name);
                ev.dataTransfer.effectAllowed = 'copy';
            };
            d.onclick = () => {
                apply(item.name).then(() => {
                    renderUI();
                    void 0;
                }).catch(e => console.warn(TAG + ' ' + e.message));
            };
            d.querySelector('.del').onclick = (ev) => {
                ev.stopPropagation();
                removeItem(item.name);
            };
            grid.appendChild(d);
        }
    }

    function bindUI(root) {
        const drop = root.querySelector('.mfsch-drop');
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/png,.png';
        input.multiple = true;
        input.style.display = 'none';
        root.appendChild(input);
        drop.onclick = () => input.click();
        input.onchange = () => {
            importFiles(input.files).then(items => {
                if (items.length) void 0;
            });
            input.value = '';
        };
        drop.ondragover = (ev) => { ev.preventDefault(); drop.classList.add('over'); };
        drop.ondragleave = () => drop.classList.remove('over');
        drop.ondrop = (ev) => {
            ev.preventDefault();
            ev.stopPropagation();
            drop.classList.remove('over');
            importFiles(ev.dataTransfer.files);
        };
        root.querySelector('[data-act="close"]').onclick = () => close();
        root.querySelector('[data-act="revert"]').onclick = () => {
            const r = revert();
            renderUI();
            void 0;
        };
        root.querySelector('[data-act="help"]').onclick = () => {
            void 0;
        };
    }

    function open() {
        if (state.open) { renderUI(); return; }
        state.open = true;
        load().then(() => { buildUI(); renderUI(); });
    }

    function close() {
        document.getElementById(ID)?.remove();
        document.getElementById(ID + '-style')?.remove();
        state.open = false;
    }

    async function load() {
        try {
            state.items = await dbAll();
            state.items.sort((a, b) => a.name.localeCompare(b.name));
            registerFaces();
        } catch (e) {
            console.warn(TAG + ' load: ' + e.message);
            state.items = [];
        }
    }

    window.MF_SkinChanger = {
        open, close,
        apply, revert,
        importFiles,
        applyAtTick,
        get items() { return state.items; },
        get current() { return state.current; },
        faces() {
            return state.items.map(i => ({ name: 'skin_' + i.name, thumb: i.thumb }));
        }
    };
    window.__MF_SkinChanger = true;

    load().catch(() => {});

    void 0;
})();

