/* ==== mf module: src/Studio/MF_Facial.js ==== */

(function () {
    'use strict';
    if (window.__MF_Facial) return;
    const TAG = 'minifeather facial';

    const ID = 'mf-facial';
    const LS_KEY = 'minifeather_facials_v1';
    const FACE = { x: 8, y: 8, w: 8, h: 8 };
    const FACE_OV = { x: 40, y: 8, w: 8, h: 8 };

    const state = {
        open: false,
        library: {},

        playing: null,

        playTimer: null,

        baseHead: null,

        tex: null,

        frameCache: new Map(),
        dirty: true
    };

    function getGame() {
        if (globalThis.miniblox?.player) return globalThis.miniblox;
        try {
            const react = document.querySelector('#react');
            if (react) for (const root of Object.values(react)) {
                const g = root?.updateQueue?.baseState?.element?.props?.game;
                if (g?.player) return g;
            }
        } catch {}
        return null;
    }

    function getMesh() {
        const g = getGame();
        const me = g?.player;
        if (!me) return null;
        try { const e = g.world?.getPlayerById?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        try { const e = g.world?.players?.get?.(me.id); if (e?.mesh) return e.mesh; } catch {}
        return me?.mesh || null;
    }
    function capeMeshesOf(mesh) {
        const out = [];
        try {
            if (mesh?.capeMesh) out.push(mesh.capeMesh);
            mesh?.traverse?.(o => {
                if (o && o !== mesh && o.capeMesh && !out.includes(o.capeMesh)) out.push(o.capeMesh);
            });
        } catch {}
        return out;
    }
    function armorMeshesOf(mesh) {
        const out = [];
        try {
            const regs = [mesh?.skinnedArmor, mesh?.armorMesh, mesh?.lodArmor];
            for (const reg of regs) {
                if (reg && typeof reg === 'object') {
                    for (const k in reg) if (reg[k]) out.push(reg[k]);
                }
            }
            const mreg = mesh && mesh.meshes;
            if (mreg && typeof mreg === 'object') {
                for (const k in mreg) {
                    if (/helmet|chestplate|leggings|boots|armor/i.test(k) && mreg[k]) out.push(mreg[k]);
                }
            }
            mesh?.traverse?.(o => {
                if (o && o !== mesh && o.name && /helmet|chestplate|leggings|boots|armor/i.test(o.name) && !out.includes(o)) out.push(o);
            });
        } catch {}
        return out;
    }

    function findSkinMaterials(mesh) {
        const out = [];
        if (!mesh) return out;
        const seen = new Set();
        mesh.traverse(o => {
            if (!o?.material) return;
            const list = Array.isArray(o.material) ? o.material : [o.material];
            for (const m of list) {
                if (m?.map && !seen.has(m)) { seen.add(m); out.push(m); }
            }
        });
        const capeMats = new Set();
        capeMeshesOf(mesh).forEach(cm => cm.traverse(o => {
            if (!o?.material) return;
            const list = Array.isArray(o.material) ? o.material : [o.material];
            for (const m of list) if (m?.map) capeMats.add(m);
        }));
        armorMeshesOf(mesh).forEach(am => am.traverse(o => {
            if (!o?.material) return;
            const list = Array.isArray(o.material) ? o.material : [o.material];
            for (const m of list) if (m?.map) capeMats.add(m);
        }));
        const body = out.filter(m => !capeMats.has(m));
        const skins = body.filter(m => {
            const w = m.map?.image?.width, h = m.map?.image?.height;
            if (!w || !h) return false;
            const k64 = w / 64;
            return Number.isInteger(k64) && (h === w || h === w / 2) && k64 <= 4;
        });
        return skins.length ? skins : (body.length ? body : out);
    }

    function resolveFace(name) {
        if (state.frameCache.has(name)) return state.frameCache.get(name);
        const p = (async () => {
            if (name === 'base') {
                return state.baseHead
                    ? { canvas: cloneCanvas(state.baseHead), kind: 'head' }
                    : { canvas: blankFace(), kind: 'face' };
            }
            if (/^p:/.test(name)) {

                const nm = name.replace(/^p:/, '');
                const hit = (window.MF_SkinEditor?.presets?.() || []).find(pr => pr.name === nm);
                if (hit?.thumb) {
                    const img = await loadImg(hit.thumb);
                    const c = document.createElement('canvas');
                    c.width = 64; c.height = 16;
                    const ctx = c.getContext('2d');
                    ctx.imageSmoothingEnabled = false;
                    ctx.drawImage(img, 0, 0);
                    return { canvas: c, kind: 'head' };
                }
                return null;
            }
            if (/^skin_/.test(name)) {

                const nm = name.replace(/^skin_/, '');
                const it = (window.MF_SkinChanger?.items || []).find(i => i.name === nm);
                if (it?.dataURL) {
                    const img = await loadImg(it.dataURL);

                    const k = Math.max(1, Math.round(img.width / 64));
                    const c = document.createElement('canvas');
                    c.width = 8; c.height = 8;
                    const ctx = c.getContext('2d');
                    ctx.imageSmoothingEnabled = false;
                    ctx.drawImage(img, 8 * k, 8 * k, 8 * k, 8 * k, 0, 0, 8, 8);
                    return { canvas: c, kind: 'face' };
                }
                return null;
            }
            if (/^fs:/.test(name)) {

                const slash = name.indexOf('/');
                if (slash < 0) return null;
                const id = name.slice(3, slash), file = name.slice(slash + 1);
                const img = await packImg(id, file).catch(() => null);
                if (!img) return null;

                const sk = Math.max(1, Math.round(img.width / 32));
                const c = document.createElement('canvas');
                c.width = 64 * sk; c.height = 16 * sk;
                const ctx = c.getContext('2d');
                ctx.imageSmoothingEnabled = false;

                if (state.baseHead) ctx.drawImage(state.baseHead, 0, 0, 64 * sk, 16 * sk);
                ctx.drawImage(img, 0, 0, img.width, img.height, 0, 0, 32 * sk, 16 * sk);
                return { canvas: c, kind: 'head', k: sk };
            }

            const cv = await window.MF_FaceSwap?.loadFaceCanvas?.(name);
            if (cv) return { canvas: cv, kind: 'face' };
            return null;
        })();
        state.frameCache.set(name, p);

        p.then(v => { if (v === null && /^fs:/.test(name)) state.frameCache.delete(name); }).catch(() => {});
        return p;
    }

    function blankFace() {
        const c = document.createElement('canvas');
        c.width = 8; c.height = 8;
        return c;
    }

    function cloneCanvas(src, w, h) {
        const c = document.createElement('canvas');
        c.width = w || src.width; c.height = h || src.height;
        c.getContext('2d').drawImage(src, 0, 0);
        return c;
    }

    function loadImg(url) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error('could not load the image'));
            img.src = url;
        });
    }

    const PACKS_DIR = 'skins/facialskins/';
    const packImgCache = new Map();

    function extAssetUrl(rel) {
        if (typeof chrome !== 'undefined' && chrome.runtime?.getURL) {
            return chrome.runtime.getURL(rel);
        }

        const meta = document.querySelector('meta[name="mf-skins-base"]');
        const base = meta?.content;
        if (base) {
            const b = base.replace(/\/$/, '') + '/';

            const noPrefix = rel.replace(/^skins\//, '');
            return b + noPrefix;
        }
        return null;
    }

    function packBaseUrl(packId) {
        const serverKnown = [
            'adele', 'adventure', 'aether', 'alice', 'apex', 'ariel', 'aurora',
            'banana', 'bob', 'cat', 'celeste', 'ethan'
        ];
        return serverKnown.includes(packId) ? PACKS_DIR : MY_PACKS_DIR;
    }

    function loadPackImg(id, file) {
        const key = id + '/' + file;
        if (packImgCache.has(key)) return packImgCache.get(key);
        const url = extAssetUrl(packBaseUrl(id) + id + '/' + file + '.png');
        const p = url
            ? loadImg(url).catch(() => null)
            : Promise.resolve(null);
        packImgCache.set(key, p);
        return p;
    }

    const FRONT_NAMES = ['alfrente', 'al frente', 'afrente', 'al frente1', 'frente'];
    async function loadPackFront(id) {
        for (const n of FRONT_NAMES) {
            const img = await loadPackImg(id, n);
            if (img) return { img, usedName: n };
        }
        return null;
    }

    function normSkinId(v) {
        if (typeof v !== 'string' || !v) return '';
        let s = v.split('/').pop().replace(/\.png$/i, '');
        const cl = CUSTOM_PREFIX + MF_NAME_PREFIX;

        if (s.toLowerCase().startsWith(cl)) s = s.slice(cl.length);
        else if (s.toLowerCase().startsWith(MFPACK_PREFIX)) s = s.slice(MFPACK_PREFIX.length);
        return s.toLowerCase();
    }

    function currentSkinId() {

        const norm = normSkinId;
        try {
            const sc = window.MF_SkinChanger?.current;
            if (typeof sc === 'string' && sc) return norm(sc);
        } catch {}
        const g = getGame();
        const me = g?.player;
        const cand = [
            me?.profile?.cosmetics?.skin,
            me?.profile?.skin,
            me?.mesh?.model?.skin,
            me?.mesh?.entity?.profile?.cosmetics?.skin,
            g?.world?.getPlayerById?.(me?.id)?.profile?.cosmetics?.skin
        ];
        for (const c of cand) {
            if (typeof c === 'string' && c) {
                const id = norm(c);
                if (id) return id;
            }
        }
        return apiSkin.value;
    }

    const apiSkin = { value: null, lastPatch: null };
    function noteApiSkin(id) {
        if (typeof id !== 'string' || !id) return;
        const clean = id.split('/').pop().replace(/\.png$/i, '').toLowerCase();
        if (clean && clean !== apiSkin.value) {
            void 0;
            apiSkin.value = clean;
        }
    }
    function extractSkinFromBody(text) {
        try {
            const j = JSON.parse(text);
            if (typeof j?.skin === 'string') return j.skin;
        } catch {}
        return null;
    }

    try {
        const origFetch = window.fetch;
        window.fetch = function (input, init) {
            let url = '';
            try {
                url = typeof input === 'string' ? input : (input?.url || '');
            } catch {}
            const p = origFetch.apply(this, arguments);
            if (url.includes('/auth-api/accounts/me')) {
                try {

                    const method = (init?.method || (input?.method) || 'GET').toUpperCase();
                    const body = init?.body || input && typeof input !== 'string' ? (input?.body ?? init?.body) : init?.body;
                    if (method !== 'GET' && method !== 'HEAD' && body) {
                        try { noteApiSkin(extractSkinFromBody(String(body))); } catch {}
                    }
                    p.then(r => {
                        try {
                            if (r.ok) r.clone().text().then(t => noteApiSkin(extractSkinFromBody(t))).catch(() => {});
                        } catch {}
                        return r;
                    }).catch(() => {});
                } catch {}
            }
            return p;
        };
    } catch {}

    try {
        const origJson = Response.prototype.json;
        if (!origJson.__mfFacialSkin) {
            const wrapped = async function (...args) {
                const j = await origJson.apply(this, args);
                try {
                    if (typeof this?.url === 'string' && this.url.includes('/auth-api/accounts/me') &&
                        typeof j?.skin === 'string') {
                        noteApiSkin(j.skin);
                    }
                } catch {}
                return j;
            };
            Object.defineProperty(wrapped, '__mfFacialSkin', { value: true });
            Response.prototype.json = wrapped;
        }
    } catch {}

    const apiFetchFail = { at: -1e9 };
    function fetchApiSkin(maxAgeMs = 8000) {

        if (apiSkin.value) return Promise.resolve(apiSkin.value);
        if (performance.now() - apiFetchFail.at < 60000) return Promise.resolve(null);
        return fetch(location.origin + '/auth-api/accounts/me', {
            method: 'POST',
            credentials: 'include', cache: 'no-store',
            headers: { 'content-type': 'application/json' },
            body: '{}'
        })
            .then(r => {
                if (!r.ok) { apiFetchFail.at = performance.now(); return null; }
                return r.json();
            })
            .then(j => { noteApiSkin(j?.skin); return apiSkin.value; })
            .catch(() => { apiFetchFail.at = performance.now(); return apiSkin.value; });
    }

    function currentPlayerUuid() {
        const g = getGame() || globalThis.__MINIBLOX_GAME__ || null;
        const me = g?.player;
        if (!me) return null;
        const isUuid = (v) => typeof v === 'string' &&
            /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
        if (isUuid(me.uuid)) return me.uuid.toLowerCase();
        if (isUuid(me.profile?.uuid)) return me.profile.uuid.toLowerCase();
        if (isUuid(me.id)) return me.id.toLowerCase();

        try {
            const pl = g?.playerList;
            const entries = pl?.values ? [...pl.values()] : (pl ? Object.values(pl) : []);
            for (const e of entries) {
                if ((isUuid(e?.uuid) && (e.uuid === me.uuid || e.id === me.id)) ||
                    (e?.username === me.username && isUuid(e?.uuid))) {
                    return e.uuid.toLowerCase();
                }
            }
        } catch {}
        return null;
    }

    const packIndex = [];

    const PACKS_DB = 'minifeather_facialpacks';
    let packsDb = null;
    function packsDbOpen() {
        if (packsDb) return Promise.resolve(packsDb);
        return new Promise((res, rej) => {
            const rq = indexedDB.open(PACKS_DB, 1);
            rq.onupgradeneeded = () => rq.result.createObjectStore('packs', { keyPath: 'id' });
            rq.onsuccess = () => { packsDb = rq.result; res(packsDb); };
            rq.onerror = () => rej(rq.error);
        });
    }
    function packsDbAll() {
        return packsDbOpen().then(db => new Promise((res, rej) => {
            const rq = db.transaction('packs', 'readonly').objectStore('packs').getAll();
            rq.onsuccess = () => res(rq.result || []);
            rq.onerror = () => rej(rq.error);
        }));
    }
    function packsDbPut(item) {
        return packsDbOpen().then(db => new Promise((res, rej) => {
            const rq = db.transaction('packs', 'readwrite').objectStore('packs').put(item);
            rq.onsuccess = () => res(true);
            rq.onerror = () => rej(rq.error);
        }));
    }
    function packsDbDel(id) {
        return packsDbOpen().then(db => new Promise((res, rej) => {
            const rq = db.transaction('packs', 'readwrite').objectStore('packs').delete(id);
            rq.onsuccess = () => res(true);
            rq.onerror = () => rej(rq.error);
        }));
    }

    async function packImg(id, file) {
        const custom = customPacks.get(id);
        if (custom) {
            const key = id + '/' + file;
            if (packImgCache.has(key)) return packImgCache.get(key);
            const du = custom.sprites[file] || null;
            const p = du ? loadImg(du).catch(() => null) : Promise.resolve(null);
            packImgCache.set(key, p);
            return p;
        }

        return loadPackImg(id, file.replace(/\.png$/i, ''));
    }

    async function zipRead(buf) {
        const dv = new DataView(buf);
        const files = new Map();

        let eocd = -1;
        for (let i = buf.byteLength - 22; i >= Math.max(0, buf.byteLength - 66000); i--) {
            if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
        }
        if (eocd < 0) throw new Error('invalid ZIP (no EOCD)');
        const count = dv.getUint16(eocd + 10, true);
        let off = dv.getUint32(eocd + 16, true);
        const entries = [];
        for (let i = 0; i < count; i++) {
            if (dv.getUint32(off, true) !== 0x02014b50) break;
            const method = dv.getUint16(off + 10, true);
            const csize = dv.getUint32(off + 20, true);
            const nlen = dv.getUint16(off + 28, true);
            const elen = dv.getUint16(off + 30, true);
            const clen = dv.getUint16(off + 32, true);
            const lho = dv.getUint32(off + 42, true);
            const name = new TextDecoder().decode(new Uint8Array(buf, off + 46, nlen));
            entries.push({ name, method, csize, lho });
            off += 46 + nlen + elen + clen;
        }

        for (const e of entries) {
            if (e.name.endsWith('/')) { files.set(e.name, null); continue; }
            if (dv.getUint32(e.lho, true) !== 0x04034b50) continue;
            const nlen = dv.getUint16(e.lho + 26, true);
            const elen = dv.getUint16(e.lho + 28, true);
            const start = e.lho + 30 + nlen + elen;
            const raw = new Uint8Array(buf, start, e.csize);
            let data = raw;
            if (e.method === 8) {
                const ds = new DecompressionStream('deflate-raw');
                const stream = new Blob([raw]).stream().pipeThrough(ds);
                data = new Uint8Array(await new Response(stream).arrayBuffer());
            } else if (e.method !== 0) continue;
            files.set(e.name, data);
        }
        return files;
    }

    function zipWrite(files) {
        const enc = new TextEncoder();
        const chunks = [];
        const central = [];
        let offset = 0;
        const crcTable = (() => {
            const t = new Uint32Array(256);
            for (let n = 0; n < 256; n++) {
                let c = n;
                for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
                t[n] = c >>> 0;
            }
            return t;
        })();
        const crc32 = (d) => {
            let c = 0xFFFFFFFF;
            for (let i = 0; i < d.length; i++) c = crcTable[(c ^ d[i]) & 0xFF] ^ (c >>> 8);
            return (c ^ 0xFFFFFFFF) >>> 0;
        };
        for (const [name, data] of files) {
            const nb = enc.encode(name);
            const crc = crc32(data);
            const lh = new Uint8Array(30 + nb.length);
            const lv = new DataView(lh.buffer);
            lv.setUint32(0, 0x04034b50, true);
            lv.setUint16(4, 20, true);

            lv.setUint16(6, 0, true);

            lv.setUint16(8, 0, true);

            lv.setUint16(10, 0, true);

            lv.setUint16(12, 0, true);

            lv.setUint32(14, crc, true);
            lv.setUint32(18, data.length, true);
            lv.setUint32(22, data.length, true);
            lv.setUint16(26, nb.length, true);
            lv.setUint16(28, 0, true);
            lh.set(nb, 30);
            chunks.push(lh, data);
            central.push({ nb, crc, size: data.length, offset });
            offset += lh.length + data.length;
        }
        const cdStart = offset;
        for (const c of central) {
            const ch = new Uint8Array(46 + c.nb.length);
            const cv = new DataView(ch.buffer);
            cv.setUint32(0, 0x02014b50, true);
            cv.setUint16(4, 20, true);
            cv.setUint16(6, 20, true);
            cv.setUint32(16, c.crc, true);
            cv.setUint32(20, c.size, true);
            cv.setUint32(24, c.size, true);
            cv.setUint16(28, c.nb.length, true);
            cv.setUint32(42, c.offset, true);
            ch.set(c.nb, 46);
            chunks.push(ch);
            offset += ch.length;
        }
        const eocd = new Uint8Array(22);
        const ev = new DataView(eocd.buffer);
        ev.setUint32(0, 0x06054b50, true);
        ev.setUint16(8, central.length, true);
        ev.setUint16(10, central.length, true);
        ev.setUint32(12, offset - cdStart, true);
        ev.setUint32(16, cdStart, true);
        chunks.push(eocd);
        return new Blob(chunks, { type: 'application/zip' });
    }

    async function importPackZip(file) {
        const buf = await file.arrayBuffer();
        const files = await zipRead(buf);

        const names = [...files.keys()];
        const pjName = names.find(n => /(^|\/)pack\.json$/i.test(n));
        if (!pjName) throw new Error('the ZIP has no pack.json');
        const dir = pjName.includes('/') ? pjName.slice(0, pjName.lastIndexOf('/') + 1) : '';
        const j = JSON.parse(new TextDecoder().decode(files.get(pjName)));
        const id = String(j.id || file.name.replace(/\.zip$/i, '')).toLowerCase().replace(/[^a-z0-9_-]/g, '');
        if (!id) throw new Error('pack.json without "id"');

        const pick = (v, fallback) => {
            const n = typeof v === 'string' ? v : (v && v.file);
            return n ? dir + n : fallback;
        };
        const pack = {
            id,
            name: String(j.name || id),
            author: String(j.author || ''),
            version: +j.version || 1,
            uuid: typeof j.uuid === 'string' ? j.uuid.toLowerCase() : null,
            skin: null,
            sprites: { front: null, left: null, right: null, up: null, down: null, blink: null }
        };
        const want = new Set();
        const sp = j.sprites || {};
        const spriteFiles = {
            front: pick(sp.front, dir + 'alfrente.png'),
            left: pick(sp.left, dir + 'izquierda.png'),
            right: pick(sp.right, dir + 'derecha.png'),
            up: pick(sp.up, null),

            down: pick(sp.down, null),
            brow: pick(sp.brow, null),
            blink: pick(sp.blink, dir + 'blink.png')
        };
        for (const k in spriteFiles) if (spriteFiles[k]) want.add(spriteFiles[k]);
        const skinFile = j.skin ? dir + j.skin : null;
        if (skinFile) want.add(skinFile);

        const lower = new Map([...files.keys()].map(n => [n.toLowerCase(), n]));
        const resolve = (wantName) => {
            if (files.has(wantName)) return wantName;
            return lower.get(wantName.toLowerCase()) || null;
        };
        const blobOf = async (name) => {
            if (!name) return null;
            const rn = resolve(name);
            const d = rn ? files.get(rn) : null;
            if (!d) return null;
            return await new Promise(res => {
                const fr = new FileReader();
                fr.onload = () => res(fr.result);
                fr.onerror = () => res(null);
                fr.readAsDataURL(new Blob([d], { type: 'image/png' }));
            });
        };
        const OPTIONAL = new Set(['up', 'down', 'brow']);
        for (const key in spriteFiles) {
            const du = await blobOf(spriteFiles[key]);
            if (!du) {
                if (OPTIONAL.has(key)) continue;
                throw new Error('missing sprite "' + key + '" (' + spriteFiles[key] + ')');
            }
            pack.sprites[key] = du;
        }
        pack.skin = await blobOf(skinFile);

        for (const key of [...packImgCache.keys()]) {
            if (key.startsWith(id + '/')) packImgCache.delete(key);
        }
        for (const key of [...state.frameCache.keys()]) {
            if (key.startsWith('fs:' + id + '/')) state.frameCache.delete(key);
        }
        auto._blinkCache = null; auto._blinkCacheZone = null; auto._blinkCacheKind = null;

        await packsDbPut(pack);
        await loadCustomPacks();

        try {
            const saved = JSON.parse(localStorage.getItem('mff:mypacks') || '[]');
            if (!saved.includes(id)) {
                saved.push(id);
                localStorage.setItem('mff:mypacks', JSON.stringify(saved));
            }
        } catch {}

        try { await applyPackSkinToGame(id); } catch {}
        return pack;
    }

    async function exportPackZip(id) {
        const p = packIndex.find(x => x.id === id);
        if (!p) throw new Error('pack "' + id + '" not found');
        const files = [];
        const j = { id: p.id, name: p.name || p.id, author: p.author || '', version: p.version || 1 };
        const sprites = {};
        const map = { front: p.front, left: p.left, right: p.right, blink: p.blink };
        const custom = customPacks.get(id);
        let bytes = async (file) => null;
        if (custom) {
            bytes = async (key) => {
                const du = custom.sprites[key];
                if (!du) return null;
                const b = await (await fetch(du)).blob();
                return new Uint8Array(await b.arrayBuffer());
            };
        } else {
            bytes = async (file) => {
                const img = await loadPackImg(id, file.replace(/\.png$/i, ''));
                if (!img) return null;

                const b = await (await fetch(img.src)).blob();
                return new Uint8Array(await b.arrayBuffer());
            };
        }
        for (const k in map) {
            if (!map[k]) continue;
            const base = custom ? k : map[k].replace(/\.png$/i, '');
            const d = await bytes(custom ? k : map[k]);
            if (d) {
                files.push([base + '.png', d]);
                sprites[k] = base + '.png';
            }
        }
        if (custom && custom.skin) {
            const b = await (await fetch(custom.skin)).blob();
            const d = new Uint8Array(await b.arrayBuffer());
            files.push([id + '.png', d]);
            j.skin = id + '.png';
        } else if (p.skinFile) {
            const base = p.skinFile.replace(/\.png$/i, '');
            const d = await bytes(p.skinFile);
            if (d) { files.push([base + '.png', d]); j.skin = base + '.png'; }
        }
        j.sprites = sprites;
        files.push(['pack.json', new TextEncoder().encode(JSON.stringify(j, null, 2))]);
        const blob = zipWrite(files);
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = p.id + '-pack.zip';
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
        return { ok: true, files: files.length };
    }

    const customPacks = new Map();
    async function loadCustomPacks() {
        try {
            const all = await packsDbAll();
            customPacks.clear();
            for (const p of all) customPacks.set(p.id, p);
        } catch {}
        rebuildPackIndex();
    }

    const MFPACK_PREFIX = 'mfpack:';

    const CUSTOM_PREFIX = 'custom:';

    const MF_NAME_PREFIX = 'mf_';

    const CUSTOM_SKIN_URL = '/auth-api/skins/custom/';
    function packSkinUrl(packId) {

        const custom = customPacks.get(packId);
        if (custom?.skin) return custom.skin;

        const p = builtinPacks.find(x => x.id === packId && !x.server);
        if (p) {
            const base = p.skinFile ? MY_PACKS_DIR + packId + '/' + p.skinFile
                                    : MY_PACKS_DIR + packId + '/' + packId + '.png';
            return extAssetUrl(base);
        }

        return null;
    }

    const packSkinReg = (globalThis.__MF_PACK_SKINS__ ||= {});
    const CUSTOM_URL_RE = /(?:^|\/)auth-api\/skins\/custom\/([^\/?#]+)\.png(?:[?#]|$)/;
    function registerPackSkin(packId) {
        const url = packSkinUrl(packId);
        if (!url) return false;
        packSkinReg[MF_NAME_PREFIX + packId] = url;
        return true;
    }

    function installPackImgHook() {
        if (globalThis.__MF_PACK_IMG_HOOK__) return;
        const proto = HTMLImageElement.prototype;
        const d = Object.getOwnPropertyDescriptor(proto, 'src');
        if (!d?.set || !d?.get) return;
        const origSet = d.set;
        Object.defineProperty(proto, 'src', {
            configurable: true,
            enumerable: d.enumerable,
            get() { return d.get.call(this); },
            set(v) {
                if (typeof v === 'string') {
                    const reg = globalThis.__MF_PACK_SKINS__;
                    if (reg) {

                        const m = v.match(CUSTOM_URL_RE);
                        if (m && reg[m[1]]) {
                            origSet.call(this, reg[m[1]]);
                            return;
                        }

                        const m2 = v.match(/^textures\/entity\/skins\/([^/?#]+)\.png/);
                        if (m2 && reg[m2[1]]) {
                            origSet.call(this, reg[m2[1]]);
                            return;
                        }
                    }
                }
                origSet.call(this, v);
            }
        });
        globalThis.__MF_PACK_IMG_HOOK__ = true;
    }

    const PACK_LAST_KEY = 'mff:pack-last-server-skin';
    function rememberServerSkin(id) {
        packLastServerSkin = id;
        try { sessionStorage.setItem(PACK_LAST_KEY, id); } catch {}
    }
    function savedServerSkin() {
        if (packLastServerSkin) return packLastServerSkin;
        try {
            const v = sessionStorage.getItem(PACK_LAST_KEY);
            if (v && !String(v).startsWith(MFPACK_PREFIX) && !String(v).startsWith(CUSTOM_PREFIX)) {
                return v;
            }
        } catch {}
        return null;
    }

    let packLastServerSkin = null;
    async function applyPackSkinToGame(packId) {
        const g = getGame();
        const me = g?.player;
        if (!g || !me) throw new Error('no game loaded (enter a world first)');
        if (!registerPackSkin(packId)) throw new Error('the pack has no PNG skin');

        const cur = me.profile?.cosmetics?.skin;
        if (cur && !String(cur).startsWith(MFPACK_PREFIX) && !String(cur).startsWith(CUSTOM_PREFIX)) {
            rememberServerSkin(cur);
        }

        try { window.MF_SkinChanger?.release?.(); } catch {}
        me.profile.cosmetics.skin = CUSTOM_PREFIX + MF_NAME_PREFIX + packId;

        let mesh = null;
        try { mesh = g.world?.getPlayerById?.(me.id)?.mesh || me.mesh; } catch {}
        try {
            if (mesh?.recreate) await mesh.recreate();
            else if (typeof mesh?.init === 'function') await mesh.init();
        } catch {}
        return true;
    }

    async function releasePackSkin() {
        const g = getGame();
        const me = g?.player;
        if (!g || !me) throw new Error('no game loaded');
        const cur = me.profile?.cosmetics?.skin;
        if (!String(cur || '').startsWith(MFPACK_PREFIX) &&
            !String(cur || '').startsWith(CUSTOM_PREFIX)) return false;

        const backup = savedServerSkin();
        me.profile.cosmetics.skin = backup || '';
        let mesh = null;
        try { mesh = g.world?.getPlayerById?.(me.id)?.mesh || me.mesh; } catch {}
        try {
            if (mesh?.recreate) await mesh.recreate();
            else if (typeof mesh?.init === 'function') await mesh.init();
        } catch {}
        packLastServerSkin = null;
        try { sessionStorage.removeItem(PACK_LAST_KEY); } catch {}
        return true;
    }

    function rebuildPackIndex() {
        packIndex.length = 0;
        for (const p of builtinPacks) packIndex.push(p);
        for (const p of customPacks.values()) {
            packIndex.push({
                id: p.id, name: p.name, author: p.author, version: p.version,
                uuid: p.uuid || null,

                front: 'front', left: 'left',
                right: 'right', blink: 'blink',
                up: p.sprites.up ? 'up' : null,

                down: p.sprites.down ? 'down' : null,
                brow: p.sprites.brow ? 'brow' : null,
                skinFile: null, custom: true, server: false
            });
        }

        installPackImgHook();
        for (const p of packIndex) { try { registerPackSkin(p.id); } catch {} }
        renderPacksTab();
    }

    const builtinPacks = [];
    const SERVER_SKINS = new Set([
        'bob', 'alice', 'techno', 'ganyu', 'klee', 'hutao', 'kyoko',
        'georgenotfound', 'thebiggelo', 'jake', 'diana', 'holly',
        'endoskeleton', 'strange', 'corrupted', 'james', 'levi', 'deadpool',
        'vindicate', 'galactus', 'suit', 'remus', 'ironman', 'transformer',
        'adele', 'natalie', 'heather', 'lexi', 'sara', 'chris', 'aurora',
        'zane', 'hunter', 'seraphina', 'celeste', 'ember', 'finn',
        'adventure', 'raven', 'nova', 'panda', 'glory', 'cody', 'aether',
        'apex', 'katie', 'vain', 'ariel', 'duck', 'ethan', 'cat', 'tester',
        'remlin', 'sushi', 'qhyun', 'banana'
    ]);
    function isServerSkin(id) { return SERVER_SKINS.has(String(id).toLowerCase()); }
    async function loadBuiltinPacks() {
        builtinPacks.length = 0;
        const dirs = await builtinDirs();
        const results = await Promise.all(dirs.map(async (id) => {
            try {
                const url = extAssetUrl(packBaseUrl(id) + id + '/pack.json');
                if (!url) return null;
                const r = await fetch(url, { cache: 'no-store' });
                if (!r.ok) return null;
                const j = await r.json();
                const sp = j.sprites || {};
                return {
                    id: (j.id || id).toLowerCase(),
                    name: j.name || id,
                    author: j.author || '',
                    version: +j.version || 1,
                    uuid: typeof j.uuid === 'string' ? j.uuid.toLowerCase() : null,
                    front: sp.front || null,
                    left: sp.left || 'izquierda.png',
                    right: sp.right || 'derecha.png',
                    up: sp.up || null,

                    down: sp.down || null,
                    brow: sp.brow || null,
                    blink: sp.blink || 'blink.png',
                    skinFile: j.skin || null,

                    server: isServerSkin(j.id || id)
                };
            } catch { return null; }
        }));
        for (const p of results) if (p) builtinPacks.push(p);
        rebuildPackIndex();
    }

    const MY_PACKS_DIR = 'skins/mypacks/';

    const MY_PACKS_IDS = ['shusukegxe', 'angrywolfx', 'eve'];
    async function builtinDirs() {
        const known = [
            'adele', 'adventure', 'aether', 'alice', 'apex', 'ariel', 'aurora',
            'banana', 'bob', 'cat', 'celeste', 'ethan'
        ];
        const mine = [...MY_PACKS_IDS];
        try {
            const saved = JSON.parse(localStorage.getItem('mff:mypacks') || '[]');
            for (const id of saved) if (!known.includes(id) && !mine.includes(id)) mine.push(id);
        } catch {}
        return [...known, ...mine];
    }

    function packFileUrl(id, file) {
        const custom = customPacks.get(id);
        if (custom) return custom.sprites[file] || null;
        return extAssetUrl(packBaseUrl(id) + id + '/' + file);
    }

    function ensureSession() {
        const mesh = getMesh();
        if (!mesh) throw new Error('player not available (enter a world first)');
        const mats = findSkinMaterials(mesh);
        if (!mats.length) throw new Error('no skin material found');
        const src = mats[0].map;
        if (!src?.image) throw new Error('skin texture not readable');

        const skinIdNow = currentSkinId();
        const srcIsOurs = !!(src.__mfLocalCanvas || src.__mfOtherKey || src.__mfPeerCanvas);
        if (!srcIsOurs) state.authTex = src;

        if ((!state.baseHead || state.baseHeadSkin !== skinIdNow) && !auto._blinkUntil) {
            const baseSrc = (srcIsOurs && state.authTex?.image) ? state.authTex : src;
            try {
                const k = Math.max(1, Math.round(baseSrc.image.width / 64));
                const c = document.createElement('canvas');
                c.width = 64 * k; c.height = 16 * k;
                c.getContext('2d').drawImage(baseSrc.image, 0, 0, 64 * k, 16 * k, 0, 0, 64 * k, 16 * k);
                state.baseHead = c; state.baseHeadK = k;
                state.baseHeadSkin = skinIdNow;
                state.baseSkinPainted = baseSrc.__mfPainted || null;

                state.frameCache.clear();
                auto._blinkCache = null;
                auto._blinkCacheZone = null;
            } catch {}
        }
        if (src.image instanceof HTMLCanvasElement && (src.__mfLocalCanvas || src.__mfOtherKey || src.__mfPeerCanvas)) {
            state.tex = src;
            return src.image;
        }

        const c = document.createElement('canvas');
        c.width = src.image.width; c.height = src.image.height;
        c.getContext('2d').drawImage(src.image, 0, 0);
        let nt = null;
        try { nt = new src.constructor(c); } catch {}
        if (!nt) throw new Error('could not create an editable texture');

        nt.__mfLocalCanvas = true;
        try {
            nt.magFilter = src.magFilter; nt.minFilter = src.minFilter;
            if (src.colorSpace !== undefined && 'colorSpace' in nt) nt.colorSpace = src.colorSpace;
            nt.flipY = src.flipY; nt.wrapS = src.wrapS; nt.wrapT = src.wrapT;
        } catch {}
        if (state.tex && state.tex !== src && state.tex.__mfLocalCanvas) {
            try { state.tex.dispose(); } catch {}
        }
        for (const m of mats) { m.map = nt; m.needsUpdate = true; }
        state.tex = nt;
        return c;
    }

    function paintFace(frame) {
        const canvas = ensureSession();
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = false;

        const k = Math.max(1, Math.round(canvas.width / 64));
        if (frame.kind === 'head') {
            if (state.baseHead) {
                ctx.drawImage(state.baseHead, 0, 0, state.baseHead.width, state.baseHead.height, 0, 0, 64 * k, 16 * k);
            } else {
                ctx.clearRect(0, 0, 32 * k, 16 * k);
            }
            ctx.drawImage(frame.canvas, 0, 0, frame.canvas.width / 2, frame.canvas.height, 0, 0, 32 * k, 16 * k);
        } else {
            ctx.clearRect(FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k);
            ctx.drawImage(frame.canvas, 0, 0, 8,  8, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k);
        }
        state.tex.needsUpdate = true;
    }

    // canvas de mezcla reutilizado: crear un <canvas> por frame durante un
    // blend era gc a 60fps para dibujar exactamente lo mismo
    let blendScratch = null;
    function blendFrames(a, b, t) {
        const w = Math.max(a.canvas.width, b.canvas.width);
        const h = Math.max(a.canvas.height, b.canvas.height);
        if (!blendScratch || blendScratch.width !== w || blendScratch.height !== h) {
            blendScratch = document.createElement('canvas');
            blendScratch.width = w; blendScratch.height = h;
        }
        const c = blendScratch;
        const ctx = c.getContext('2d');
        ctx.imageSmoothingEnabled = false;
        ctx.globalAlpha = 1;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(a.canvas, 0, 0, w, h);
        ctx.globalAlpha = t;
        ctx.drawImage(b.canvas, 0, 0, w, h);
        ctx.globalAlpha = 1;
        return { canvas: c, kind: a.kind };
    }

    async function play(name) {
        const anim = state.library[name];
        if (!anim?.frames?.length) return { ok: false, error: 'facial "' + name + '" does not exist or has no frames' };
        stop(false);
        if (auto.on) autoStop(false);
        try { ensureSession(); } catch (e) { return { ok: false, error: e.message }; }
        state.playing = name;

        const frames = [];
        for (const f of anim.frames) {
            let fr = null;
            try { fr = await resolveFace(f.face); } catch {}
            if (!fr) fr = state.baseHead
                ? { canvas: cloneCanvas(state.baseHead), kind: 'head' }
                : { canvas: blankFace(), kind: 'face' };
            frames.push({ canvas: fr.canvas, kind: fr.kind, holdMs: +f.holdMs || 400, blendMs: Math.max(0, +f.blendMs || 0) });
        }

        const t0 = performance.now();
        const totalMs = frames.reduce((s, f) => s + f.holdMs + f.blendMs, 0) || 1;
        const tick = () => {
            if (!state.playing) return;
            const anim = state.library[state.playing];
            if (!anim) return stop(true);
            // duración invariante del loop: calculada una vez en play(), no a 60fps
            let t = (performance.now() - t0) % totalMs;
            let i = 0;
            // paseo acotado: un holdMs negativo (el input no valida nada) hace
            // que t crezca en vez de bajar y este while se convierte en un arete
            for (let n = 0; n < frames.length && t > frames[i].holdMs + frames[i].blendMs; n++) {
                t -= frames[i].holdMs + frames[i].blendMs;
                i = (i + 1) % frames.length;
            }
            const cur = frames[i];
            const nxt = frames[(i + 1) % frames.length];
            try {
                if (t > cur.holdMs && cur.blendMs > 0 && cur.kind === nxt.kind) {

                    const k = (t - cur.holdMs) / cur.blendMs;
                    paintFace(blendFrames(cur, nxt, k));
                } else {
                    paintFace(cur);
                }
            } catch (e) {

                state.playing = null;
                if (state.playTimer) { cancelAnimationFrame(state.playTimer); state.playTimer = null; }
                console.warn(TAG + ' loop detenido: ' + e.message);
                return;
            }
            state.playTimer = requestAnimationFrame(tick);
        };
        tick();
        void 0;
        return { ok: true, name };
    }

    function stop(restore = true) {
        if (state.playTimer) { cancelAnimationFrame(state.playTimer); state.playTimer = null; }
        state.playing = null;
        if (restore && state.baseHead && state.tex) {
            try { paintFace({ canvas: state.baseHead, kind: 'head' }); } catch {}
        }
        renderUI();
        return { ok: true };
    }

    const LS_AUTO = LS_KEY + '_auto';
    const auto = {
        on: false,
        yawThreshold: 10,

        pitchThreshold: 10,
        front: '',

        left: '',

        right: '',

        up: '',
        down: '',
        blink: true,

        blinkClosed: '',

        blinkMinMs: 2000, blinkMaxMs: 7000,
        brow: false,

        browFace: '',

        browMs: 1400,

        _browUntil: 0,

        _raf: null,

        _nextBlink: 0,

        _blinkUntil: 0,

        _blinkCache: null,

        _blinkCacheZone: null,

        _zone: 'front',

        _refYaw: null, _refPitch: null, _lastT: 0
    };

    function loadAuto() {
        try { Object.assign(auto, JSON.parse(localStorage.getItem(LS_AUTO) || '{}')); }
        catch {}

        if (auto.yawThreshold === 35) auto.yawThreshold = 10;
        if (auto.pitchThreshold === 30) auto.pitchThreshold = 10;

        auto._raf = null; auto._nextBlink = 0; auto._blinkUntil = 0;
        auto._blinkCache = null; auto._blinkCacheZone = null; auto._zone = 'front';
        auto._browUntil = 0; auto._browPainted = false;
        auto._refYaw = null; auto._refPitch = null; auto._lastT = 0;
    }
    function saveAuto() {
        try {
            localStorage.setItem(LS_AUTO, JSON.stringify({
                on: auto.on, yawThreshold: auto.yawThreshold, pitchThreshold: auto.pitchThreshold,
                front: auto.front, left: auto.left, right: auto.right, up: auto.up, down: auto.down,
                blink: auto.blink, blinkClosed: auto.blinkClosed,
                blinkMinMs: auto.blinkMinMs, blinkMaxMs: auto.blinkMaxMs,
                brow: auto.brow, browFace: auto.browFace, browMs: auto.browMs
            }));
        } catch {}
    }

    function cameraRig() {
        const g = getGame();
        const me = g?.player;
        try {
            const camera = me?.game?.gameScene?.camera || g?.gameScene?.camera;
            const pitchObj = camera?.parent, yawObj = camera?.parent?.parent;
            if (yawObj && typeof yawObj.rotation?.y === 'number' && typeof pitchObj?.rotation?.x === 'number') {
                return { yaw: yawObj.rotation.y, pitch: pitchObj.rotation.x };
            }
        } catch {}
        return null;
    }

    const wrapPi = (r) => { r = (r + Math.PI) % (Math.PI * 2); if (r < 0) r += Math.PI * 2; return r - Math.PI; };
    const D = 180 / Math.PI;

    function lookAngles() {
        const rig = cameraRig();
        if (!rig) return null;
        const now = performance.now();
        const dt = Math.min(0.1, (now - (auto._lastT || now)) / 1000);
        auto._lastT = now;
        if (auto._refYaw == null) { auto._refYaw = rig.yaw; auto._refPitch = rig.pitch; }
        const follow = Math.PI * dt;

        auto._refYaw += Math.max(-follow, Math.min(follow, wrapPi(rig.yaw - auto._refYaw)));
        const fP = follow * 0.7;
        auto._refPitch += Math.max(-fP, Math.min(fP, Math.max(-Math.PI / 2, Math.min(Math.PI / 2, rig.pitch - auto._refPitch))));
        return {
            yaw: wrapPi(rig.yaw - auto._refYaw) * D,

            pitch: wrapPi(rig.pitch - auto._refPitch) * D,
            absYaw: wrapPi(rig.yaw) * D,

            absPitch: rig.pitch * D
        };
    }

    const HYST = () => Math.min(8, Math.max(2, Math.floor(Math.min(auto.yawThreshold, auto.pitchThreshold) / 2)));
    function zoneOf(a) {
        const z = auto._zone || 'front';
        const thr = auto.yawThreshold, pthr = auto.pitchThreshold;
        const hY = Math.min(HYST(), thr / 2), hP = Math.min(HYST(), pthr / 2);

        const inUp = auto.up && a.pitch > pthr, outUp = a.pitch > pthr - hP;
        const inDown = auto.down && a.pitch < -pthr, outDown = a.pitch < -(pthr - hP);
        const inR = auto.right && a.yaw > thr, outR = a.yaw > thr - hY;
        const inL = auto.left && a.yaw < -thr, outL = a.yaw < -(thr - hY);

        switch (z) {
            case 'up': if (auto.up && outUp) return 'up'; break;
            case 'down': if (auto.down && outDown) return 'down'; break;
            case 'left': if (auto.left && outL) return 'left'; break;
            case 'right': if (auto.right && outR) return 'right'; break;
        }
        if (inUp) return 'up';
        if (inDown) return 'down';
        if (inR) return 'right';
        if (inL) return 'left';
        return 'front';
    }

    const resolveAutoName = (n) => (typeof n === 'string' && n.startsWith('fs:')) ? n : 'p:' + n;

    async function paintZone(zone, force = false) {
        if (!force && auto._zone === zone) return;
        auto._zone = zone;
        const name = zone === 'front' ? (auto.front || null) : auto[zone] || null;
        try {
            let fr = null;
            if (name) fr = await resolveFace(resolveAutoName(name)).catch(() => null);
            if (!fr) fr = state.baseHead ? { canvas: state.baseHead, kind: 'head' } : { canvas: blankFace(), kind: 'face' };
            paintFace({ canvas: fr.canvas, kind: fr.kind });
        } catch {}
    }

    async function getBlinkCanvas() {
        const zone = auto._zone || 'front';
        if (auto._blinkCache && auto._blinkCacheZone === zone) return auto._blinkCache;

        const zoneFace = async () => {
            const name = zone === 'front' ? (auto.front || null) : auto[zone] || null;
            let fr = null;
            if (name) fr = await resolveFace(resolveAutoName(name)).catch(() => null);
            if (fr) {
                const k = fr.kind === 'head' ? Math.max(1, Math.round(fr.canvas.width / 64)) : 1;
                const c = document.createElement('canvas');
                c.width = 8; c.height = 8;
                const cx = c.getContext('2d', { willReadFrequently: true });
                cx.imageSmoothingEnabled = false;
                if (fr.kind === 'head') cx.drawImage(fr.canvas, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k, 0, 0, 8, 8);
                else cx.drawImage(fr.canvas, 0, 0, 8, 8, 0, 0, 8, 8);
                return c;
            }
            if (state.baseHead) {
                const bk = state.baseHeadK || 1;
                const c = document.createElement('canvas');
                c.width = 8; c.height = 8;
                const cx = c.getContext('2d', { willReadFrequently: true });
                cx.imageSmoothingEnabled = false;
                cx.drawImage(state.baseHead, FACE.x * bk, FACE.y * bk, FACE.w * bk, FACE.h * bk, 0, 0, 8, 8);
                return c;
            }
            return null;
        };

        try {

            if (auto.blinkClosed) {
                const fr = await resolveFace(resolveAutoName(auto.blinkClosed)).catch(() => null);
                if (fr) {

                    if (fr.kind === 'head') {
                        auto._blinkCache = fr.canvas; auto._blinkCacheZone = zone;
                        auto._blinkCacheKind = 'head';
                        return fr.canvas;
                    }
                    const c = document.createElement('canvas');
                    c.width = 8; c.height = 8;
                    const cx = c.getContext('2d');
                    cx.imageSmoothingEnabled = false;
                    cx.drawImage(fr.canvas, 0, 0, 8, 8, 0, 0, 8, 8);
                    auto._blinkCache = c; auto._blinkCacheZone = zone;
                    auto._blinkCacheKind = 'face';
                    return c;
                }
            }

            const face = await zoneFace();
            if (face) {
                const cx = face.getContext('2d', { willReadFrequently: true });

                const cheek = cx.getImageData(1, 6, 1, 1).data;
                cx.fillStyle = `rgb(${cheek[0]},${cheek[1]},${cheek[2]})`;
                cx.fillRect(1, 4, 2, 2);
                cx.fillRect(5, 4, 2, 2);
                auto._blinkCache = face; auto._blinkCacheZone = zone;
                auto._blinkCacheKind = 'face';
                return face;
            }
        } catch {}
        return null;
    }

    function scheduleBlink(now) {
        auto._nextBlink = now + auto.blinkMinMs + Math.random() * Math.max(0, auto.blinkMaxMs - auto.blinkMinMs);
    }

    function broadcastFacial(a) {
        try { window.MF_Peer?.sendStudio?.({ t: 'facial', a }); } catch {}
    }

    const chatSeen = new WeakSet();
    const DEBUG_BROW = localStorage.getItem('mff:debug-brow') === '1';
    function debugBrow(...a) { if (DEBUG_BROW) void 0; }
    function chatQuestionWatch() {
        if (!auto.brow || !auto.on) { debugBrow('watch off (brow=' + auto.brow + ' on=' + auto.on + ')'); return; }
        const g = getGame() || globalThis.__MINIBLOX_GAME__ || null;
        const log = g?.chat?.log;
        if (!Array.isArray(log)) { debugBrow('sin chat: game=' + !!g + ' log=' + (log === undefined ? 'undefined' : typeof log)); return; }

        for (let i = Math.max(0, log.length - 12); i < log.length; i++) {
            const entry = log[i];
            if (!entry || typeof entry !== 'object' || chatSeen.has(entry)) continue;
            chatSeen.add(entry);
            const text = String(entry.text ?? entry.message ?? entry.content ?? '');
            const hasQ = text.includes('?');
            debugBrow('chat[' + i + ']' + (hasQ ? ' [?]' : '') + ': ' + JSON.stringify(text.slice(0, 60)));

            if (hasQ) {
                auto._browUntil = performance.now() + (auto.browMs || 1400);
                debugBrow('→ ceja hasta +' + (auto.browMs || 1400) + 'ms');
                return;
            }
        }
    }

    async function getBrowCanvas() {

        if (auto.browFace) {
            const fr = await resolveFace(resolveAutoName(auto.browFace)).catch(e => { debugBrow('preset browFace falló:', e?.message || e); return null; });
            if (fr) {
                debugBrow('brow por preset: ' + auto.browFace + ' (kind=' + fr.kind + ')');
                if (fr.kind === 'head') return { canvas: fr.canvas, kind: 'head' };
                const c = document.createElement('canvas');
                c.width = 8; c.height = 8;
                const cx = c.getContext('2d');
                cx.imageSmoothingEnabled = false;
                cx.drawImage(fr.canvas, 0, 0, 8, 8, 0, 0, 8, 8);
                return { canvas: c, kind: 'face' };
            }
            debugBrow('preset browFace "' + auto.browFace + '" NO resolvió → siguiente fuente');
        }

        const zone = auto._zone || 'front';
        const name = zone === 'front' ? (auto.front || null) : auto[zone] || null;
        if (typeof name === 'string' && name.startsWith('fs:')) {
            const m = name.match(/^fs:([^/]+)\/(.+)$/);
            const pack = m ? packIndex.find(p => p.id === m[1]) : null;
            if (pack?.brow) {
                const fr = await resolveFace('fs:' + pack.id + '/' + pack.brow).catch(() => null);
                if (fr) { debugBrow('brow por pack: ' + pack.id + '/' + pack.brow + ' (kind=' + fr.kind + ')'); return { canvas: fr.canvas, kind: fr.kind }; }
                debugBrow('pack brow "' + pack.brow + '" NO cargó');
            } else {
                debugBrow('pack ' + (pack ? pack.id : m?.[1]) + ' sin sprite brow');
            }
        }

        debugBrow('brow SINTETIZADA sobre zona "' + zone + '"');
        const face = await zoneFace();
        if (!face) return null;
        const c = document.createElement('canvas');
        c.width = 8; c.height = 8;
        const cx = c.getContext('2d', { willReadFrequently: true });
        cx.imageSmoothingEnabled = false;
        cx.drawImage(face, 0, 0);
        try {
            const hair = cx.getImageData(4, 0, 1, 1).data;
            const row3 = cx.getImageData(0, 3, 8, 1);
            cx.putImageData(row3, 0, 2);

            const cheek = cx.getImageData(1, 6, 1, 1).data;
            cx.fillStyle = `rgb(${Math.round((cheek[0] + hair[0]) / 2)},${Math.round((cheek[1] + hair[1]) / 2)},${Math.round((cheek[2] + hair[2]) / 2)})`;
            cx.fillRect(0, 3, 8, 1);
        } catch {}
        return { canvas: c, kind: 'face' };
    }

    function autoTick() {
        if (!auto.on) { auto._raf = null; return; }
        const now = performance.now();

        chatQuestionWatch();
        if (auto._browUntil) {
            if (now >= auto._browUntil) {
                debugBrow('fin de la ceja → restaurar zona "' + (auto._zone || 'front') + '"');
                auto._browUntil = 0;
                broadcastFacial('open');
                paintZone(auto._zone || 'front', true);
            } else {

                if (!auto._browPainted) {
                    auto._browPainted = true;
                    broadcastFacial('brow');
                    debugBrow('pintando ceja (quedan ' + Math.round(auto._browUntil - now) + 'ms)');
                    getBrowCanvas().then(fr => {
                        if (fr && auto.on && auto._browUntil) {
                            try { paintFace({ canvas: fr.canvas, kind: fr.kind }); }
                            catch (e) {

                                state.tex = null; state.baseHead = null;
                                debugBrow('brow: sesión inválida (' + e.message + ') → recapturar');
                            }
                        } else if (fr) {
                            debugBrow('canvas listo pero ventana cerrada (on=' + auto.on + ') — no se pinta');
                        }
                    });
                }
            }
        } else if (auto._browPainted) {
            auto._browPainted = false;
        }

        if (auto.blink && !auto._browUntil) {
            if (auto._blinkUntil && now >= auto._blinkUntil) {
                auto._blinkUntil = 0;
                scheduleBlink(now);
                broadcastFacial('open');
                paintZone(auto._zone || 'front', true);
            } else if (!auto._blinkUntil && now >= auto._nextBlink) {
                auto._blinkUntil = now + 45 + Math.random() * 45;
                broadcastFacial('blink');
                getBlinkCanvas().then(cv => {

                    if (cv && auto.on && auto._blinkUntil && performance.now() < auto._blinkUntil) {

                        try { paintFace({ canvas: cv, kind: auto._blinkCacheKind || 'face' }); }
                        catch (e) {

                            auto._blinkUntil = 0; scheduleBlink(performance.now());
                            state.tex = null; state.baseHead = null;
                            debugBrow('blink: sesión inválida (' + e.message + ') → recapturar');
                        }
                    }
                }).catch(e => {
                    auto._blinkUntil = 0; scheduleBlink(performance.now());
                    debugBrow('blink falló: ' + (e?.message || e));
                });
            }
        }

        if (!auto._browUntil) {
            const angles = lookAngles();
            if (angles) {
                const z = zoneOf(angles);
                if (z !== auto._zone && !auto._blinkUntil) {
                    broadcastFacial(z);
                    paintZone(z);
                }
            }
        }
        auto._raf = requestAnimationFrame(autoTick);
    }

    async function autoStart() {
        try { ensureSession(); } catch (e) { return { ok: false, error: e.message }; }
        stop(false);
        auto.on = true;
        try { localStorage.removeItem(LS_KEY + '_autoUserOff'); } catch {}
        skinWatch.userOff = false;
        auto._zone = null;
        auto._refYaw = null; auto._refPitch = null; auto._lastT = 0;
        scheduleBlink(performance.now());
        if (!auto._raf) auto._raf = requestAnimationFrame(autoTick);
        renderUI();
        void 0;
        return { ok: true };
    }

    function autoStop(restore = true) {
        auto.on = false;
        if (auto._raf) { cancelAnimationFrame(auto._raf); auto._raf = null; }
        broadcastFacial('off');
        if (restore && state.baseHead && state.tex) {
            try { paintFace({ canvas: state.baseHead, kind: 'head' }); } catch {}
        }
        renderUI();
        return { ok: true };
    }

    const LS_OTHERS = LS_KEY + '_others';
    const others = {
        on: false,
        intervalMinMs: 2500,
        intervalMaxMs: 6500,
        _raf: null,

        _sessions: new Map()
    };
    function loadOthers() {
        try { Object.assign(others, JSON.parse(localStorage.getItem(LS_OTHERS) || '{}')); } catch {}
        others._raf = null; others._sessions = new Map();
    }
    function saveOthers() {
        try {
            localStorage.setItem(LS_OTHERS, JSON.stringify({
                on: others.on, intervalMinMs: others.intervalMinMs, intervalMaxMs: others.intervalMaxMs
            }));
        } catch {}
    }
    loadOthers();

    function otherPlayers() {
        const g = getGame() || globalThis.__MINIBLOX_GAME__ || null;
        const me = g?.player;
        if (!g || !me) return [];
        const out = [];
        const seen = new Set();
        const meId = String(me.id ?? '');
        const meUuid = me.uuid != null ? String(me.uuid) : null;
        const isMe = (key, uuid) =>
            (meId && String(key) === meId) || (meUuid != null && uuid != null && String(uuid) === meUuid);
        const add = (key, e, name) => {
            if (!key || seen.has(key) || isMe(key, null)) return;
            const mesh = e?.mesh;
            if (!mesh) return;

            const uuid = typeof e?.uuid === 'string' ? e.uuid.toLowerCase() : null;
            const uname = String(e?.username || e?.profile?.username || name || '').toLowerCase() || null;
            let skin = '';
            const sc = e?.profile?.cosmetics?.skin || e?.profile?.skin || e?.mesh?.model?.skin;
            if (typeof sc === 'string' && sc) skin = normSkinId(sc);
            if (!skin || !packIndex.some(p => p.id === skin)) {
                const dbSkin = skinForIdentity(uuid, uname);
                if (dbSkin && packIndex.some(p => p.id === dbSkin)) skin = dbSkin;
            }
            if (uuid && !skin) {
                const byUuid = packIndex.find(p => p.uuid === uuid);
                if (byUuid) skin = byUuid.id;
            }
            seen.add(key); out.push({ key: String(key), mesh, name: String(name || key).slice(0, 16), skin, uuid });
        };
        try {
            if (g.world?.players instanceof Map) {
                for (const [id, e] of g.world.players) {
                    if (isMe(id, e?.uuid)) continue;
                    add(e?.uuid || id, e, e?.username || e?.profile?.username || e?.name);
                }
            }
        } catch {}
        try {
            const pl = g.playerList;
            const entries = pl?.entries ? [...pl.entries()] : Object.entries(pl || {});
            for (const [k, v] of entries) {
                if (!v || typeof v !== 'object') continue;
                if (isMe(k, v.uuid)) continue;
                try { const e = g.world?.getPlayerById?.(k) || g.world?.players?.get?.(k); if (e) add(v.uuid || k, e, v.username || v.name); } catch {}
            }
        } catch {}
        return out;
    }

    function packForOther(skinId) {
        if (!skinId) return null;
        for (const p of packIndex) if (p.id === skinId) return p;
        return null;
    }

    function skinForIdentity(uuid, username) {
        const db = window.__MF_CustomSkins_DB__ || null;
        let v = '';
        if (db) {
            if (uuid && db.byUuid && db.byUuid[uuid]) v = db.byUuid[uuid];
            if (!v && username && db.byName) {
                const u = String(username);
                if (db.byName[u]) v = db.byName[u];
                else {

                    const k = u.toLowerCase().replace(/[\s_-]+/g, '');
                    for (const n in db.byName) {
                        if (String(n).toLowerCase().replace(/[\s_-]+/g, '') === k) { v = db.byName[n]; break; }
                    }
                }
            }
        }
        return v ? normSkinId(v) : '';
    }

    function preloadOtherPack(s, pack) {
        if (!s || !pack || s.pack?._id === pack.id) return;
        const entry = { _id: pack.id, img: { front: null, left: null, right: null, up: null, down: null, blink: null } };
        s.pack = entry;
        for (const which of ['front', 'left', 'right', 'up', 'down', 'blink']) {
            const file = pack[which];
            if (!file) continue;
            packImg(pack.id, file)
                .then(img => { if (img && s.pack === entry) { entry.img[which] = img; s.zoneDirty = true; } })
                .catch(() => {});
        }
    }

    function paintOtherStrip(s, img) {
        try {
            const k = s.k || 1, cx = s.canvas.getContext('2d');
            cx.imageSmoothingEnabled = false;
            if (s.baseHead) {
                cx.drawImage(s.baseHead, 0, 0, s.baseHead.width, s.baseHead.height, 0, 0, 64 * k, 16 * k);
            } else {
                cx.clearRect(0, 0, 32 * k, 16 * k);
            }
            cx.drawImage(img, 0, 0, img.width, img.height, 0, 0, 32 * k, 16 * k);
            s.tex.needsUpdate = true;
        } catch {}
    }

    function otherSession(p) {
        let s = others._sessions.get(p.key);
        const mats = findSkinMaterials(p.mesh);
        if (!mats.length) return null;

        let src = null;
        const srcMats = [];
        for (const m of mats) {
            const t = m.map;
            if (!t?.image) continue;
            if (t.image instanceof HTMLCanvasElement) {
                if (t.__mfLocalCanvas || t.__mfPeerCanvas) continue;
                if (t.__mfOtherKey && t.__mfOtherKey !== p.key) continue;
            }
            srcMats.push(m);
            if (!src) src = t;
        }
        const srcIsOurs = !!(src && src.image instanceof HTMLCanvasElement && src.__mfOtherKey === p.key);
        const now = performance.now();

        if (srcIsOurs && s?.tex) {
            const auth = s.authTex;
            if (auth?.image instanceof HTMLCanvasElement && now - (s.lastMirror || 0) > 400) {
                s.lastMirror = now;
                try {
                    const cx = s.canvas.getContext('2d');
                    cx.imageSmoothingEnabled = false;
                    cx.drawImage(auth.image, 0, 0);
                    if (!s.blinkUntil) s.zoneDirty = true;
                } catch {}
            }
            return s;
        }
        if (!src) return null;
        if (!s) {
            s = { tex: null, canvas: null, baseHead: null, k: 1, nextBlink: 0, blinkUntil: 0, name: p.name, srcId: null, lastMirror: 0, authTex: null };
            others._sessions.set(p.key, s);
        }

        const srcId = String(src.uuid ?? '') + ':' + src.image.width + 'x' + src.image.height;
        const changed = s.srcId !== srcId;

        const needsMount = srcMats.some(m => m.map !== s.tex);
        if (changed || !s.tex || needsMount) {
            s.lastMirror = now;
            s.authTex = srcIsOurs ? null : src;

            if (changed || !s.baseHead) {
                try {
                    const k = Math.max(1, Math.round(src.image.width / 64));
                    const c = document.createElement('canvas');
                    c.width = 64 * k; c.height = 16 * k;
                    c.getContext('2d').drawImage(src.image, 0, 0, 64 * k, 16 * k, 0, 0, 64 * k, 16 * k);
                    s.baseHead = c; s.k = k;
                } catch { return null; }
            }

            if (!s.tex || s.canvas.width !== src.image.width || s.canvas.height !== src.image.height) {
                const c = document.createElement('canvas');
                c.width = src.image.width; c.height = src.image.height;
                let nt = null;
                try { nt = new src.constructor(c); } catch {}
                if (!nt) { others._sessions.delete(p.key); return null; }
                nt.__mfOtherKey = p.key;
                try {
                    nt.magFilter = src.magFilter; nt.minFilter = src.minFilter;
                    if (src.colorSpace !== undefined && 'colorSpace' in nt) nt.colorSpace = src.colorSpace;
                    nt.flipY = src.flipY; nt.wrapS = src.wrapS; nt.wrapT = src.wrapT;
                } catch {}
                if (s.tex && s.tex !== src && s.tex.__mfOtherKey) {
                    try { s.tex.dispose(); } catch {}
                }
                s.tex = nt; s.canvas = c;
            }

            try {
                const cx = s.canvas.getContext('2d');
                cx.imageSmoothingEnabled = false;
                cx.clearRect(0, 0, s.canvas.width, s.canvas.height);
                cx.drawImage(src.image, 0, 0);
            } catch {}

            for (const m of srcMats) {
                if (m.map === s.tex) continue;
                m.map = s.tex; m.needsUpdate = true;
            }
            if (!s.blinkUntil) s.zoneDirty = true;
        }
        s.srcId = srcId;
        return s;
    }

    function otherBlinkCanvas(s) {
        if (!s?.baseHead) return null;
        const k = s.k || 1;
        const c = document.createElement('canvas');
        c.width = 8; c.height = 8;
        const cx = c.getContext('2d', { willReadFrequently: true });
        cx.imageSmoothingEnabled = false;
        cx.drawImage(s.baseHead, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k, 0, 0, 8, 8);
        try {
            const cheek = cx.getImageData(1, 6, 1, 1).data;
            cx.fillStyle = `rgb(${cheek[0]},${cheek[1]},${cheek[2]})`;
            cx.fillRect(1, 4, 2, 2);
            cx.fillRect(5, 4, 2, 2);
        } catch {}
        return c;
    }

    function otherEyeColors(s) {
        if (s._eye && s._eyeFor === s.baseHead) return s._eye;
        const k = s.k || 1;
        const c = document.createElement('canvas');
        c.width = 8; c.height = 8;
        const cx = c.getContext('2d', { willReadFrequently: true });
        cx.imageSmoothingEnabled = false;
        cx.drawImage(s.baseHead, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k, 0, 0, 8, 8);
        const eye = { iris: null, white: [219, 219, 219], skin: [230, 180, 150] };
        try {
            const cheek = cx.getImageData(1, 6, 1, 1).data;
            eye.skin = [cheek[0], cheek[1], cheek[2]];
            const region = cx.getImageData(1, 4, 6, 2).data;
            const px = (x, y) => { const o = ((y - 4) * 6 + (x - 1)) * 4; return [region[o], region[o + 1], region[o + 2], region[o + 3]]; };
            for (let x = 1; x <= 6; x++) {
                for (let y = 4; y <= 5; y++) {
                    const d = px(x, y);
                    if (!d || d[3] === 0) continue;
                    const sum = d[0] + d[1] + d[2];
                    if (!eye.iris || sum < eye.iris[0] + eye.iris[1] + eye.iris[2]) {
                        if (sum < eye.skin[0] + eye.skin[1] + eye.skin[2] - 90) eye.iris = [d[0], d[1], d[2]];
                    }
                    if (sum > eye.white[0] + eye.white[1] + eye.white[2]) eye.white = [d[0], d[1], d[2]];
                }
            }
        } catch {}
        s._eye = eye; s._eyeFor = s.baseHead;
        return eye;
    }

    const GAZE_RANGE = 30 * Math.PI / 180;
    const GAZE_PREDICT_S = 0.12;
    const GAZE_VMAX = 6;

    function otherGaze(p, s) {
        try {
            const m = p.mesh;
            if (!m) return null;
            let head = s?._head || null, body = s?._body || null;
            const attached = ref => { for (let o = ref; o; o = o.parent) if (o === m) return true; return false; };
            if (head && !attached(head)) { head = null; if (s) s._head = null; }
            if (body && !attached(body)) { body = null; if (s) s._body = null; }

            if (!head || !body) {
                const queue = [m];
                const seen = new WeakSet();
                let visited = 0;
                while (queue.length && visited < 500 && !(head && body)) {
                    const obj = queue.shift();
                    if (!obj || typeof obj !== 'object' || seen.has(obj)) continue;
                    seen.add(obj); visited++;
                    if (!head && obj.headPivot?.rotation) head = obj.headPivot;
                    if (!body && obj.body?.rotation) body = obj.body;
                    if (Array.isArray(obj.children)) for (const c of obj.children) queue.push(c);
                }
                if (s) { s._head = head || null; s._body = body || null; }
            }
            if (!head) return null;
            const yaw = wrapPi((Number(head.rotation.y) || 0) - (Number(body?.rotation.y) || 0));
            const pitch = Number(head.rotation.x) || 0;

            const now = performance.now();
            if (s && s._gYaw != null) {
                const dt = (now - s._gT) / 1000;
                if (dt > 0.001 && dt < 0.5) {
                    const vy = Math.max(-GAZE_VMAX, Math.min(GAZE_VMAX, wrapPi(yaw - s._gYaw) / dt));
                    const vp = Math.max(-GAZE_VMAX, Math.min(GAZE_VMAX, (pitch - (s._gPitch ?? pitch)) / dt));
                    s._gvYaw = (s._gvYaw ?? 0) * 0.7 + vy * 0.3;
                    s._gvPitch = (s._gvPitch ?? 0) * 0.7 + vp * 0.3;
                }
            }
            if (s) { s._gYaw = yaw; s._gPitch = pitch; s._gT = now; }

            const pyaw = wrapPi(yaw + (s?._gvYaw ?? 0) * GAZE_PREDICT_S);
            const ppitch = Math.max(-1.4, Math.min(1.4, pitch + (s?._gvPitch ?? 0) * GAZE_PREDICT_S));

            const gx = Math.max(-1, Math.min(1, pyaw / GAZE_RANGE));
            const gy = Math.max(-1, Math.min(1, ppitch / GAZE_RANGE));

            const thr = 22 * Math.PI / 180;
            let zone = 'front';
            if (ppitch > thr) zone = 'up';
            else if (ppitch < -thr) zone = 'down';
            else if (pyaw > thr) zone = 'right';
            else if (pyaw < -thr) zone = 'left';

            return { gx, gy, zone };
        } catch { return null; }
    }

    function paintOtherGaze(s, gx, gy, base) {
        if (!s?.baseHead || !s.canvas) return false;
        const k = s.k || 1;
        const cx = s.canvas.getContext('2d');
        cx.imageSmoothingEnabled = false;
        cx.drawImage(s.baseHead, 0, 0, s.baseHead.width, s.baseHead.height, 0, 0, 64 * k, 16 * k);
        if (base) cx.drawImage(base, 0, 0, base.width, base.height, 0, 0, 32 * k, 16 * k);
        const eye = otherEyeColors(s);
        if (eye.iris) {
            const rgb = a => `rgb(${a[0]},${a[1]},${a[2]})`;
            const ix = Math.round((gx * 0.5 + 0.5) * k);
            const iy = Math.round((0.5 - gy * 0.5) * k);
            for (const ex of [1, 5]) {
                const bx = (FACE.x + ex) * k, by = (FACE.y + 4) * k;
                cx.fillStyle = rgb(eye.white);
                cx.fillRect(bx, by, 2 * k, 2 * k);
                cx.fillStyle = rgb(eye.iris);
                cx.fillRect(bx + ix, by + iy, k, k);
            }
        }
        s.tex.needsUpdate = true;
        return true;
    }

    let _lastOtherTick = 0;
    function otherTick() {
        if (!others.on) { others._raf = null; return; }
        const now = performance.now();
        if (now - _lastOtherTick < 48) { others._raf = requestAnimationFrame(otherTick); return; }
        _lastOtherTick = now;
        const live = new Set();
        for (const p of otherPlayers()) {
            live.add(p.key);

            const pack = packForOther(p.skin);
            if (!pack) {

                const s = others._sessions.get(p.key);
                if (s) restoreOther(p.key);
                continue;
            }
            const s = otherSession(p);
            if (!s) continue;

            preloadOtherPack(s, pack);

            const gaze = otherGaze(p, s) || { gx: 0, gy: 0, zone: 'front' };
            const z = gaze.zone;
            if (s.zone !== z) { s.zone = z; s.zoneDirty = true; }
            const gxMove = Math.abs(gaze.gx - (s._gpx ?? 0)) > 0.02 || Math.abs(gaze.gy - (s._gpy ?? 0)) > 0.02;
            s._gpx = gaze.gx; s._gpy = gaze.gy;
            if (!s.nextBlink) s.nextBlink = now + 800 + Math.random() * others.intervalMinMs;
            if (s.blinkUntil && now >= s.blinkUntil) {
                s.blinkUntil = 0;
                s.nextBlink = now + others.intervalMinMs + Math.random() * Math.max(0, others.intervalMaxMs - others.intervalMinMs);
                s.zoneDirty = true;
            } else if (!s.blinkUntil && now >= s.nextBlink && s.zone === 'front') {
                s.blinkUntil = now + 45 + Math.random() * 45;
                if (s.pack?.img?.blink) {

                    paintOtherStrip(s, s.pack.img.blink);
                } else {
                    const cv = otherBlinkCanvas(s);
                    if (cv) {
                        try {
                            const k = s.k || 1, cx = s.canvas.getContext('2d');
                            cx.imageSmoothingEnabled = false;
                            cx.drawImage(cv, 0, 0, 8, 8, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k);
                            s.tex.needsUpdate = true;
                        } catch {}
                    }
                }
            } else if (!s.blinkUntil && (s.zoneDirty || gxMove)) {
                s.zoneDirty = false;
                const strip = s.pack?.img ? (s.zone === 'front' ? s.pack.img.front : s.pack.img[s.zone]) : null;
                if (s.zone === 'front') {
                    paintOtherGaze(s, gaze.gx, gaze.gy, strip || null);
                } else if (strip) {
                    paintOtherStrip(s, strip);
                } else {
                    paintOtherGaze(s, gaze.gx, gaze.gy, null);
                }
            }
        }

        for (const key of others._sessions.keys()) if (!live.has(key)) others._sessions.delete(key);
        others._raf = requestAnimationFrame(otherTick);
    }

    function restoreOther(key) {
        const s = others._sessions.get(key);
        if (!s) return;
        try {
            const k = s.k || 1, cx = s.canvas.getContext('2d');
            cx.imageSmoothingEnabled = false;
            cx.clearRect(0, 0, 64 * k, 16 * k);
            cx.drawImage(s.baseHead, 0, 0, 64 * k, 16 * k, 0, 0, 64 * k, 16 * k);
            s.tex.needsUpdate = true;
        } catch {}
        others._sessions.delete(key);
    }

    function othersStart() {
        others.on = true;
        saveOthers();
        if (!others._raf) others._raf = requestAnimationFrame(otherTick);
        renderUI();
        const n = otherPlayers().length;
        void 0;
        return { ok: true, count: n };
    }
    function othersStop() {
        others.on = false;
        if (others._raf) { cancelAnimationFrame(others._raf); others._raf = null; }

        for (const key of [...others._sessions.keys()]) restoreOther(key);
        others._sessions.clear();
        saveOthers();
        renderUI();
        void 0;
        return { ok: true };
    }

    function loadLibrary() {
        let lib = {};
        try { lib = JSON.parse(localStorage.getItem(LS_KEY) || '{}'); } catch {}
        const out = {};
        for (const [k, v] of Object.entries(lib)) {
            if (Array.isArray(v)) out[k] = { frames: v };

            else if (v && Array.isArray(v.frames)) out[k] = v;

        }
        state.library = out;
    }
    function saveLibrary() {
        try { localStorage.setItem(LS_KEY, JSON.stringify(state.library)); } catch {}
    }

    function buildTemplates() {
        const presets = (window.MF_SkinEditor?.presets?.() || []).map(p => 'p:' + p.name);
        const T = {};
        if (presets.length >= 2) {
            T['alternate presets'] = { frames: [
                { face: presets[0], holdMs: 1200, blendMs: 250 },
                { face: presets[1], holdMs: 1200, blendMs: 250 }
            ] };
            T['preset cycle'] = { frames: presets.slice(0, 4).map(p => ({ face: p, holdMs: 900, blendMs: 150 })) };
        }
        T['blink'] = { frames: [
            { face: 'base', holdMs: 2600, blendMs: 80 },
            { face: 'noface', holdMs: 90, blendMs: 80 },
            { face: 'base', holdMs: 60, blendMs: 80 },
            { face: 'noface', holdMs: 90, blendMs: 80 }
        ] };
        T['serious ↔ serious_1'] = { frames: [
            { face: 'base', holdMs: 1400, blendMs: 300 },
            { face: 'serious_1', holdMs: 1400, blendMs: 300 }
        ] };
        return T;
    }

    function buildUI() {
        if (document.getElementById(ID)) { renderUI(); return; }
        const style = document.createElement('style');
        style.id = ID + '-style';
        style.textContent = `
            #${ID} * { box-sizing:border-box; margin:0; padding:0; }
            #${ID} { position:fixed; top:60px; left:50%; transform:translateX(-50%);
  z-index:2147483000; width:720px; max-width:95vw; max-height:88vh;
  display:flex; flex-direction:column;
  background:rgba(27,27,31,.95); border:1px solid #32323a; border-radius:8px;
  backdrop-filter:blur(6px); box-shadow:0 12px 48px rgba(0,0,0,.65);
  color:#e8e8ee; font:12px/1.4 'Segoe UI',system-ui,sans-serif; user-select:none; }
  #${ID} .mff-head { display:flex; align-items:center; gap:8px; padding:9px 12px;
  border-bottom:1px solid #32323a; font-weight:700; letter-spacing:.5px;
  cursor:move; background:rgba(20,20,24,.95); border-radius:8px 8px 0 0; }
  #${ID} .mff-head .dot { width:8px; height:8px; border-radius:50%;
  background:#ffb84d; animation:mff-pulse 1.5s infinite; flex-shrink:0; }
  @keyframes mff-pulse { 50% { opacity:.35; } }
  #${ID} .mff-body { display:flex; min-height:0; flex:1; }
  #${ID} .mff-left { width:230px; flex-shrink:0; display:flex; flex-direction:column;
  border-right:1px solid #26262e; min-height:0; }
  #${ID} .mff-right { flex:1; display:flex; flex-direction:column; min-width:0; min-height:0; }
  #${ID} .mff-sec { font-size:10px; text-transform:uppercase; letter-spacing:1.5px;
  color:#6e6e7a; padding:8px 12px 4px; font-weight:600; }
  #${ID} .mff-list { flex:1; overflow-y:auto; padding:4px 8px; min-height:120px; max-height:46vh; }
  #${ID} .mff-item { display:flex; align-items:center; gap:6px; padding:6px 8px;
  border-radius:4px; cursor:pointer; border:1px solid transparent; }
  #${ID} .mff-item:hover { background:#26262e; }
  #${ID} .mff-item.on { background:#241d16; outline:1px solid #ff6b2b; }
  #${ID} .mff-item.editing { border-color:#4fc3f7; }
  #${ID} .mff-item .nm { flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  #${ID} .mff-item .meta { font-size:10px; color:#8a8a96; }
  #${ID} .mff-item button { background:none; border:none; cursor:pointer; font-size:11px; padding:1px 3px; color:#c8c8d2; }
  #${ID} .mff-item button:hover { color:#fff; }
  #${ID} .mff-pad { padding:8px 12px; }
  #${ID} select, #${ID} input { background:#191921; color:#e8e8ee;
  border:1px solid #32323a; border-radius:4px; padding:4px 6px; font:inherit; width:100%; }
  #${ID} .mff-frames { flex:1; overflow-y:auto; padding:6px 12px; min-height:100px; }
  #${ID} .mff-frame { display:grid; grid-template-columns:1fr 70px 70px 22px 24px; gap:4px;
  align-items:center; padding:4px 0; border-bottom:1px dashed #26262e; }
  #${ID} .mff-frame input { padding:3px 4px; font-size:11px; }
  #${ID} .mff-frame .thumb { width:22px; height:22px; image-rendering:pixelated;
  background:#0c0c10; border:1px solid #32323a; border-radius:3px;
  object-fit:contain; object-position:left; }
  #${ID} button { background:#23232c; color:#e8e8ee; border:1px solid #3a3a44;
  border-radius:4px; padding:4px 8px; cursor:pointer; font:inherit; }
  #${ID} button:hover { background:#2e2e3a; }
  #${ID} button.on { background:#ff6b2b; color:#14141a; border-color:#ff6b2b; font-weight:700; }
  #${ID} .mff-row { display:flex; gap:6px; align-items:center; }
  #${ID} .mff-hint { padding:0 12px 6px; font-size:10px; color:#8a8a96; }
  #${ID} .mff-foot { display:flex; gap:6px; padding:8px 12px;
  border-top:1px solid #26262e; background:rgba(20,20,24,.6); border-radius:0 0 8px 8px; }
  #${ID} .mff-tabs { display:flex; gap:2px; padding:6px 12px 0; }
  #${ID} .mff-tabs button { background:transparent; border:none; border-bottom:2px solid transparent;
  color:#9a9aa6; border-radius:4px 4px 0 0; padding:5px 14px; font-weight:600; }
  #${ID} .mff-tabs button:hover { color:#fff; background:transparent; }
  #${ID} .mff-tabs button.on { color:#ff6b2b; border-bottom-color:#ff6b2b; }
  #${ID} .mff-autoform { padding:6px 12px; }
  #${ID} .mff-field { display:grid; grid-template-columns:86px 1fr; gap:6px;
  align-items:center; padding:4px 0; }
  #${ID} .mff-field label { color:#9a9aa6; font-size:11px; }
  #${ID} .mff-check { display:flex; align-items:center; gap:8px; padding:5px 0; color:#c8c8d2; }
  #${ID} .mff-check input[type=checkbox] { width:auto; accent-color:#ff6b2b; }
  #${ID} ::-webkit-scrollbar { width:8px; height:8px; }
  #${ID} ::-webkit-scrollbar-thumb { background:#33333e; border-radius:4px; }
  #${ID} ::-webkit-scrollbar-track { background:transparent; }
        `;
        document.body.appendChild(style);
        const root = document.createElement('div');
        root.id = ID;
        root.innerHTML = `
            <div class="mff-head"><span class="dot"></span>👀 FACIALS — looping face animations
    <button data-act="close" style="margin-left:auto">✕</button></div>
        <div class="mff-tabs">
    <button data-tab="loop" class="on">Loops</button>
    <button data-tab="auto" title="The face reacts to where you look + random blinking">Auto</button>
    <button data-tab="packs" title="Skin packs with animated faces (builtin + ZIP)">Packs</button>
        </div>
            <div class="mff-body" data-page="loop">
  <div class="mff-left">
    <div class="mff-sec">Library</div>
    <div class="mff-list" id="mff-list"></div>
    <div class="mff-pad mff-row">
      <button id="mff-new" title="Create a new empty facial" style="flex:1">+ New</button>
      <button id="mff-seed" title="Regenerate templates with your current drawn presets">✨</button>
    </div>
  </div>
  <div class="mff-right">
    <div class="mff-sec">Keyframe editor</div>
    <div class="mff-hint">Each frame = a face + how long it holds + transition. Loops until you stop.</div>
    <div class="mff-pad mff-row" style="margin-bottom:4px">
      <select id="mff-face" title="Keyframe face"></select>
      <button id="mff-add" title="Add keyframe" style="white-space:nowrap">+ Frame</button>
    </div>
    <div class="mff-frames" id="mff-frames"></div>
  </div>
      </div>
          <div class="mff-body" data-page="auto" style="display:none">
  <div class="mff-left">
    <div class="mff-sec">Per-direction presets</div>
    <div class="mff-hint">Draw sprites in the skin editor, save them as presets and assign them here. Turn your head and the face changes on its own.</div>
    <div class="mff-autoform" id="mff-autoform"></div>
  </div>
  <div class="mff-right">
    <div class="mff-sec">Auto blinking</div>
    <div class="mff-autoform" id="mff-blinkform" style="padding:0 12px"></div>
    <div class="mff-sec">Live</div>
    <div class="mff-pad" id="mff-autolive" style="font:11px 'Consolas',monospace;color:#9a9aa6;line-height:1.8"></div>
  </div>
      </div>
          <div class="mff-body" data-page="packs" style="display:none">
  <div class="mff-left">
    <div class="mff-sec">Facial packs</div>
    <div class="mff-hint">Each pack = skin + sprites (front / left / right / blink). If you wear its skin, the face animates on its own.</div>
    <div class="mff-list" id="mff-packs"></div>
    <div class="mff-pad mff-row">
      <button id="mff-packimport" title="Import pack from a ZIP (pack.json + PNGs)" style="flex:1">📥 Import ZIP</button>
      <input type="file" id="mff-packfile" accept=".zip" style="display:none">
    </div>
  </div>
  <div class="mff-right">
    <div class="mff-sec">Selected pack</div>
    <div class="mff-pad" id="mff-packdetail" style="font-size:11px;color:#c8c8d2"></div>
  </div>
      </div>
          <div class="mff-foot">
  <button id="mff-autotoggle" title="Auto: the face reacts to head rotation and blinks on its own">⚡ Auto</button>
  <button id="mff-save" title="Save to library">💾 Save</button>
  <button id="mff-play" title="Play on loop">▶ Loop</button>
  <button id="mff-stop" title="Stop and restore">⏹ Stop</button>
  <span id="mff-status" style="font-size:10px;color:#8a8a96;margin-left:auto;align-self:center"></span>
  <button id="mff-del" title="Delete the facial being edited">🗑</button>
      </div>
        `;
        document.body.appendChild(root);
        bindUI(root);
        makeDraggable(root);
    }

    function makeDraggable(root) {
        const head = root.querySelector('.mff-head');
        let sx = 0, sy = 0, ox = 0, oy = 0, drag = false;
        head.addEventListener('pointerdown', (e) => {
            if (e.target.tagName === 'BUTTON') return;
            drag = true;
            const r = root.getBoundingClientRect();
            root.style.left = r.left + 'px'; root.style.top = r.top + 'px';
            root.style.right = 'auto'; root.style.transform = 'none';
            sx = e.clientX; sy = e.clientY; ox = r.left; oy = r.top;
            head.setPointerCapture(e.pointerId);
        });
        head.addEventListener('pointermove', (e) => {
            if (!drag) return;
            root.style.left = Math.max(0, ox + e.clientX - sx) + 'px';
            root.style.top = Math.max(0, oy + e.clientY - sy) + 'px';
        });
        const up = () => { drag = false; };
        head.addEventListener('pointerup', up);
        head.addEventListener('pointercancel', up);
    }

    function faceOptions() {
        const opts = [{ v: 'base', t: 'base (your current head)' }];

        for (const pr of (window.MF_SkinEditor?.presets?.() || [])) {
            opts.push({ v: 'p:' + pr.name, t: '✏️ ' + pr.name });
        }

        for (const it of (window.MF_SkinChanger?.items || [])) {
            opts.push({ v: 'skin_' + it.name, t: '👕 ' + it.name });
        }

        for (const p of packIndex) {
            const nm = (p.name || p.id) + (p.custom ? ' (zip)' : '');
            opts.push({ v: 'fs:' + p.id + '/' + p.front, t: '📦 ' + nm + ' front' });
            opts.push({ v: 'fs:' + p.id + '/' + p.left, t: '📦 ' + nm + ' left' });
            opts.push({ v: 'fs:' + p.id + '/' + p.right, t: '📦 ' + nm + ' right' });
            opts.push({ v: 'fs:' + p.id + '/' + p.blink, t: '📦 ' + nm + ' blink' });
        }

        for (const n of (window.MF_FaceSwap?.list?.() || [])) {
            opts.push({ v: n, t: n });
        }
        return opts;
    }

    let editing = null;

    function renderUI() {
        const root = document.getElementById(ID);
        if (!root) return;

        const list = root.querySelector('#mff-list');
        list.innerHTML = '';
        const names = Object.keys(state.library);
        if (!names.length) {
            list.innerHTML = '<div style="color:#8a8a96;font-size:11px;padding:4px 2px">No saved facials — use a template or create one</div>';
        }
        for (const n of names) {
            const nf = state.library[n]?.frames?.length ?? 0;
            const it = el('div', 'mff-item' + (state.playing === n ? ' on' : '') + (editing === n ? ' editing' : ''));
            it.innerHTML = `<span class="nm">${n}</span><span class="meta">${nf}f</span>
                <button data-x="edit" title="Edit">✎</button>
                <button data-x="play" title="Play on loop">▶</button>
                <button data-x="del" title="Delete">✕</button>`;
            it.querySelector('[data-x="edit"]').onclick = (e) => { e.stopPropagation(); loadEditor(n); };
            it.querySelector('[data-x="play"]').onclick = (e) => { e.stopPropagation(); play(n); renderUI(); };
            it.querySelector('[data-x="del"]').onclick = (e) => {
                e.stopPropagation();
                if (state.playing === n) stop();
                delete state.library[n];
                saveLibrary();
                if (editing === n) editing = null;
                renderUI();
            };
            it.onclick = () => loadEditor(n);
            list.appendChild(it);
        }

        const fsel = root.querySelector('#mff-face');
        if (fsel) {
            const cur = fsel.value;
            fsel.innerHTML = faceOptions().map(o => `<option value="${o.v}">${o.t}</option>`).join('');
            if (cur) fsel.value = cur;
        }

        const st = root.querySelector('#mff-status');
        if (st) st.textContent = auto.on
            ? '⚡ auto ' + (state.playing ? '(loop paused)' : '')
            : (state.playing ? '▶ ' + state.playing : (editing ? 'editing: ' + editing : 'nothing playing'));
        updateAutoToggle();

        if (root.querySelector('[data-page="auto"]')?.style.display !== 'none') renderAutoForm();

        renderFrames();
    }

    function renderFrames() {
        const root = document.getElementById(ID);
        if (!root) return;
        const box = root.querySelector('#mff-frames');
        if (!editing || !state.library[editing]) {
            box.innerHTML = '<div style="color:#8a8a96;font-size:11px;padding:4px 0">Create a facial (+ New) or select one from the library to edit its frames</div>';
            return;
        }
        box.innerHTML = '';
        const frames = state.library[editing].frames;
        if (!frames.length) {
            box.innerHTML = '<div style="color:#8a8a96;font-size:11px;padding:4px 0">No frames — pick a face and press "+ Frame"</div>';
            return;
        }
        frames.forEach((f, i) => {
            const row = el('div', 'mff-frame');
            row.innerHTML = `
                <select data-k="face">${faceOptions().map(o => `<option value="${o.v}" ${o.v === f.face ? 'selected' : ''}>${o.t}</option>`).join('')}</select>
                    <input data-k="holdMs" type="number" min="20" step="20" value="${f.holdMs ?? 400}" title="Hold (ms)">
                        <input data-k="blendMs" type="number" min="0" step="20" value="${f.blendMs ?? 0}" title="Transition (ms)">
                            <img class="thumb" data-thumb="${f.face}" title="Face preview" alt="">
                                <button data-x="rm" title="Remove frame">✕</button>`;
            row.querySelector('[data-k="face"]').onchange = (e) => { f.face = e.target.value; renderFrames(); };
            row.querySelector('[data-k="holdMs"]').onchange = (e) => { f.holdMs = +e.target.value || 400; };
            row.querySelector('[data-k="blendMs"]').onchange = (e) => { f.blendMs = +e.target.value || 0; };
            row.querySelector('[data-x="rm"]').onclick = () => { frames.splice(i, 1); renderFrames(); };
            box.appendChild(row);
        });
        const total = frames.reduce((s, f) => s + (+f.holdMs || 400) + (+f.blendMs || 0), 0);
        const tot = el('div', '', `<span style="color:#8a8a96;font-size:10px">cycle: ${total} ms · ${(1000 / Math.max(1, total)).toFixed(2)} loops/s</span>`);
        box.appendChild(tot);

        fillThumbs(box);
    }

    function fillThumbs(box) {
        box.querySelectorAll('img[data-thumb]').forEach(img => {
            const name = img.dataset.thumb;
            resolveFace(name).then(fr => {
                if (!fr || !img.isConnected) return;

                const k = fr.kind === 'head' ? Math.max(1, Math.round(fr.canvas.width / 64)) : 1;
                const c = document.createElement('canvas');
                c.width = 8; c.height = 8;
                const cx = c.getContext('2d');
                cx.imageSmoothingEnabled = false;
                if (fr.kind === 'head') cx.drawImage(fr.canvas, FACE.x * k, FACE.y * k, FACE.w * k, FACE.h * k, 0, 0, 8, 8);
                else cx.drawImage(fr.canvas, 0, 0, 8, 8, 0, 0, 8, 8);
                img.src = c.toDataURL();
            }).catch(() => {});
        });
    }

    function presetOptions(sel, kind = 'dir') {
        const names = (window.MF_SkinEditor?.presets?.() || []).map(p => p.name);
        let html = '<option value="" ' + (sel ? '' : 'selected') + '>— (no change)</option>' +
            names.map(n => `<option value="${n}" ${n === sel ? 'selected' : ''}>✏️ ${n}</option>`).join('');
        if (packIndex.length) {
            html += '<optgroup label="Facial packs">';
            for (const p of packIndex) {
                const front = p.front || 'alfrente';
                const opts = kind === 'blink'
                    ? [`fs:${p.id}/${p.blink}`]
                    : [`fs:${p.id}/${front}`, `fs:${p.id}/${p.left}`, `fs:${p.id}/${p.right}`];
                for (const v of opts) {
                    const label = v.split('/').pop().replace(/\.png$/i, '');
                    const nm = (p.name || p.id) + (p.custom ? ' (zip)' : '');
                    html += `<option value="${v}" ${v === sel ? 'selected' : ''}>📦 ${nm}/${label}</option>`;
                }
            }
            html += '</optgroup>';
        }
        return html;
    }

    let packSel = null;
    function renderPacksTab() {
        const root = document.getElementById(ID);
        if (!root) return;
        const list = root.querySelector('#mff-packs');
        if (!list) return;
        if (packSel && !packIndex.some(p => p.id === packSel)) packSel = null;
        list.innerHTML = '';
        if (!packIndex.length) {
            list.innerHTML = '<div style="color:#8a8a96;font-size:11px;padding:4px 2px">No packs — import a ZIP</div>';
        }
        for (const p of packIndex) {
            const it = el('div', 'mff-item' + (packSel === p.id ? ' editing' : ''));
            const tag = p.server ? 'server' : (p.custom ? 'zip' : 'custom');
            it.innerHTML = `<span class="nm">${p.name || p.id}${p.custom ? ' <span class="meta">(zip)</span>' : ''}</span>
                <span class="meta">${tag}</span>`;
            it.onclick = () => { packSel = p.id; renderPacksTab(); };
            list.appendChild(it);
        }

        const det = root.querySelector('#mff-packdetail');
        if (det) {
            const p = packIndex.find(x => x.id === packSel);
            if (!p) {
                det.innerHTML = '<span style="color:#8a8a96">Select a pack from the list</span>';
            } else {
                const cur = currentSkinId();
                det.innerHTML = `
                    <div style="font-weight:700;font-size:13px;margin-bottom:2px">${p.name || p.id}</div>
                        <div style="color:#8a8a96;margin-bottom:8px">id: ${p.id}${p.author ? ' · by ' + p.author : ''} · v${p.version || 1} · ${p.server ? 'server skin (activates when you wear it in the wardrobe)' : p.custom ? 'ZIP imported' : 'custom (mypacks)'}</div>
                            <div class="mff-row" style="flex-wrap:wrap">
  <button data-pk="apply" title="Wear the pack's skin (builtin only)">👕 Use skin</button>
  <button data-pk="release" title="Remove the custom skin and go back to the server one">↩ Remove skin</button>
  <button data-pk="auto" title="Enable auto mode with this pack's sprites">⚡ Activate</button>
  <button data-pk="export" title="Download the pack as a ZIP (pack.json + PNGs)">📤 Export ZIP</button>
  ${p.custom ? '<button data-pk="del" title="Delete the imported pack">🗑</button>' : ''}
  </div>
      <div style="color:#8a8a96;margin-top:8px;font-size:10px">${cur === p.id ? '✓ this skin is worn — the face animates on its own' : 'the face animates when skin ' + p.id + ' is in use'}</div>`;
                det.querySelector('[data-pk="release"]').onclick = async () => {
                    try {
                        const ok = await releasePackSkin();
                        if (!ok) alert('no custom skin worn (you\'re already on the server one)');
                        renderPacksTab();
                    } catch (e) { alert('could not remove: ' + e.message); }
                };
                det.querySelector('[data-pk="apply"]').onclick = async () => {
                    if (p.server) {

                        alert('"' + (p.name || p.id) + '" is a server skin:\nput it on from the game\'s wardrobe (dressing room).\nThe animated face activates on its own when the skin is detected.');
                        return;
                    }
                    try {

                        await applyPackSkinToGame(p.id);
                        renderPacksTab();
                    } catch (e) { alert('could not apply: ' + e.message); }
                };
                det.querySelector('[data-pk="auto"]').onclick = async () => {

                    auto.front = 'fs:' + p.id + '/' + p.front;
                    auto.left = 'fs:' + p.id + '/' + p.left;
                    auto.right = 'fs:' + p.id + '/' + p.right;
                    auto.up = p.up ? 'fs:' + p.id + '/' + p.up : '';
                    auto.down = p.down ? 'fs:' + p.id + '/' + p.down : '';
                    auto.browFace = p.brow ? 'fs:' + p.id + '/' + p.brow : '';
                    auto.blinkClosed = 'fs:' + p.id + '/' + p.blink;
                    auto.blink = true;
                    skinWatch.userOff = false;
                    skinWatch.lastApplied = p.id;
                    saveAuto();
                    const r = await autoStart();
                    if (!r.ok) alert(r.error);
                    renderPacksTab();
                };
                det.querySelector('[data-pk="export"]').onclick = async () => {
                    try { await exportPackZip(p.id); }
                    catch (e) { alert('export: ' + e.message); }
                };
                const del = det.querySelector('[data-pk="del"]');
                if (del) del.onclick = async () => {
                    if (!confirm('Delete pack "' + (p.name || p.id) + '"?')) return;
                    await packsDbDel(p.id);
                    customPacks.delete(p.id);
                    if (skinWatch.lastApplied === p.id) skinWatch.lastApplied = null;
                    rebuildPackIndex();
                };
            }
        }
    }

    function renderAutoForm() {
        const root = document.getElementById(ID);
        if (!root) return;
        const form = root.querySelector('#mff-autoform');
        if (form) {
            const field = (key, label) => `
                <div class="mff-field"><label>${label}</label>
                    <select data-auto="${key}">${presetOptions(auto[key])}</select></div>`;
            form.innerHTML =
                field('front', '⬆ front') +
                field('left', '⬅ look left') +
                field('right', '➡ look right') +
                field('up', '⬆ look up') +
                field('down', '⬇ look down') +
                `<div class="mff-field"><label>turn threshold</label>
                    <input type="number" min="5" max="120" step="5" value="${auto.yawThreshold}" data-auton="yawThreshold" title="Yaw degrees to activate (default 10)"></div>` +
                `<div class="mff-field"><label>vert threshold</label>
                    <input type="number" min="5" max="80" step="5" value="${auto.pitchThreshold}" data-auton="pitchThreshold" title="Pitch degrees to activate (default 10)"></div>`;
            form.querySelectorAll('[data-auto]').forEach(s => s.onchange = () => {
                auto[s.dataset.auto] = s.value; saveAuto();
                auto._zone = null;
            });
            form.querySelectorAll('[data-auton]').forEach(i => i.onchange = () => {
                auto[i.dataset.auton] = Math.max(5, +i.value || 10); saveAuto();
            });
        }
        const bf = root.querySelector('#mff-blinkform');
        if (bf) {
            bf.innerHTML = `
                <div class="mff-check"><input type="checkbox" id="mff-blinkon" ${auto.blink ? 'checked' : ''}>
  <label for="mff-blinkon">Blink only at random intervals</label></div>
      <div class="mff-field"><label>closed eyes</label>
          <select data-auto="blinkClosed">${presetOptions(auto.blinkClosed, 'blink')}</select></div>
              <div class="mff-field"><label>every min (s)</label>
                  <input type="number" min="0.5" max="30" step="0.5" value="${(auto.blinkMinMs / 1000).toFixed(1)}" data-blink="min"></div>
                      <div class="mff-field"><label>every max (s)</label>
                          <input type="number" min="1" max="60" step="0.5" value="${(auto.blinkMaxMs / 1000).toFixed(1)}" data-blink="max"></div>
                              <div class="mff-check"><input type="checkbox" id="mff-browon" ${auto.brow ? 'checked' : ''}>
  <label for="mff-browon">🤨 raise the brow when a "?" appears in chat</label></div>
      <div class="mff-field"><label>brow (optional)</label>
          <select data-auto="browFace">${presetOptions(auto.browFace, 'brow')}</select></div>
              <div class="mff-field"><label>duration (s)</label>
                  <input type="number" min="0.3" max="5" step="0.1" value="${(auto.browMs / 1000).toFixed(1)}" data-brow="ms"></div>
                      <div class="mff-check"><input type="checkbox" id="mff-otherson" ${others.on ? 'checked' : ''}>
  <label for="mff-otherson">👥 animate others (local blink, machinima)</label></div>
      <div class="mff-field"><label>others min (s)</label>
          <input type="number" min="0.5" max="30" step="0.5" value="${(others.intervalMinMs / 1000).toFixed(1)}" data-others="min"></div>
              <div class="mff-field"><label>others max (s)</label>
                  <input type="number" min="1" max="60" step="0.5" value="${(others.intervalMaxMs / 1000).toFixed(1)}" data-others="max"></div>`;
            const chk = bf.querySelector('#mff-blinkon');
            if (chk) chk.onchange = () => { auto.blink = chk.checked; saveAuto(); };
            const sel = bf.querySelector('[data-auto="blinkClosed"]');
            if (sel) sel.onchange = () => {
                auto.blinkClosed = sel.value; saveAuto();
                state.frameCache.delete('p:' + sel.value);
                auto._blinkCache = null;
            };
            bf.querySelectorAll('[data-blink]').forEach(i => i.onchange = () => {
                const v = Math.max(0.3, +i.value || 2) * 1000;
                if (i.dataset.blink === 'min') auto.blinkMinMs = v;
                else auto.blinkMaxMs = Math.max(v, auto.blinkMinMs);
                saveAuto();
            });
            const browChk = bf.querySelector('#mff-browon');
            if (browChk) browChk.onchange = () => { auto.brow = browChk.checked; saveAuto(); };
            const browSel = bf.querySelector('[data-auto="browFace"]');
            if (browSel) browSel.onchange = () => { auto.browFace = browSel.value; saveAuto(); };
            const browMs = bf.querySelector('[data-brow="ms"]');
            if (browMs) browMs.onchange = () => {
                auto.browMs = Math.max(0.3, +browMs.value || 1.4) * 1000;
                saveAuto();
            };
            const othersChk = bf.querySelector('#mff-otherson');
            if (othersChk) othersChk.onchange = () => {
                if (othersChk.checked) othersStart();
                else othersStop();
            };
            bf.querySelectorAll('[data-others]').forEach(i => i.onchange = () => {
                const v = Math.max(0.3, +i.value || 2.5) * 1000;
                if (i.dataset.others === 'min') others.intervalMinMs = v;
                else others.intervalMaxMs = Math.max(v, others.intervalMinMs);
                saveOthers();
            });
        }
        updateAutoLive();
    }

    function updateAutoLive() {
        const root = document.getElementById(ID);
        const live = root?.querySelector('#mff-autolive');
        if (!live) return;
        const a = lookAngles();
        const rows = [];
        rows.push('auto: ' + (auto.on ? '<b style="color:#3ecf8e">ON</b>' : 'off'));
        if (a) {
            rows.push('rel: ' + a.yaw.toFixed(0) + '° / ' + a.pitch.toFixed(0) + '° · abs: ' + a.absYaw.toFixed(0) + '° / ' + a.absPitch.toFixed(0) + '°');
            const z = zoneOf(a);
            const preset = z === 'front' ? (auto.front || '(current front)') : (auto[z] || '(no preset)');
            rows.push('zone: ' + z + ' → ' + preset);
        } else {
            rows.push('(enter a world to see angles)');
        }
        if (auto.blink) {
            const next = Math.max(0, (auto._nextBlink - performance.now()) / 1000).toFixed(1);
            rows.push('next blink: ' + (auto.on ? next + ' s' : '—'));
        }
        live.innerHTML = rows.join('<br>');
        if (auto.on && root && !root.dataset.autoLiveRaf) {
            root.dataset.autoLiveRaf = '1';
            const loop = () => {
                const r = document.getElementById(ID);
                if (!r) { delete (r || {}).dataset; return; }
                const l = r.querySelector('#mff-autolive');
                if (!l) { delete r.dataset.autoLiveRaf; return; }
                updateAutoLiveInner(l);
                requestAnimationFrame(loop);
            };
            requestAnimationFrame(loop);
        }
    }
    function updateAutoLiveInner(live) {
        const a = lookAngles();
        const rows = [];
        rows.push('auto: ' + (auto.on ? '<b style="color:#3ecf8e">ON</b>' : 'off'));
        if (a) {
            rows.push('rel: ' + a.yaw.toFixed(0) + '° / ' + a.pitch.toFixed(0) + '° · abs: ' + a.absYaw.toFixed(0) + '° / ' + a.absPitch.toFixed(0) + '°');
            const z = zoneOf(a);
            const preset = z === 'front' ? (auto.front || '(current front)') : (auto[z] || '(no preset)');
            rows.push('zone: ' + z + ' → ' + preset);
        }
        if (auto.blink && auto.on) {
            const next = Math.max(0, (auto._nextBlink - performance.now()) / 1000).toFixed(1);
            rows.push('next blink: ' + next + ' s');
        }
        live.innerHTML = rows.join('<br>');
    }

    function loadEditor(name) {
        editing = name;
        renderUI();
    }

    function ensureEditing() {
        if (editing && state.library[editing]) return editing;
        const names = Object.keys(state.library);
        editing = state.playing || names[0] || null;
        if (editing) renderUI();
        return editing;
    }

    function el(cls, html) {
        const d = document.createElement('div');
        if (cls) d.className = cls;
        if (html != null) d.innerHTML = html;
        return d;
    }

    function bindUI(root) {
        root.querySelector('[data-act="close"]').onclick = () => close();

        root.querySelectorAll('[data-tab]').forEach(b => b.onclick = () => {
            root.querySelectorAll('[data-tab]').forEach(x => x.classList.toggle('on', x === b));
            root.querySelectorAll('.mff-body').forEach(pg =>
                pg.style.display = (pg.dataset.page === b.dataset.tab) ? 'flex' : 'none');
            if (b.dataset.tab === 'auto') renderAutoForm();
        });

        const at = root.querySelector('#mff-autotoggle');
        if (at) at.onclick = async () => {
            if (auto.on) {
                autoStop(); skinWatch.userOff = true;
                try { localStorage.setItem(LS_KEY + '_autoUserOff', '1'); } catch {}
            }
            else { const r = await autoStart(); if (!r.ok) alert(r.error); }
            saveAuto();
            updateAutoToggle();
        };
        root.querySelector('#mff-new').onclick = () => {
            const n = prompt('New facial name:', 'my facial');
            if (!n) return;
            if (state.library[n]) { alert('already exists'); return; }
            state.library[n] = { frames: [] };
            saveLibrary();
            editing = n;
            renderUI();
        };
        root.querySelector('#mff-add').onclick = () => {
            if (!ensureEditing()) { alert('create a facial first with "+ New"'); return; }
            const face = root.querySelector('#mff-face').value || 'base';
            state.library[editing].frames.push({ face, holdMs: 400, blendMs: 0 });
            saveLibrary();
            renderUI();
        };
        root.querySelector('#mff-save').onclick = () => {
            if (!ensureEditing()) { alert('create a facial first'); return; }
            saveLibrary();
            renderUI();
        };
        root.querySelector('#mff-play').onclick = async () => {
            if (!ensureEditing()) { alert('create a facial first'); return; }
            const r = await play(editing);
            if (!r.ok) alert(r.error);
            renderUI();
        };
        root.querySelector('#mff-stop').onclick = () => { stop(); };
        root.querySelector('#mff-del').onclick = () => {
            if (!editing) return;
            if (state.playing === editing) stop();
            delete state.library[editing];
            editing = null;
            saveLibrary();
            renderUI();
        };
        root.querySelector('#mff-seed').onclick = () => {
            window.MF_Facial.seedTemplates();
        };

        const pfile = root.querySelector('#mff-packfile');
        const pbtn = root.querySelector('#mff-packimport');
        if (pbtn) {
            pbtn.onclick = () => pfile?.click();
            if (pfile) pfile.onchange = async () => {
                const f = pfile.files?.[0];
                pfile.value = '';
                if (!f) return;
                pbtn.textContent = '⏳ importing…';
                pbtn.disabled = true;
                try {
                    const p = await importPackZip(f);
                    packSel = p.id;
                    renderPacksTab();
                    alert('pack "' + (p.name || p.id) + '" imported ✓\n(skin applied and animated face active)');
                } catch (e) {
                    alert('import ZIP: ' + e.message);
                } finally {
                    pbtn.textContent = '📥 Import ZIP';
                    pbtn.disabled = false;
                }
            };
        }

        const ptab = root.querySelector('[data-tab="packs"]');
        if (ptab) ptab.addEventListener('click', renderPacksTab);
        updateAutoToggle();
    }

    function updateAutoToggle() {
        const at = document.querySelector('#' + ID + ' #mff-autotoggle');
        if (at) at.classList.toggle('on', auto.on);
    }

    function open() {
        if (state.open) { renderUI(); return; }
        state.open = true;
        loadLibrary(); state.dirty = false;
        loadAuto();

        if (!Object.keys(state.library).length) {
            state.library = { ...buildTemplates() };
            saveLibrary();
        }
        buildUI();
        ensureEditing();
    }

    function close() {
        document.getElementById(ID)?.remove();
        document.getElementById(ID + '-style')?.remove();
        state.open = false;
    }

    window.MF_Facial = {
        open, close,
        play, stop,
        loadLibrary, saveLibrary,
        get library() { return state.library; },
        get playing() { return state.playing; },

        get autoOn() { return auto.on; },
        autoStart, autoStop,
        get autoConfig() { return auto; },
        setAutoConfig(patch) {
            Object.assign(auto, patch);
            saveAuto();
            auto._zone = null;

            auto._blinkCache = null;
            renderAutoForm();
            return { ok: true };
        },

        seedTemplates() {
            state.library = { ...state.library, ...buildTemplates() };
            saveLibrary();
            renderUI();
            return { ok: true };
        },

        get packs() { return packIndex.map(p => ({ ...p })); },
        importPackZip, exportPackZip,
        applyPack: applyPackSkinToGame,
        releasePack: releasePackSkin,

        deletePack: async function (id) {
            await packsDbDel(id);
            customPacks.delete(id);
            if (skinWatch.lastApplied === id) skinWatch.lastApplied = null;
            rebuildPackIndex();
            return { ok: true };
        },

        applyCustomSkin: async function (name, pngUrl) {
            if (pngUrl) {
                packSkinReg[MF_NAME_PREFIX + name] = pngUrl;
            } else if (!registerPackSkin(name)) {
                throw new Error('the pack "' + name + '" has no PNG skin');
            }
            installPackImgHook();
            return applyPackSkinToGame(name);
        },

        registerCustomSkin: function (name, pngUrl) {
            if (typeof name !== 'string' || typeof pngUrl !== 'string') return false;
            installPackImgHook();
            packSkinReg[MF_NAME_PREFIX + name] = pngUrl;
            return true;
        },
        diag(deep = false) {
            const mesh = getMesh();
            const rows = ['mesh: ' + (mesh ? mesh.constructor?.name || 'ok' : 'NO (¿dentro de un mundo?)')];
            if (mesh) {
                if (deep) {
                    const seen = new Set();
                    mesh.traverse(o => {
                        if (!o?.material) return;
                        const list = Array.isArray(o.material) ? o.material : [o.material];
                        list.forEach((m, i) => {
                            if (!m?.map || seen.has(m)) return;
                            seen.add(m);
                            const im = m.map.image;
                            rows.push('  mat<' + seen.size + '> ' + (im ? im.width + 'x' + im.height : 'sin imagen') +
                                ' @ ' + (o.name || o.type || '?') +
                                (o.parent ? ' ← ' + (o.parent.name || o.parent.type || '?') : '') +
                                ' src=' + String(m.map.source?.data?.src || m.map.userData?.src || '').slice(0, 60));
                        });
                    });
                    rows.push('--- fin materiales (' + seen.size + ') ---');
                    const reg = mesh.meshes;
                    if (reg && typeof reg === 'object') rows.push('mesh.meshes keys: ' + Object.keys(reg).join(', '));
                }
                const mats = findSkinMaterials(mesh);
                rows.push('skinMaterials: ' + mats.length);
                mats.forEach((m, i) => {
                    const im = m.map?.image;
                    rows.push('  [' + i + '] ' + (im ? im.width + 'x' + im.height : 'sin imagen') +
                        (m.map && (m.map.__mfLocalCanvas || m.map.__mfOtherKey || m.map.__mfPeerCanvas) ? ' (facial ✓ montada)' : '') +
                        (m.map === state.tex ? ' (activa)' : ''));
                });
            }
            rows.push('state.tex: ' + (state.tex ? 'viva' : 'null') +
                ' · baseHead: ' + (state.baseHead ? 'sí' : 'no') +
                ' · auto: ' + (auto.on ? 'ON (zona ' + (auto._zone || '?') + ')' : 'off') +
                ' · playing: ' + (state.playing || 'nada'));
            const txt = rows.join('\n');
            console.log(TAG + '\n' + txt);
            return txt;
        }
    };
    window.__MF_Facial = true;
    document.addEventListener('minifeather:facial-open', () => {
        state.open ? close() : open();
    });

    const LS_LAST = LS_KEY + '_last';
    try {
        loadAuto();
        const last = localStorage.getItem(LS_LAST);
        const wantAuto = auto.on;
        if (last || wantAuto) loadLibrary();
        if (wantAuto || (last && state.library[last])) {

            const boot = setInterval(() => {
                if (state.playing || auto._raf) { clearInterval(boot); return; }
                try {
                    const g = getGame();
                    if (g?.player?.mesh) {
                        clearInterval(boot);
                        if (wantAuto) { auto.on = false; autoStart().then(r => { if (r.ok) void 0; }); }
                        else if (last && state.library[last]) {
                            play(last).then(r => {
                                if (r.ok) void 0;
                            });
                        }
                    }
                } catch {}
            }, 1500);
            setTimeout(() => clearInterval(boot), 60000);
        }
    } catch {}

    if (others.on) {
        const boot2 = setInterval(() => {
            if (others._raf) { clearInterval(boot2); return; }
            try {
                const g = getGame();
                if (g?.player?.mesh) {
                    clearInterval(boot2);
                    others.on = false;
                    othersStart();
                }
            } catch {}
        }, 1500);
        setTimeout(() => clearInterval(boot2), 60000);
    }

    const skinWatch = { timer: null, lastApplied: null, userOff: false, busy: false, uuidDone: false };
    async function applyPackForSkin(force = false) {
        if (skinWatch.busy) return null;
        skinWatch.busy = true;
        try {
            const skinId = currentSkinId();
            if (!skinId) return null;

            const uid = currentPlayerUuid();
            let pack = uid ? packIndex.find(p => p.uuid === uid) : null;
            if (pack && pack.id !== skinId) {
                if (skinWatch.uuidDone) return null;
                skinWatch.uuidDone = true;
                if (!force && skinWatch.lastApplied === pack.id) return null;

                debugBrow('uuid skin: facial-only (skin intacta: ' + skinId + ')');
            } else {
                pack = packIndex.find(p => p.id === skinId);
            }
            if (!pack) { skinWatch.lastApplied = null; return null; }
            const pid = pack.id;
            if (!force && skinWatch.lastApplied === pid) return null;

            let frontFile = pack.front || null;
            if (!frontFile) {
                const hit = await loadPackFront(pid);
                if (!hit) return null;
                frontFile = hit.usedName;
                pack.front = frontFile;
            }

            let tries = 0;
            while (tries++ < 20 && !getMesh()) await new Promise(r => setTimeout(r, 250));
            if (!getMesh()) return null;

            auto.front = 'fs:' + pid + '/' + frontFile;
            auto.left = 'fs:' + pid + '/' + pack.left;
            auto.right = 'fs:' + pid + '/' + pack.right;
            auto.up = pack.up ? 'fs:' + pid + '/' + pack.up : '';
            auto.down = pack.down ? 'fs:' + pid + '/' + pack.down : '';
            auto.browFace = pack.brow ? 'fs:' + pid + '/' + pack.brow : '';
            auto.brow = !!pack.brow;
            auto.blinkClosed = 'fs:' + pid + '/' + pack.blink;
            auto.blink = true;
            saveAuto();
            skinWatch.lastApplied = pid;
            skinWatch.userOff = false;
            const r = await autoStart();
            if (r.ok) void 0;
            return r;
        } finally { skinWatch.busy = false; }
    }

    skinWatch.timer = setInterval(() => {
        if (skinWatch.busy) return;
        fetchApiSkin().then(() => {

            if (!auto.on && !skinWatch.userOff && !skinWatch.uuidDone) {
                const uid = currentPlayerUuid();
                const byUuid = uid ? packIndex.find(p => p.uuid === uid) : null;
                if (byUuid && skinWatch.lastApplied !== byUuid.id) {
                    void 0;
                    applyPackForSkin(true).catch(() => {});
                    return;
                }
            }
            const sid = currentSkinId();
            if (!sid) return;

            if (auto.on && skinWatch.lastApplied && skinWatch.lastApplied !== sid &&
                !packIndex.some(p => p.id === sid)) {
                skinWatch.lastApplied = null;
                autoStop(true);
                return;
            }
            if (!auto.on) {

                if (!skinWatch.userOff && skinWatch.lastApplied !== sid) applyPackForSkin().catch(() => {});
            } else if (sid !== skinWatch.lastApplied) {
                applyPackForSkin(true).catch(() => {});
            }
        });
    }, 4000);

    const packBoot = setInterval(() => {
        if (getMesh() && currentSkinId()) {
            clearInterval(packBoot);
            fetchApiSkin(0).finally(() => applyPackForSkin().catch(() => {}));
        }
    }, 1000);
    setTimeout(() => clearInterval(packBoot), 120000);
    const autoBoot = setInterval(() => {
        if (!getMesh()) return;
        clearInterval(autoBoot);
        let userOff = false;
        try { userOff = localStorage.getItem(LS_KEY + '_autoUserOff') === '1'; } catch {}
        if (auto.front && !userOff) autoStart();
    }, 1000);
    setTimeout(() => clearInterval(autoBoot), 120000);
    window.addEventListener('minifeather:skin-repainted', (e) => {
        try {
            if (!auto.on && !state.playing) return;
            const paintedMesh = e.detail?.mesh;
            const mesh = getMesh();
            if (!mesh) return;
            const pid = paintedMesh?.entity?.id ?? paintedMesh?.entity?.entityId;
            const mid = mesh.entity?.id ?? mesh.entity?.entityId;
            if (paintedMesh !== mesh && !(pid != null && pid === mid)) return;
            try {
                const newAuth = [];
                paintedMesh.traverse(o => {
                    const list = o?.material ? (Array.isArray(o.material) ? o.material : [o.material]) : [];
                    for (const m of list) if (m?.map?.__mfPainted) newAuth.push(m.map);
                });
                if (newAuth[0]) {
                    state.authTex = newAuth[0];
                    state.lastMirror = 0;
                }
            } catch {}
            state.tex = null;
            state.baseHead = null;
            state.frameCache.clear();
            auto._blinkCache = null; auto._blinkCacheZone = null;
            ensureSession();
            paintZone(auto._zone || 'front', true);
        } catch {}
    });
    setInterval(() => {
        if (!auto.on || !auto.front) return;
        const mesh = getMesh();
        if (!mesh) return;
        try {
            const mats = findSkinMaterials(mesh);
            if (!mats.length) return;
            const paintedUnder = mats
                .map(m => m.map?.__mfPainted)
                .find(u => typeof u === 'string');
            if (paintedUnder && paintedUnder !== state.baseSkinPainted) {
                state.baseSkinPainted = paintedUnder;
                state.tex = null;
                state.baseHead = null;
                state.frameCache.clear();
                auto._blinkCache = null; auto._blinkCacheZone = null;
                ensureSession();
                paintZone(auto._zone || 'front', true);
                return;
            }
            const anyMounted = mats.some(m => m.map === state.tex);
            if (!anyMounted) {
                state.tex = null;
                state.baseHead = null;
                ensureSession();
                paintZone(auto._zone || 'front', true);
            } else {
                for (const m of mats) {
                    if (m.map !== state.tex) { m.map = state.tex; m.needsUpdate = true; }
                }
                const nowMs = performance.now();
                if (state.authTex?.image && state.tex?.image instanceof HTMLCanvasElement
                    && nowMs - (state.lastMirror || 0) > 400) {
                    state.lastMirror = nowMs;
                    try {
                        const cx = state.tex.image.getContext('2d');
                        cx.imageSmoothingEnabled = false;
                        const ai = state.authTex.image, ti = state.tex.image;
                        cx.drawImage(ai, 0, 0, ai.width, ai.height, 0, 0, ti.width, ti.height);
                        state.tex.needsUpdate = true;
                        paintZone(auto._zone || 'front', true);
                    } catch {}
                }
            }
        } catch {}
    }, 500);

    const packsReady = Promise.all([
        loadBuiltinPacks().catch(() => {}),
        loadCustomPacks().catch(() => {})
    ]);
    packsReady.then(() => applyPackForSkin().catch(() => {}));

    {
        const origPlay = window.MF_Facial.play;
        window.MF_Facial.play = async function (name) {
            try { localStorage.setItem(LS_LAST, name); } catch {}
            return origPlay(name);
        };
    }

    void 0;
})();

//# sourceURL=MF:src/Studio/MF_Facial.js

/* ==== mf module: src/Studio/MF_Film.js ==== */

(function () {
    'use strict';

    if (window.__MF_Film) return;
    const TAG = 'minifeather film';

    const TPS = 20;

    const TICK_MS = 1000 / TPS;
    const JOINT_NAMES = [
        'headPivot', 'body', 'skeleton',
        'leftShoulderJoint', 'leftElbowJoint',
        'rightShoulderJoint', 'rightElbowJoint',
        'leftHipJoint', 'leftKneeJoint',
        'rightHipJoint', 'rightKneeJoint'
    ];

    const POS_ONLY_JOINTS = new Set(['skeleton']);
    const EPS = 1e-4;

    const LS_KEY = 'minifeather_films_v1';
    const LS_LIMIT = 45 * 1024 * 1024;

    const state = {

        recording: false,
        recStart: 0,

        recTick: 0,
        recTimer: null,
        frames: [],
        lastFrame: null,
        droppedTicks: 0,

        playing: false,
        paused: false,
        playStart: 0,

        playTickBase: 0,

        playRange: null,

        playRaf: null,
        playFilm: null,
        playMode: 'film',

        playSeq: null,

        actors: new Map(),

        films: null
    };

    function getGame() {
        if (globalThis.miniblox?.player) return globalThis.miniblox;
        try {
            const react = document.querySelector('#react');
            if (react) {
                for (const root of Object.values(react)) {
                    const game = root?.updateQueue?.baseState?.element?.props?.game;
                    if (game?.player) return game;
                }
            }
        } catch {}
        return null;
    }

    function getLocalPlayerEntity(game) {
        const me = game?.player;
        if (!me) return null;
        try { const e = game.world?.getPlayerById?.(me.id); if (e?.mesh) return e; } catch {}
        try { const e = game.world?.players?.get?.(me.id); if (e?.mesh) return e; } catch {}
        try { const e = game.world?.entities?.get?.(me.id); if (e?.mesh) return e; } catch {}
        try {
            const ents = game.world?.entities;
            if (ents?.values) {
                for (const e of ents.values()) {
                    if (e?.uuid === me.uuid || e?.id === me.id) return e;
                }
            }
        } catch {}
        return me?.mesh ? me : null;
    }

    function findJoint(mesh, name) {
        if (!mesh) return null;
        if (mesh[name] && mesh[name].rotation) return mesh[name];
        const queue = [mesh];
        const seen = new WeakSet();
        let visited = 0;
        while (queue.length && visited < 500) {
            const obj = queue.shift();
            if (!obj || typeof obj !== 'object' || seen.has(obj)) continue;
            seen.add(obj);
            visited++;
            if (obj[name] && obj[name].rotation) return obj[name];
            if (Array.isArray(obj.children)) {
                for (const child of obj.children) queue.push(child);
            }
        }
        return null;
    }

    function captureFrame(ent, tick) {
        const mesh = ent?.mesh;
        const pos = ent?.pos || mesh?.position;
        if (!pos) return null;

        const frame = {
            t: tick,
            p: [+pos.x || 0, +pos.y || 0, +pos.z || 0],
            yaw: +ent?.yaw || 0,
            pitch: +ent?.pitch || 0,
            sneak: !!ent?.sneaking,
            sprint: !!ent?.sprinting
        };

        if (mesh) {
            const j = {};
            for (const name of JOINT_NAMES) {
                const joint = findJoint(mesh, name);
                if (!joint) continue;
                if (POS_ONLY_JOINTS.has(name)) {
                    j[name] = [joint.position.x, joint.position.y, joint.position.z];
                } else {
                    const r = joint.rotation;
                    j[name] = [r.x, r.y, r.z];
                }
            }
            frame.j = j;
        }
        return frame;
    }

    function frameDiffers(a, b) {
        if (!a) return true;
        if (Math.abs(a.yaw - b.yaw) > EPS || Math.abs(a.pitch - b.pitch) > EPS) return true;
        if (a.sneak !== b.sneak || a.sprint !== b.sprint) return true;
        for (let i = 0; i < 3; i++) if (Math.abs(a.p[i] - b.p[i]) > EPS) return true;
        const ja = a.j || {}, jb = b.j || {};
        for (const k in jb) {
            const va = ja[k];
            if (!va) return true;
            for (let i = 0; i < 3; i++) if (Math.abs(va[i] - jb[k][i]) > EPS) return true;
        }
        return false;
    }

    function recorderTick() {
        const game = getGame();
        const ent = getLocalPlayerEntity(game);
        if (!ent) return;

        const now = performance.now();

        const expected = Math.floor((now - state.recStart) / TICK_MS);
        if (expected > state.recTick + 1) {
            state.droppedTicks += expected - state.recTick - 1;
        }
        state.recTick = expected;

        const frame = captureFrame(ent, state.recTick);
        if (frame && frameDiffers(state.lastFrame, frame)) {
            state.frames.push(frame);
            state.lastFrame = frame;
        }
    }

    function startRecording() {
        if (state.recording) return { ok: false, error: 'already recording' };
        const game = getGame();
        const ent = getLocalPlayerEntity(game);
        if (!ent) return { ok: false, error: 'player/mesh not available (are you in a game?)' };
        state.recording = true;
        state.recStart = performance.now();
        state.recTick = 0;
        state.frames = [];
        state.lastFrame = null;
        state.droppedTicks = 0;
        state.recTimer = setInterval(recorderTick, TICK_MS);
        return { ok: true, fromTick: 0 };
    }

    function stopRecording() {
        if (!state.recording) return { ok: false, error: 'not recording' };
        clearInterval(state.recTimer);
        state.recTimer = null;
        state.recording = false;

        // flush del último tick; si no se capturó nada no se inventa un frame en el origen del mundo
        if (state.lastFrame) state.frames.push({ ...state.lastFrame, t: state.recTick });
        return {
            ok: true,
            keyframes: state.frames.length,
            ticks: state.recTick,
            droppedTicks: state.droppedTicks
        };
    }

    function loadFilms() {
        if (state.films) return state.films;
        try {
            const p = JSON.parse(localStorage.getItem(LS_KEY) || '{}');
            // storage corrupto puede parsear a null/número/array: el resto del módulo asume un objeto
            state.films = (p && typeof p === 'object' && !Array.isArray(p)) ? p : {};
        } catch { state.films = {}; }
        return state.films;
    }

    function persistFilms() {
        try {
            const json = JSON.stringify(state.films);
            if (json.length > LS_LIMIT) return { ok: false, error: 'storage limit (' + (LS_LIMIT / 1048576).toFixed(0) + 'MB) reached: export and delete old takes' };
            localStorage.setItem(LS_KEY, json);
            return { ok: true };
        } catch (e) {
            return { ok: false, error: 'could not save (quota?): ' + (e?.message || e) };
        }
    }

    function currentTakeAsFilm(name) {
        const game = getGame();
        return {
            version: 1,
            name: name || ('take-' + new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-')),
            fps: TPS,
            durationTicks: state.recTick,
            recordedAt: Date.now(),
            server: (game?.server || '').toString().slice(0, 64) || null,
            actors: [{
                id: 'actor-1',

                skin: game?.player?.profile?.username || null,
                frames: state.frames
            }]
        };
    }

    function saveFilm(name) {
        if (!state.frames.length) return { ok: false, error: 'no take in memory (record first)' };
        const films = loadFilms();
        const film = currentTakeAsFilm(name);
        if (!name) {
            // el nombre automático tiene precisión de segundo: no pisar la toma grabada hace un segundo
            const base = film.name;
            for (let n = 2; films[film.name]; n++) film.name = base + '-' + n;
        }
        films[film.name] = film;
        state.films = films;
        const r = persistFilms();
        return r.ok ? { ok: true, name: film.name, keyframes: film.actors[0].frames.length, ticks: film.durationTicks } : r;
    }

    function deleteFilm(name) {
        const films = loadFilms();
        if (!(name in films)) return { ok: false, error: 'does not exist "' + name + '"' };
        delete films[name];
        state.films = films;
        const r = persistFilms();
        return r.ok ? { ok: true } : r;
    }

    function exportFilm(name) {
        const films = loadFilms();
        const film = name ? films[name] : (state.frames.length ? currentTakeAsFilm(name) : null);
        if (!film) return { ok: false, error: 'take not found (neither in memory nor saved)' };
        const blob = new Blob([JSON.stringify(film)], { type: 'application/json' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = (film.name || 'film') + '.mffilm.json';
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
        return { ok: true, name: film.name };
    }

    function importFilm(name, data) {
        if (!data || typeof data !== 'object') return { ok: false, error: 'invalid data' };
        if (!Array.isArray(data.actors) || !data.actors.length ||
            !data.actors.every(a => Array.isArray(a?.frames))) {
            return { ok: false, error: '.mffilm.json format not recognized (no actors)' };
        }
        const films = loadFilms();
        const finalName = name || data.name || ('imported-' + Date.now());
        // la duración es el último tick grabado, no el número de keyframes (una toma quieta tiene 10 frames y 600 ticks)
        let lastTick = 0;
        for (const a of data.actors) {
            const fr = a.frames;
            if (fr.length) lastTick = Math.max(lastTick, +fr[fr.length - 1].t || 0);
        }
        const film = {
            ...data,
            name: finalName,
            version: data.version || 1,
            durationTicks: data.durationTicks || lastTick
        };
        films[finalName] = film;
        state.films = films;
        const r = persistFilms();
        return r.ok ? { ok: true, name: finalName, ticks: film.durationTicks } : r;
    }

    function countNodes(o) {
        let n = 1;
        for (const c of (o.children || [])) n += countNodes(c);
        return n;
    }

    function manualCloneNode(src) {
        let node;
        try {
            if (src.isSkinnedMesh) {

                node = new src.constructor(src.geometry, src.material);
                try {
                    node.bind(src.skeleton, src.bindMatrix || src.matrixWorld?.clone?.() || null);
                } catch {}
            } else if (src.isMesh) {
                node = new src.constructor(src.geometry, src.material);
            } else {
                node = new src.constructor();
            }
        } catch { return null; }
        try {
            node.position.copy(src.position);
            node.quaternion.copy(src.quaternion);
            node.scale.copy(src.scale);
            if (src.name) node.name = src.name;
            node.visible = src.visible !== false;
            node.matrixAutoUpdate = true;
            node.frustumCulled = false;
        } catch {}
        for (const child of (src.children || [])) {
            const c = manualCloneNode(child);
            if (c) node.add(c);
        }
        return node;
    }

    function clonePlayerMesh() {
        const ent = getLocalPlayerEntity(getGame());
        const mesh = ent?.mesh;
        if (!mesh) return null;

        let clone = null;
        if (typeof mesh.clone === 'function') {
            try {
                const c = mesh.clone(true);

                if (c && countNodes(c) === countNodes(mesh)) clone = c;
            } catch {}
        }
        if (!clone) {
            clone = manualCloneNode(mesh);
            if (clone) void 0;
        }
        if (!clone) {
            console.warn(TAG + ' clone del player failed por completo');
            return null;
        }
        try {
            clone.traverse(o => {
                o.matrixAutoUpdate = true;
                o.frustumCulled = false;

                o.visible = true;
            });
        } catch {}

        try {
            let checks = 0;
            const wd = setInterval(() => {
                checks++;
                try {
                    if (!clone.parent) { clearInterval(wd); return; }
                    clone.traverse(o => {
                        if (o.visible === false) o.visible = true;
                    });
                } catch {}
                if (checks >= 40) clearInterval(wd);
            }, 250);
        } catch {}
        return clone;
    }

    function despawnOne(actorId) {
        const rec = state.actors.get(actorId);
        if (!rec) return;
        if (rec.isClone) {
            try { rec.root?.parent?.remove(rec.root); } catch {}
        } else {
            try { window.MF_CustomModels?.despawn?.(rec.cmId, true); } catch {}
        }
        state.actors.delete(actorId);
    }

    function spawnActor(actor) {
        const id = 'film_' + actor.id;
        const game = getGame();
        const scene = game?.gameScene?.scene;
        if (!scene) return null;
        const first = actor.frames?.[0];
        // film corrupto o sin frames: mejor sin actor que un TypeError dentro del rAF dejando el playback colgado
        if (!first?.p) return null;
        despawnOne(actor.id);

        const clone = clonePlayerMesh();
        if (clone) {
            clone.position.set(first.p[0], first.p[1], first.p[2]);
            clone.rotation.set(0, first.yaw || 0, 0);
            scene.add(clone);
            const rec = { root: clone, yaw: first.yaw || 0, isClone: true, cmId: id };
            state.actors.set(actor.id, rec);
            void 0;
            return rec;
        }

        const CM = window.MF_CustomModels;
        if (!CM?.spawn) return null;
        CM.spawn('verity_full_model.glb', first.p[0], first.p[1], first.p[2], {
            id,
            height: 1.8,
            followPlayer: false,
            puppet: true,
            lookAtPlayer: false
        });
        const rec = { root: null, yaw: first.yaw || 0, isClone: false, cmId: id };
        state.actors.set(actor.id, rec);
        return rec;
    }

    function ensureActor(film, actor) {
        let rec = state.actors.get(actor.id);
        // cambio de mundo/escena: el clon quedó huérfano, respawnear en la escena actual
        if (rec && rec.isClone && rec.root && !rec.root.parent) {
            despawnOne(actor.id);
            rec = null;
        }
        if (!rec) rec = spawnActor(actor);
        if (!rec) return null;
        if (!rec.isClone) {

            rec.root = window.MF_CustomModels?.getRecord?.(rec.cmId)?.root || rec.root || null;
        }
        return rec;
    }

    function sampleFrame(frames, tick) {

        let lo = 0, hi = frames.length - 1;
        if (tick <= frames[0].t) return { frame: frames[0], prev: frames[0], f: 0 };
        if (tick >= frames[hi].t) return { frame: frames[hi], prev: frames[hi], f: 0 };
        while (lo < hi - 1) {
            const mid = (lo + hi) >> 1;
            if (frames[mid].t <= tick) lo = mid; else hi = mid;
        }
        const prev = frames[lo], next = frames[lo + 1];
        const span = next.t - prev.t || 1;
        return { frame: next, prev, f: Math.min(1, Math.max(0, (tick - prev.t) / span)) };
    }

    function lerp(a, b, f) { return a + (b - a) * f; }

    function shortestAngle(a, b) {
        let d = b - a;
        while (d > Math.PI) d -= Math.PI * 2;
        while (d < -Math.PI) d += Math.PI * 2;
        return d;
    }

    function applyActorFrame(rec, actor, tick) {
        const root = rec.root;
        if (!root) return;
        const { prev, frame, f } = sampleFrame(actor.frames, tick);

        root.position.set(lerp(prev.p[0], frame.p[0], f), lerp(prev.p[1], frame.p[1], f), lerp(prev.p[2], frame.p[2], f));

        const yaw = prev.yaw + shortestAngle(prev.yaw, frame.yaw) * f;
        rec.yaw = yaw;
        root.rotation.y = yaw;

        const ja = prev.j || {}, jb = frame.j || {};
        for (const name in jb) {
            const joint = findJoint(root, name);
            if (!joint) continue;
            const va = ja[name] || jb[name];
            if (POS_ONLY_JOINTS.has(name)) {
                joint.position.set(lerp(va[0], jb[name][0], f), lerp(va[1], jb[name][1], f), lerp(va[2], jb[name][2], f));
            } else {
                const pitch = lerp(va[0], jb[name][0], f);
                const jyaw = va[1] + shortestAngle(va[1], jb[name][1]) * f;
                const roll = lerp(va[2], jb[name][2], f);
                joint.rotation.set(pitch, jyaw, roll);
            }
        }
    }

    function playbackLoop() {
        if (!state.playing || state.paused) return;
        const film = state.playFilm;
        if (!film) { stopPlayback(); return; }
        // sin mundo no hay playback zombie moviendo mallas huérfanas
        if (!getGame()) { stopPlayback(); despawnActors(); return; }

        const tick = state.playTickBase + (performance.now() - state.playStart) / TICK_MS;

        const endTick = state.playRange.to ?? film.durationTicks;
        const startTick = state.playRange.from ?? 0;

        if (tick >= endTick) {

            for (const actor of film.actors) {
                const rec = ensureActor(film, actor);
                if (rec) applyActorFrame(rec, actor, endTick);
            }
            stopPlayback();
            window.dispatchEvent(new CustomEvent('mf:film-ended', { detail: { atTick: Math.floor(endTick) } }));
            return;
        }

        for (const actor of film.actors) {
            const rec = ensureActor(film, actor);
            if (rec) applyActorFrame(rec, actor, tick);
        }

        const intTick = Math.floor(tick);
        if (window.MF_FaceSwap && intTick !== state.lastFaceTick) {
            state.lastFaceTick = intTick;
            try { window.MF_FaceSwap.onTick(intTick); } catch {}
        }

        state.playRaf = requestAnimationFrame(playbackLoop);
    }

    function setPlayRange(from, to) {
        if (from == null && to == null) { state.playRange = null; return { ok: true, range: null }; }
        state.playRange = {
            from: from != null ? Math.max(0, from) : 0,
            to: to != null ? Math.max(1, to) : null
        };
        return { ok: true, range: { ...state.playRange } };
    }
    function getPlayRange() { return state.playRange ? { ...state.playRange } : null; }

    function playFilm(name, range) {
        if (state.playing) stopPlayback();
        const films = loadFilms();
        const film = name
            ? films[name] || null
            : (state.frames.length ? currentTakeAsFilm(null) : null);
        if (!film) return { ok: false, error: 'take not found (record one or specify a name from /film list)' };
        if (!Array.isArray(film.actors) || !film.actors.length) return { ok: false, error: 'film is corrupt (no actors)' };

        let r = range || state.playRange;
        if (r && typeof r === 'object') {
            const from = Math.max(0, Math.min(r.from ?? 0, film.durationTicks - 1));
            const to = Math.max(from + 1, Math.min(r.to ?? film.durationTicks, film.durationTicks));
            r = { from, to };
        } else r = null;
        state.playRange = r;

        state.playing = true;
        state.paused = false;
        state.playFilm = film;
        state.playTickBase = r ? r.from : 0;
        state.playStart = performance.now();
        state.lastFaceTick = -1;

        try { window.MF_FaceSwap?.resetForPlayback?.(); } catch {}

        if (r && window.MF_FaceSwap?.skipBefore) {
            try { window.MF_FaceSwap.skipBefore(r.from); } catch {}
        }

        try { window.MF_Emotes?.stop?.(); } catch {}

        state.playRaf = requestAnimationFrame(playbackLoop);
        return { ok: true, name: film.name, ticks: film.durationTicks, actors: film.actors.length };
    }

    function playSequence(clips) {
        if (state.playing) stopPlayback();
        if (!Array.isArray(clips) || !clips.length) {
            return { ok: false, error: 'sequence is empty — drag takes to the timeline' };
        }
        const films = loadFilms();

        const items = [];
        for (const c of clips) {
            const film = films[c.filmName];
            // un clip cuyo film ya no existe se salta; uno corrupto también, no a matar el loop de rAF
            if (!film || !Array.isArray(film.actors)) continue;
            items.push({
                film,
                start: Math.max(0, c.start),
                duration: Math.max(1, Math.min(c.duration, film.durationTicks))
            });
        }
        if (!items.length) return { ok: false, error: 'no timeline clip exists in the library' };
        items.sort((a, b) => a.start - b.start);

        state.playing = true;
        state.paused = false;
        state.playMode = 'sequence';
        state.playSeq = items;
        state.playFilm = null;
        state.playTickBase = 0;
        state.playStart = performance.now();
        state.lastFaceTick = -1;

        try { window.MF_FaceSwap?.resetForPlayback?.(); } catch {}

        if (state.playRange?.from) {
            state.playTickBase = Math.min(state.playRange.from, seqTotalTicks(items) - 1);
            try { window.MF_FaceSwap?.skipBefore?.(state.playTickBase); } catch {}
        }

        try { window.MF_Emotes?.stop?.(); } catch {}
        state.playRaf = requestAnimationFrame(sequenceLoop);
        return { ok: true, clips: items.length, ticks: seqTotalTicks(items) };
    }

    function seqTotalTicks(items) {
        return items.reduce((m, c) => Math.max(m, c.start + c.duration), 0);
    }

    function sequenceLoop() {
        if (!state.playing || state.paused || state.playMode !== 'sequence') return;
        const items = state.playSeq;
        if (!items?.length) { stopPlayback(); return; }
        if (!getGame()) { stopPlayback(); despawnActors(); return; }

        let tick = state.playTickBase + (performance.now() - state.playStart) / TICK_MS;
        const total = seqTotalTicks(items);
        const endTick = state.playRange?.to ?? total;

        if (tick >= endTick) {

            applySeqFrame(items, endTick);
            stopPlayback();
            window.dispatchEvent(new CustomEvent('mf:film-ended', { detail: { atTick: Math.floor(endTick) } }));
            return;
        }

        applySeqFrame(items, tick);

        const intTick = Math.floor(tick);
        if (window.MF_FaceSwap && intTick !== state.lastFaceTick) {
            state.lastFaceTick = intTick;
            try { window.MF_FaceSwap.onTick(intTick); } catch {}
        }

        state.playRaf = requestAnimationFrame(sequenceLoop);
    }

    function applySeqFrame(items, tick) {
        for (const it of items) {
            const localTick = tick - it.start;
            const active = localTick >= 0 && localTick < it.duration;
            if (!active) continue;
            for (const actor of it.film.actors) {
                const rec = ensureActor(it.film, actor);
                if (rec) applyActorFrame(rec, actor, localTick);
            }
        }
    }

    function pausePlayback() {
        if (!state.playing || state.paused) return { ok: false, error: 'not playing' };
        state.paused = true;
        state.playTickBase += (performance.now() - state.playStart) / TICK_MS;
        cancelAnimationFrame(state.playRaf);
        return { ok: true, atTick: Math.floor(state.playTickBase) };
    }

    function resumePlayback() {
        if (!state.playing || !state.paused) return { ok: false, error: 'not paused' };
        state.paused = false;
        state.playStart = performance.now();

        state.playRaf = requestAnimationFrame(state.playMode === 'sequence' ? sequenceLoop : playbackLoop);
        return { ok: true };
    }

    function stopPlayback() {
        if (state.playRaf) cancelAnimationFrame(state.playRaf);
        state.playRaf = null;
        state.playing = false;
        state.paused = false;
        state.playMode = 'film';
        state.playFilm = null;
        state.playSeq = null;
        return { ok: true };
    }

    function despawnActors() {
        for (const actorId of [...state.actors.keys()]) despawnOne(actorId);
        state.actors.clear();
        return { ok: true };
    }

    function diag() {
        const game = getGame();
        const ent = getLocalPlayerEntity(game);
        const mesh = ent?.mesh;
        const joints = {};
        if (mesh) for (const n of JOINT_NAMES) joints[n] = !!findJoint(mesh, n);
        return {
            game: !!game, playerEntity: !!ent, mesh: !!mesh,
            joints,
            recording: state.recording,
            framesInMemory: state.frames.length,
            playing: state.playing, paused: state.paused,
            actorsSpawned: state.actors.size,
            savedFilms: Object.keys(loadFilms()).length
        };
    }

    window.MF_Film = {
        startRecording, stopRecording,
        saveFilm, deleteFilm, exportFilm, importFilm,
        playFilm, playSequence, pausePlayback, resumePlayback, stopPlayback,
        setPlayRange, getPlayRange, despawnActors,
        diag,
        listFilms() { return Object.keys(loadFilms()); },
        getFilm(name) { const f = loadFilms(); return f[name] || null; },
        get status() {
            return {
                recording: state.recording,
                playing: state.playing,
                paused: state.paused,
                // en pausa el reloj está congelado: playStart es viejo, sumarlo avanzaría el tick sin reproducir
                tick: state.playing ? Math.floor(state.playTickBase + (state.paused ? 0 : (performance.now() - state.playStart) / TICK_MS)) : null,
                frames: state.frames.length,
                actors: state.actors.size
            };
        }
    };
    window.__MF_Film = true;

    document.addEventListener('minifeather:film-config', (e) => {
        try {
            const cfg = JSON.parse(e.detail);
            if (cfg.action === 'stopPlayback') stopPlayback();
            if (cfg.action === 'despawnActors') despawnActors();
        } catch {}
    }, true);

    document.addEventListener('minifeather:film-state-request', () => {
        try {
            document.dispatchEvent(new CustomEvent('minifeather:film-state', {
                detail: JSON.stringify(window.MF_Film.status)
            }));
        } catch {}
    }, true);

    void 0;
})();

//# sourceURL=MF:src/Studio/MF_Film.js

/* ==== mf module: src/Studio/MF_FilmCamera.js ==== */

(function () {
    'use strict';
    if (window.__MF_FILMCAMERA__) return;
    window.__MF_FILMCAMERA__ = true;

    const TAG = 'minifeather filmcamera';
    const TPS = 20;
    const LS_KEY = 'minifeather_filmcamera_v1';

    const state = {
        clips: [],
        selectedId: null,

        audioEls: new Map(),

        subtitle: null,

    };

    function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
    function lerp(a, b, t) { return a + (b - a) * t; }
    function hermite(t) { return t * t * (3 - 2 * t); }
    function shortestAngle(a, b) {
        let d = (b - a) % (Math.PI * 2);
        if (d > Math.PI) d -= Math.PI * 2;
        if (d < -Math.PI) d += Math.PI * 2;
        return d;
    }
    function ease(kind, t) {
        t = clamp(t, 0, 1);
        switch (kind) {
            case 'linear': return t;
            case 'step': return t < 1 ? 0 : 1;
            case 'easeIn': return t * t;
            case 'easeOut': return 1 - (1 - t) * (1 - t);
            default: return hermite(t);
        }
    }

    function envelope(c, local) {
        const fi = Number(c.env?.fi) || 0, fo = Number(c.env?.fo) || 0;
        if (fi > 0 && local < fi) return clamp(local / fi, 0, 1);
        if (fo > 0 && local > c.duration - fo) return clamp((c.duration - local) / fo, 0, 1);
        return 1;
    }
    const uid = () => 'cam-' + Math.random().toString(36).slice(2, 8);
    function clone(o) { return JSON.parse(JSON.stringify(o ?? {})); }

    const TYPES = {
        idle: {
            label: 'Fijo', icon: '🎥', overwrite: true, layer: 0,
            defaults: { pose: { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, fov: 0 } },
        },
        keyframe: {
            label: 'Keyframes', icon: '🔡', overwrite: true, layer: 1,
            defaults: { keys: [{ t: 0, x: 0, y: 0, z: 0, yaw: 0, pitch: 0, roll: 0, fov: 0 },
                              { t: 20, x: 0, y: 0, z: 2, yaw: 0.5, pitch: 0, roll: 0, fov: 0 }], interp: 'ease' },
        },
        path: {
            label: 'Ruta', icon: '🛣️', overwrite: true, layer: 1,
            defaults: { points: [{ t: 0, x: 0, y: 0, z: 0, yaw: 0, pitch: 0, fov: 0 },
                                 { t: 40, x: 4, y: 0, z: 0, yaw: 1.2, pitch: 0, fov: 0 }], interp: 'hermite' },
        },
        dolly: {
            label: 'Dolly', icon: '🎯', overwrite: true, layer: 0,
            defaults: { pose: { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, fov: 0 }, distance: 6, ease: 'ease' },
        },
        orbit: {
            label: 'Órbita', icon: '🪐', overwrite: true, layer: 1,
            defaults: { target: { x: 0, y: 0, z: 0 }, distance: 8, from: 0, to: 360, height: 2, pitch: 0.3, fov: 0, ease: 'ease' },
        },
        look: {
            label: 'Mirar a', icon: '👁️', overwrite: false, layer: 3,
            defaults: { target: { x: 0, y: 0, z: 0 }, keepPos: true },
        },
        shake: {
            label: 'Shake', icon: '🌀', overwrite: false, layer: 4,
            defaults: { freq: 2, amount: 0.4, mask: { x: false, y: false, z: false, yaw: true, pitch: true, roll: false, fov: false } },
        },
        translate: {
            label: 'Offset', icon: '↔️', overwrite: false, layer: 5,
            defaults: { offset: { x: 0, y: 0, z: 0 }, addYaw: 0, addPitch: 0 },
        },
        subtitle: {
            label: 'Subtitle', icon: '💬', overwrite: false, layer: 9,
            defaults: { text: 'Text…', size: 20, x: 0.5, y: 0.85, color: '#ffffff', background: true },
        },
        audio: {
            label: 'Audio', icon: '🔊', overwrite: false, layer: 10,
            defaults: { src: '', volume: 1, offset: 0 },
        },
    };

    function loadClips() {
        try {
            const raw = localStorage.getItem(LS_KEY);
            if (!raw) return [];
            const data = JSON.parse(raw);
            if (!Array.isArray(data?.clips)) return [];
            const out = [];
            for (const c of data.clips) {
                const T = TYPES[c?.type];
                if (!T) continue;
                // evalClip hace p.pose.x sin preguntar: un clip guardado sin props (o a medias) revienta el uiLoop del studio
                c.props = { ...clone(T.defaults), ...(c.props && typeof c.props === 'object' ? c.props : null) };
                out.push(c);
            }
            return out;
        } catch (e) { console.warn(TAG, 'loadClips:', e?.message || e); return []; }
    }
    function saveClips() {
        try {
            localStorage.setItem(LS_KEY, JSON.stringify({ version: 1, clips: state.clips }));
        } catch (e) { console.warn(TAG, 'saveClips (full?):', e?.message || e); }
    }
    state.clips = loadClips();

    function addClip(spec) {
        const type = String(spec?.type || 'idle');
        const T = TYPES[type];
        if (!T) throw new Error('tipo de clip desconocido: ' + type);
        const c = {
            id: uid(),
            type,
            title: spec.title || T.label,
            start: Math.max(0, Math.round(Number(spec.start) || 0)),
            duration: Math.max(1, Math.round(Number(spec.duration) || TPS)),
            enabled: spec.enabled !== false,
            layer: spec.layer != null ? Number(spec.layer) : T.layer,
            env: { fi: Math.max(0, Math.round(Number(spec.fadeIn) || 0)),
                   fo: Math.max(0, Math.round(Number(spec.fadeOut) || 0)) },
            props: clone(T.defaults),
        };
        if (spec.props) c.props = { ...c.props, ...clone(spec.props) };
        state.clips.push(c);
        saveClips();
        return c;
    }
    function removeClip(id) {
        const i = state.clips.findIndex(c => c.id === id);
        if (i === -1) return false;
        stopAudioFor(state.clips[i]);
        state.clips.splice(i, 1);
        if (state.selectedId === id) state.selectedId = null;
        saveClips();
        return true;
    }
    function updateClip(id, patch) {
        const c = state.clips.find(x => x.id === id);
        if (!c) return null;
        if (patch.start != null) c.start = Math.max(0, Math.round(patch.start));
        if (patch.duration != null) c.duration = Math.max(1, Math.round(patch.duration));
        if (patch.enabled != null) c.enabled = !!patch.enabled;
        if (patch.title != null) c.title = String(patch.title);
        if (patch.layer != null) c.layer = Math.max(0, Math.round(patch.layer));
        if (patch.fadeIn != null) c.env.fi = Math.max(0, Math.round(patch.fadeIn));
        if (patch.fadeOut != null) c.env.fo = Math.max(0, Math.round(patch.fadeOut));
        if (patch.props) c.props = { ...c.props, ...clone(patch.props) };
        saveClips();
        return c;
    }
    function getClip(id) { return state.clips.find(c => c.id === id) || null; }
    function clearAll() {
        for (const c of [...state.clips]) stopAudioFor(c);
        state.clips = [];
        state.selectedId = null;
        saveClips();
    }
    const byLayer = () => [...state.clips].sort((a, b) => (a.layer - b.layer) || (a.start - b.start));

    function studioPose() {

        const S = window.MF_Studio;
        const pose = S?.getStudioCamPose?.();
        if (pose) return pose;
        try {
            const g = window.__MINIBLOX_GAME__ || window.miniblox;
            const cam = g?.gameScene?.camera || g?.camera;
            if (cam) {
                const p = cam.position;
                return { x: p.x, y: p.y, z: p.z, yaw: cam.rotation?.y || 0, pitch: cam.rotation?.x || 0, fov: cam.fov || 0 };
            }
        } catch {}
        return { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, fov: 0 };
    }

    function addFromStudio(type, opts = {}) {
        const pose = studioPose();
        const c = addClip({ type, start: opts.start ?? 0, duration: opts.duration ?? TPS, title: opts.title });
        if (type === 'idle' || type === 'dolly') {
            c.props.pose = { ...pose };
        } else if (type === 'keyframe') {
            c.props.keys = [{ t: 0, ...pose, roll: 0 },
                            { t: c.duration, x: pose.x, y: pose.y, z: pose.z + 2, yaw: pose.yaw, pitch: pose.pitch, roll: 0, fov: pose.fov }];
        } else if (type === 'path') {
            c.props.points = [{ t: 0, ...pose },
                              { t: c.duration, x: pose.x + 4, y: pose.y, z: pose.z, yaw: pose.yaw, pitch: pose.pitch, fov: pose.fov }];
        } else if (type === 'orbit' || type === 'look') {

            const fx = pose.x - Math.sin(pose.yaw) * 4, fz = pose.z - Math.cos(pose.yaw) * 4;
            if (type === 'orbit') c.props.target = { x: fx, y: pose.y - 1, z: fz };
            else c.props.target = { x: fx, y: pose.y, z: fz };
        }
        saveClips();
        return c;
    }

    function addKeyAt(clipId, localTick) {
        const c = getClip(clipId);
        if (!c) return null;
        const pose = studioPose();
        if (c.type === 'keyframe') {
            c.props.keys.push({ t: Math.max(0, Math.round(localTick)), x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw, pitch: pose.pitch, roll: 0, fov: pose.fov });
            c.props.keys.sort((a, b) => a.t - b.t);
        } else if (c.type === 'path') {
            c.props.points.push({ t: Math.max(0, Math.round(localTick)), x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw, pitch: pose.pitch, fov: pose.fov });
            c.props.points.sort((a, b) => a.t - b.t);
        } else return null;
        saveClips();
        return c;
    }

    function evalClip(c, local, out) {
        const p = c.props;
        switch (c.type) {
            case 'idle': {
                out.x = p.pose.x; out.y = p.pose.y; out.z = p.pose.z;
                out.yaw = p.pose.yaw; out.pitch = p.pose.pitch;
                if (p.pose.fov) out.fov = p.pose.fov;
                break;
            }
            case 'dolly': {
                const t = ease(p.ease, clamp(local / Math.max(1, c.duration), 0, 1));
                const d = Number(p.distance) || 0;
                out.x = p.pose.x - Math.sin(p.pose.yaw) * d * t;
                out.y = p.pose.y - Math.tan(p.pose.pitch || 0) * d * t * 0 + p.pose.y * 0;
                out.z = p.pose.z - Math.cos(p.pose.yaw) * d * t;
                out.yaw = p.pose.yaw; out.pitch = p.pose.pitch;
                if (p.pose.fov) out.fov = p.pose.fov;
                break;
            }
            case 'keyframe': {
                const r = sampleKeys(p.keys, local, p.interp);
                Object.assign(out, r);
                break;
            }
            case 'path': {
                const r = samplePoints(p.points, local, p.interp);
                Object.assign(out, r);
                break;
            }
            case 'orbit': {
                const t = ease(p.ease, clamp(local / Math.max(1, c.duration), 0, 1));
                const a0 = deg(p.from), a1 = deg(p.to);
                const ang = a0 + (a1 - a0) * t;
                const d = Number(p.distance) || 8, h = Number(p.height) || 0;
                out.x = p.target.x + Math.sin(ang) * d;
                out.z = p.target.z + Math.cos(ang) * d;
                out.y = p.target.y + h;

                const dx = p.target.x - out.x, dz = p.target.z - out.z, dy = p.target.y - out.y;
                out.yaw = Math.atan2(-dx, -dz);
                out.pitch = Math.atan2(dy, Math.hypot(dx, dz));
                if (p.fov) out.fov = p.fov;
                break;
            }
            case 'look': {
                if (!out.hasPos) break;
                const dx = p.target.x - out.x, dy = p.target.y - out.y, dz = p.target.z - out.z;
                out.yaw = Math.atan2(-dx, -dz);
                out.pitch = Math.atan2(dy, Math.hypot(dx, dz));
                break;
            }
            case 'shake': {
                const m = p.mask || {};
                const f = Number(p.freq) || 2, a = Number(p.amount) || 0.3;
                const s = Math.sin, cs = Math.cos, tt = local / TPS;
                if (m.x) out.x += s(tt * f * Math.PI * 2) * a;
                if (m.y) out.y += cs(tt * f * Math.PI * 2) * a;
                if (m.z) out.z += s(tt * f * Math.PI * 2 + 2.1) * a;
                if (m.yaw) out.yaw += s(tt * f * Math.PI * 2) * a * 0.5;
                if (m.pitch) out.pitch += cs(tt * f * Math.PI * 2) * a * 0.5;
                if (m.roll) out.roll += s(tt * f * Math.PI * 2 + 1.3) * a * 0.5;
                if (m.fov) out.fov = (out.fov || 0) + s(tt * f * Math.PI * 2) * a;
                break;
            }
            case 'translate': {
                out.x += Number(p.offset?.x) || 0;
                out.y += Number(p.offset?.y) || 0;
                out.z += Number(p.offset?.z) || 0;
                out.yaw += Number(p.addYaw) || 0;
                out.pitch += Number(p.addPitch) || 0;
                break;
            }
        }
    }
    const deg = d => (Number(d) || 0) * Math.PI / 180;

    function sampleKeys(keys, local, interp) {
        const out = {};
        if (!keys?.length) return out;
        const ks = keys;
        if (local <= ks[0].t) return { ...ks[0] };
        const last = ks[ks.length - 1];
        if (local >= last.t) {
            const { t, ...v } = last; return v;
        }
        let i = 0;
        while (i < ks.length - 1 && ks[i + 1].t <= local) i++;
        const a = ks[i], b = ks[i + 1];
        const raw = (local - a.t) / Math.max(1, b.t - a.t);
        const t = interp === 'linear' ? raw : ease(interp, raw);
        for (const ch of ['x', 'y', 'z', 'roll', 'fov']) out[ch] = lerp(a[ch] || 0, b[ch] || 0, t);
        out.yaw = a.yaw + shortestAngle(a.yaw || 0, b.yaw || 0) * t;
        out.pitch = lerp(a.pitch || 0, b.pitch || 0, t);
        return out;
    }
    function samplePoints(pts, local, interp) {
        const out = {};
        if (!pts?.length) return out;
        if (local <= pts[0].t) { const { t, ...v } = pts[0]; return v; }
        const last = pts[pts.length - 1];
        if (local >= last.t) { const { t, ...v } = last; return v; }
        let i = 0;
        while (i < pts.length - 1 && pts[i + 1].t <= local) i++;
        const a = pts[i], b = pts[i + 1];
        const raw = (local - a.t) / Math.max(1, b.t - a.t);
        const t = interp === 'linear' ? raw : ease(interp, raw);
        for (const ch of ['x', 'y', 'z', 'fov']) out[ch] = lerp(a[ch] || 0, b[ch] || 0, t);
        out.yaw = a.yaw + shortestAngle(a.yaw || 0, b.yaw || 0) * t;
        out.pitch = lerp(a.pitch || 0, b.pitch || 0, t);
        return out;
    }

    function evalLayered(tick) {
        let out = null;
        for (const c of byLayer()) {
            if (!c.enabled) continue;
            const local = tick - c.start;
            if (local < 0 || local >= c.duration) continue;
            if (c.type === 'subtitle' || c.type === 'audio') continue;
            if (TYPES[c.type]?.overwrite) {

                if (!out) out = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, roll: 0, fov: 0, hasPos: true };
                const cur = { ...out };
                evalClip(c, local, cur);

                const e = envelope(c, local);
                if (e >= 1) Object.assign(out, cur);
                else {

                    for (const k of ['x', 'y', 'z', 'yaw', 'pitch', 'roll', 'fov']) {
                        out[k] = lerp(out[k] || 0, cur[k] || 0, e);
                    }
                }
            } else if (out) {
                const cur = { ...out };
                evalClip(c, local, cur);
                Object.assign(out, cur);
            }
        }
        return out;
    }

    function evalSubtitles(tick) {
        let best = null;
        for (const c of state.clips) {
            if (c.type !== 'subtitle' || !c.enabled) continue;
            const local = tick - c.start;
            if (local < 0 || local >= c.duration) continue;
            const alpha = envelope(c, local);
            if (!best || alpha > best.alpha) best = { ...c.props, alpha, title: c.title, id: c.id };
        }
        state.subtitle = best;
        return best;
    }

    function stopAudioFor(c) {
        const el = state.audioEls.get(c?.id);
        if (el) { try { el.pause(); el.currentTime = 0; } catch {} state.audioEls.delete(c.id); }
    }
    function evalAudio(tick, playing) {
        for (const c of state.clips) {
            if (c.type !== 'audio' || !c.enabled) continue;
            const local = tick - c.start;
            const inWindow = local >= 0 && local < c.duration;
            let el = state.audioEls.get(c.id);
            if (inWindow && playing) {
                if (!el && c.props.src) {
                    el = new Audio(c.props.src);
                    el.volume = clamp(Number(c.props.volume) || 1, 0, 1);
                    // el.duration es NaN hasta loadedmetadata: decidir el loop entonces, no aquí
                    el.addEventListener('loadedmetadata', () => { el.loop = c.duration / TPS > el.duration; });
                    state.audioEls.set(c.id, el);
                    const off = Number(c.props.offset) || 0;
                    try { if (off > 0) el.currentTime = off; } catch {}
                    // borrar el elemento al rechazar play() lo recreaba a 20 por segundo mientras siga fallando
                    el.play().catch(() => {});
                } else if (el && el.paused) el.play().catch(() => {});
            } else if (el && (!inWindow || !playing)) {
                if (!inWindow) stopAudioFor(c);
                else try { el.pause(); } catch {}
            }
        }
    }
    function stopAudio() { for (const c of [...state.clips]) stopAudioFor(c); }

    function onTick(tick, playing = true) {
        const pose = evalLayered(tick);
        evalSubtitles(tick);
        evalAudio(tick, playing);
        return pose;
    }

    function evalClipOnly(c, local) {
        if (!c || !TYPES[c.type]) return null;
        const cur = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, roll: 0, fov: 0, hasPos: false };
        try { evalClip(c, Math.max(0, Math.min(c.duration, local)), cur); } catch {}
        return cur;
    }
    function reset() {
        stopAudio();
        state.subtitle = null;
    }

    window.MF_FilmCamera = {
        TPS,
        TYPES,

        add: addClip,
        addFromStudio,
        addKeyAt,

        remove: removeClip,
        update: updateClip,
        get: getClip,
        clear: clearAll,
        byLayer,
        studioPose,

        evalLayered,

        evalClipOnly,

        evalSubtitles,
        onTick,

        reset,

        save: saveClips,
        select(id) { state.selectedId = id || null; },
        get clips() { return state.clips; },
        get selectedId() { return state.selectedId; },
        set selectedId(v) { state.selectedId = v; },
        get subtitle() { return state.subtitle; },
    };

    void 0;
})();

//# sourceURL=MF:src/Studio/MF_FilmCamera.js

/* ==== mf module: src/Studio/MF_Pose.js ==== */

(function () {
    'use strict';

    if (window.__MF_Pose) return;
    const TAG = 'minifeather pose';
    const LS_KEY = 'minifeather_poses_v1';

    const PARTS = {
        head:     { joints: ['headPivot'] },
        torso:    { joints: ['body'] },
        leftArm:  { joints: ['leftShoulderJoint', 'leftElbowJoint'] },
        rightArm: { joints: ['rightShoulderJoint', 'rightElbowJoint'] },
        leftLeg:  { joints: ['leftHipJoint', 'leftKneeJoint'] },
        rightLeg: { joints: ['rightHipJoint', 'rightKneeJoint'] }
    };
    const ALL_JOINTS = Object.values(PARTS).flatMap(p => p.joints);

    const state = {

        rest: null,

        restMesh: null,
        poses: null
    };

    function getGame() {
        if (globalThis.miniblox?.player) return globalThis.miniblox;
        try {
            const react = document.querySelector('#react');
            if (react) for (const root of Object.values(react)) {
                const g = root?.updateQueue?.baseState?.element?.props?.game;
                if (g?.player) return g;
            }
        } catch {}
        return null;
    }

    function getLocalPlayerEntity(game) {
        const me = game?.player;
        if (!me) return null;
        try { const e = game.world?.getPlayerById?.(me.id); if (e?.mesh) return e; } catch {}
        try { const e = game.world?.players?.get?.(me.id); if (e?.mesh) return e; } catch {}
        try { const e = game.world?.entities?.get?.(me.id); if (e?.mesh) return e; } catch {}
        try {
            const ents = game.world?.entities;
            if (ents?.values) for (const e of ents.values()) {
                if (e?.uuid === me.uuid || e?.id === me.id) return e;
            }
        } catch {}
        return me?.mesh ? me : null;
    }

    function findJoint(mesh, name) {
        if (!mesh) return null;
        if (mesh[name] && mesh[name].rotation) return mesh[name];
        const queue = [mesh];
        const seen = new WeakSet();
        let visited = 0;
        while (queue.length && visited < 500) {
            const obj = queue.shift();
            if (!obj || typeof obj !== 'object' || seen.has(obj)) continue;
            seen.add(obj);
            visited++;
            if (obj[name] && obj[name].rotation) return obj[name];
            if (Array.isArray(obj.children)) for (const c of obj.children) queue.push(c);
        }
        return null;
    }

    function getMesh() {
        return getLocalPlayerEntity(getGame())?.mesh || null;
    }

    function captureRest() {
        const mesh = getMesh();
        if (!mesh) return null;
        const rest = {};
        for (const name of ALL_JOINTS) {
            const j = findJoint(mesh, name);
            if (j) rest[name] = {
                x: j.rotation.x, y: j.rotation.y, z: j.rotation.z,
                sx: j.scale.x, sy: j.scale.y, sz: j.scale.z,
                px: j.position.x, py: j.position.y, pz: j.position.z
            };
        }
        state.rest = rest;
        state.restMesh = mesh;
        return rest;
    }

    function ensureRest() {
        // el rest es del mesh que lo capturó: tras un respawn o recreate el
        // objeto es otro y el rest viejo vale para restaurar un fantasma
        if (!state.rest || state.restMesh !== getMesh()) captureRest();
        return state.rest;
    }

    function deg2rad(d) { return (Array.isArray(d) ? d : [d]).map(v => v * Math.PI / 180); }

    function setPart(part, angles) {
        const def = PARTS[part];
        if (!def) throw new Error('parte desconocida: ' + part + ' (usa: ' + Object.keys(PARTS).join(', ') + ')');
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador/mesh no disponible');
        ensureRest();

        const joints = def.joints.map(n => findJoint(mesh, n));
        if (!joints[0]) throw new Error('joint "' + def.joints[0] + '" no encontrado en el mesh');

        const rad = {
            x: (angles.pitch || 0) * Math.PI / 180,
            y: (angles.yaw || 0) * Math.PI / 180,
            z: (angles.roll || 0) * Math.PI / 180
        };

        joints[0].rotation.set(rad.x, rad.y, rad.z);

        if (joints[1] && angles.bend != null) {
            joints[1].rotation.set((angles.bend || 0) * Math.PI / 180, 0, 0);
        }
        return { ok: true, part, applied: angles };
    }

    function getPose() {
        const mesh = getMesh();
        if (!mesh) return null;
        const pose = {};
        for (const part in PARTS) {
            const j = findJoint(mesh, PARTS[part].joints[0]);
            if (j) pose[part] = [j.rotation.x, j.rotation.y, j.rotation.z];
        }
        return pose;
    }

    function applyPoseObj(pose) {
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador/mesh no disponible');
        for (const part in pose) {
            const def = PARTS[part];
            if (!def) continue;
            // pose remota por p2p: un dato malformado no debe meter NaN en la
            // articulación y fundir el rig en silencio
            const v = pose[part];
            if (!Array.isArray(v) || v.length < 3) continue;
            const rx = +v[0], ry = +v[1], rz = +v[2];
            if (!Number.isFinite(rx) || !Number.isFinite(ry) || !Number.isFinite(rz)) continue;
            const j = findJoint(mesh, def.joints[0]);
            if (j) j.rotation.set(rx, ry, rz);
        }
        return { ok: true };
    }

    function reset() {
        const rest = ensureRest();
        const mesh = getMesh();
        if (!mesh || !rest) return { ok: false, error: 'sin rest capturado' };
        for (const name in rest) {
            const j = findJoint(mesh, name);
            if (!j) continue;
            j.rotation.set(rest[name].x, rest[name].y, rest[name].z);
            if (rest[name].sx != null) j.scale.set(rest[name].sx, rest[name].sy, rest[name].sz);
            if (rest[name].px != null) j.position.set(rest[name].px, rest[name].py, rest[name].pz);
        }
        return { ok: true };
    }

    function loadPoses() {
        if (state.poses) return state.poses;
        try { state.poses = JSON.parse(localStorage.getItem(LS_KEY) || '{}'); } catch { state.poses = {}; }
        return state.poses;
    }

    function save(name) {
        const pose = getPose();
        if (!pose) return { ok: false, error: 'player/mesh not available' };
        const poses = loadPoses();
        poses[name] = pose;
        state.poses = poses;
        try {
            localStorage.setItem(LS_KEY, JSON.stringify(poses));
            return { ok: true, name };
        } catch (e) {
            return { ok: false, error: 'could not save: ' + (e?.message || e) };
        }
    }

    function apply(name) {
        const poses = loadPoses();
        if (!(name in poses)) return { ok: false, error: 'pose "' + name + '" no existe (ver list())' };
        return applyPoseObj(poses[name]);
    }

    function remove(name) {
        const poses = loadPoses();
        if (!(name in poses)) return { ok: false, error: 'pose "' + name + '" no existe' };
        delete poses[name];
        state.poses = poses;
        try { localStorage.setItem(LS_KEY, JSON.stringify(poses)); } catch {}
        return { ok: true };
    }

    const PRESETS = {
        'tpose': { leftArm: { pitch: 0, roll: 90 }, rightArm: { pitch: 0, roll: -90 } },
        'wave-ready': { rightArm: { pitch: -170, roll: 20, bend: 30 } },
        'point-forward': { rightArm: { pitch: -90 } },
        'salute': { rightArm: { pitch: -150, roll: 25, bend: 100 } },
        'sit': { leftLeg: { pitch: -90, bend: 90 }, rightLeg: { pitch: -90, bend: 90 } },
        'hero': { leftArm: { pitch: -160, roll: 15 }, rightArm: { pitch: -160, roll: -15 }, head: { pitch: 8 } }
    };

    function applyPreset(name) {
        const p = PRESETS[name];
        if (!p) return { ok: false, error: 'preset "' + name + '" does not exist: ' + Object.keys(PRESETS).join(', ') };
        reset();
        // un rig con pivots de menos no debe tumbar el preset entero a medias:
        // se aplica lo que se pueda y se cuenta lo que no
        const failed = [];
        for (const part in p) {
            try { setPart(part, p[part]); } catch { failed.push(part); }
        }
        if (failed.length) return { ok: false, error: 'joints no encontrados: ' + failed.join(', '), preset: name };
        return { ok: true, preset: name };
    }

    function getV3(camera) {
        try { return camera?.position?.constructor || null; } catch { return null; }
    }

    function getCamera() {
        const g = getGame();
        return g?.gameScene?.camera || g?.camera || window.MF_FREECAM?.camera || null;
    }

    function getGameCanvas() {
        const g = getGame();
        const c = g?.gameScene?.renderer?.domElement || g?.renderer?.domElement;
        if (c) return c;
        let best = null;
        try {
            for (const cv of document.querySelectorAll('canvas')) {
                if (!best || cv.width * cv.height > best.width * best.height) best = cv;
            }
        } catch {}
        return best;
    }

    const PART_RADIUS = {
        head: 0.32, torso: 0.38,
        leftArm: 0.42, rightArm: 0.42,
        leftLeg: 0.42, rightLeg: 0.42
    };

    function rayTri(orig, dir, v0, v1, v2) {
        const e1x = v1.x - v0.x, e1y = v1.y - v0.y, e1z = v1.z - v0.z;
        const e2x = v2.x - v0.x, e2y = v2.y - v0.y, e2z = v2.z - v0.z;
        const px = dir.y * e2z - dir.z * e2y;
        const py = dir.z * e2x - dir.x * e2z;
        const pz = dir.x * e2y - dir.y * e2x;
        const det = e1x * px + e1y * py + e1z * pz;
        if (det > -1e-9 && det < 1e-9) return null;
        const inv = 1 / det;
        const tx = orig.x - v0.x, ty = orig.y - v0.y, tz = orig.z - v0.z;
        const u = (tx * px + ty * py + tz * pz) * inv;
        if (u < -1e-6 || u > 1 + 1e-6) return null;
        const qx = ty * e1z - tz * e1y;
        const qy = tz * e1x - tx * e1z;
        const qz = tx * e1y - ty * e1x;
        const v = (dir.x * qx + dir.y * qy + dir.z * qz) * inv;
        if (v < -1e-6 || u + v > 1 + 1e-6) return null;
        const t = (e2x * qx + e2y * qy + e2z * qz) * inv;
        return t > 1e-6 ? t : null;
    }

    function pickPart(clientX, clientY) {
        const ent = getLocalPlayerEntity(getGame());
        const mesh = ent?.mesh;
        const camera = getCamera();
        const V3 = getV3(camera);
        if (!mesh || !camera || !V3) return null;

        const rect = (getGameCanvas() || document.body).getBoundingClientRect();
        const ndcX = ((clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
        const ndcY = -((clientY - rect.top) / Math.max(1, rect.height)) * 2 + 1;

        let origin, dir;
        try {
            camera.updateMatrixWorld?.();
            origin = new V3().setFromMatrixPosition(camera.matrixWorld);
            dir = new V3(ndcX, ndcY, 0.5).unproject(camera).sub(origin).normalize();
            if (!Number.isFinite(dir.x) || dir.lengthSq() === 0) return null;
        } catch { return null; }

        try { mesh.updateMatrixWorld(true); } catch {}

        const jointToPart = {};
        for (const part in PARTS) for (const j of PARTS[part].joints) jointToPart[j] = part;

        const meshes = [];
        mesh.traverse(o => { if (o?.isMesh && o.geometry) meshes.push(o); });
        if (!meshes.length) return null;

        let best = null;
        const vA = new V3(), vB = new V3(), vC = new V3();
        for (const m of meshes) {
            const geo = m.geometry;
            const posAttr = geo?.attributes?.position;
            if (!posAttr) continue;
            let index = geo.index?.array || null;
            const count = posAttr.count;

            let ownerPart = null, ownerJoint = null;
            let node = m;
            while (node && node !== mesh.parent) {
                if (node.name && jointToPart[node.name]) { ownerPart = jointToPart[node.name]; ownerJoint = node.name; break; }
                node = node.parent;
            }

            let mw = null;
            try { m.updateMatrixWorld?.(true); mw = m.matrixWorld; } catch {}
            if (!mw) continue;
            const e = mw.elements;

            const worldOf = (i, out) => {
                const x = posAttr.getX(i), y = posAttr.getY(i), z = posAttr.getZ(i);

                out.x = e[0] * x + e[4] * y + e[8] * z + e[12];
                out.y = e[1] * x + e[5] * y + e[9] * z + e[13];
                out.z = e[2] * x + e[6] * y + e[10] * z + e[14];
            };

            const triCount = index ? index.length / 3 : count / 3;
            for (let ti = 0; ti < triCount; ti++) {
                let i0, i1, i2;
                if (index) { i0 = index[ti * 3]; i1 = index[ti * 3 + 1]; i2 = index[ti * 3 + 2]; }
                else { i0 = ti * 3; i1 = ti * 3 + 1; i2 = ti * 3 + 2; }
                worldOf(i0, vA); worldOf(i1, vB); worldOf(i2, vC);
                const t = rayTri(origin, dir, vA, vB, vC);
                if (t == null) continue;
                if (!best || t < best.t) best = { t, part: ownerPart, obj: m, jointName: ownerJoint };
            }
        }
        if (!best || !best.part) {

            return pickByProximity(mesh, origin, dir, V3);
        }
        const point = new V3().copy(dir).multiplyScalar(best.t).add(origin);
        return { part: best.part, jointName: best.jointName, object: best.obj, hit: { point } };
    }

    function pickByProximity(mesh, origin, dir, V3) {
        let best = null;
        const wp = new V3(), tmp = new V3();
        for (const part in PARTS) {
            const j = findJoint(mesh, PARTS[part].joints[0]);
            if (!j) continue;
            try { j.getWorldPosition(wp); } catch { continue; }
            tmp.copy(wp).sub(origin);
            const t = tmp.dot(dir);
            if (t < 0.05) continue;
            const d = tmp.copy(wp).sub(new V3().copy(dir).multiplyScalar(t).add(origin)).length();
            const r = PART_RADIUS[part] || 0.4;
            const score = d - r;
            if (score < 0 && (!best || score < best.score)) {
                best = { score, part, jointName: PARTS[part].joints[0], joint: j, point: wp.clone() };
            }
        }
        if (!best) return null;

        let obj = null, bestD = Infinity;
        const probe = new V3();
        mesh.traverse(o => {
            if (!o?.isMesh || !o.geometry) return;
            try {
                o.getWorldPosition(probe);
                const dd = probe.distanceTo(best.point);
                if (dd < bestD) { bestD = dd; obj = o; }
            } catch {}
        });
        return { part: best.part, jointName: best.jointName, object: obj || mesh, hit: { point: best.point } };
    }

    function getScale(part) {
        const def = PARTS[part];
        if (!def) throw new Error('parte desconocida: ' + part);
        const mesh = getMesh();
        if (!mesh) return null;
        const j = findJoint(mesh, def.joints[0]);
        return j ? { x: j.scale.x, y: j.scale.y, z: j.scale.z } : null;
    }

    function setScale(part, s) {
        const def = PARTS[part];
        if (!def) throw new Error('parte desconocida: ' + part + ' (usa: ' + Object.keys(PARTS).join(', ') + ')');
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador/mesh no disponible');
        const j = findJoint(mesh, def.joints[0]);
        if (!j) throw new Error('joint "' + def.joints[0] + '" no encontrado');
        const clampS = (v) => Math.min(3, Math.max(0.1, v));
        const cur = { x: j.scale.x, y: j.scale.y, z: j.scale.z };
        const nx = s.uniform != null ? clampS(s.uniform) : (s.x != null ? clampS(s.x) : cur.x);
        const ny = s.uniform != null ? clampS(s.uniform) : (s.y != null ? clampS(s.y) : cur.y);
        const nz = s.uniform != null ? clampS(s.uniform) : (s.z != null ? clampS(s.z) : cur.z);
        j.scale.set(nx, ny, nz);
        return { ok: true, part, scale: { x: nx, y: ny, z: nz } };
    }

    function getOffset(part) {
        const def = PARTS[part];
        if (!def) throw new Error('parte desconocida: ' + part);
        const mesh = getMesh();
        if (!mesh) return null;
        const j = findJoint(mesh, def.joints[0]);
        if (!j) return null;
        const rest = ensureRest();
        const r = rest?.[def.joints[0]];
        if (!r) return { x: 0, y: 0, z: 0 };
        return { x: j.position.x - r.px, y: j.position.y - r.py, z: j.position.z - r.pz };
    }

    function setOffset(part, off) {
        const def = PARTS[part];
        if (!def) throw new Error('parte desconocida: ' + part + ' (usa: ' + Object.keys(PARTS).join(', ') + ')');
        const mesh = getMesh();
        if (!mesh) throw new Error('jugador/mesh no disponible');
        const j = findJoint(mesh, def.joints[0]);
        if (!j) throw new Error('joint "' + def.joints[0] + '" no encontrado');
        const rest = ensureRest();
        const r = rest?.[def.joints[0]] || { px: 0, py: 0, pz: 0 };
        const clampO = (v) => Math.min(2, Math.max(-2, v));
        const nx = r.px + (off.x != null ? clampO(off.x) : j.position.x - r.px);
        const ny = r.py + (off.y != null ? clampO(off.y) : j.position.y - r.py);
        const nz = r.pz + (off.z != null ? clampO(off.z) : j.position.z - r.pz);
        j.position.set(nx, ny, nz);
        return { ok: true, part, offset: { x: nx - r.px, y: ny - r.py, z: nz - r.pz } };
    }

    const rotDrags = new Map();
    let rotDragSeq = 0;

    function qInv(q) {
        try { return q.invert(); } catch { return q.conjugate(); }
    }

    function reflectAxis(a, n) {
        if (!n) return a;
        const d = 2 * (a.x * n.x + a.y * n.y + a.z * n.z);
        return a.clone().addScaledVector(n, -d);
    }

    function beginRotateWorld(part, camera) {
        const def = PARTS[part];
        if (!def) return null;
        const mesh = getMesh();
        if (!mesh) return null;
        const j = findJoint(mesh, def.joints[0]);
        if (!j?.quaternion) return null;
        try {
            const Q = j.quaternion.constructor;
            const st = {
                part, joint: j, Q,
                camera: camera || getCamera(),
                qStartWorld: new Q(),
                qParentWorldInv: new Q()
            };
            j.getWorldQuaternion(st.qStartWorld);
            if (j.parent?.quaternion) j.parent.getWorldQuaternion(st.qParentWorldInv);
            qInv(st.qParentWorldInv);

            try {
                mesh.updateMatrixWorld?.(true);
                const V3 = camera?.position?.constructor || j.position.constructor;
                const e = mesh.matrixWorld.elements;
                st.mirrorN = new V3(e[0], e[1], e[2]).normalize();
            } catch {}

            const mp = ({ leftArm: 'rightArm', rightArm: 'leftArm', leftLeg: 'rightLeg', rightLeg: 'leftLeg' })[part];
            if (mp) {
                const mj = findJoint(mesh, PARTS[mp].joints[0]);
                if (mj?.quaternion) {
                    st.mirrorPart = mp;
                    st.mirrorJoint = mj;
                    st.qMirrorStart = new Q();
                    st.qMirrorParentInv = new Q();
                    mj.getWorldQuaternion(st.qMirrorStart);
                    if (mj.parent?.quaternion) mj.parent.getWorldQuaternion(st.qMirrorParentInv);
                    qInv(st.qMirrorParentInv);
                }
            }
            const id = ++rotDragSeq;
            rotDrags.set(id, st);
            return id;
        } catch { return null; }
    }

    function applyRotateWorld(handle, dxTotal, dyTotal, snap15, mirror) {
        const st = rotDrags.get(handle);
        if (!st) return null;
        const camera = st.camera || getCamera();
        if (!camera?.matrixWorld) return null;
        try {
            camera.updateMatrixWorld?.();
            const V3 = camera.position.constructor;
            const e = camera.matrixWorld.elements;
            const right = new V3(e[0], e[1], e[2]).normalize();
            const back = new V3(e[8], e[9], e[10]).normalize();

            const k = 0.5 * Math.PI / 180;
            let aR = dyTotal * k;
            let aB = dxTotal * k;
            if (snap15) {
                const s = 15 * Math.PI / 180;
                aR = Math.round(aR / s) * s;
                aB = Math.round(aB / s) * s;
            }

            const qDelta = new st.Q().setFromAxisAngle(back, aB).multiply(new st.Q().setFromAxisAngle(right, aR));

            const qNew = qDelta.clone().multiply(st.qStartWorld);
            const qLocal = st.qParentWorldInv.clone().multiply(qNew);

            st.joint.quaternion.copy(qLocal);

            const deg = (r) => r * 180 / Math.PI;
            const out = { deg: [deg(st.joint.rotation.x), deg(st.joint.rotation.y), deg(st.joint.rotation.z)] };

            if (mirror && st.mirrorJoint) {
                const mR = reflectAxis(right, st.mirrorN);
                const mB = reflectAxis(back, st.mirrorN);
                const qDeltaM = new st.Q().setFromAxisAngle(mB, -aB).multiply(new st.Q().setFromAxisAngle(mR, -aR));
                const qNewM = qDeltaM.clone().multiply(st.qMirrorStart);
                const qLocalM = st.qMirrorParentInv.clone().multiply(qNewM);
                st.mirrorJoint.quaternion.copy(qLocalM);
                out.mirrorDeg = [deg(st.mirrorJoint.rotation.x), deg(st.mirrorJoint.rotation.y), deg(st.mirrorJoint.rotation.z)];
            }
            return out;
        } catch { return null; }
    }

    function endRotateWorld(handle) { rotDrags.delete(handle); }

    function applyAxisRotateWorld(handle, axis, angle, snap15, mirror) {
        const st = rotDrags.get(handle);
        if (!st) return null;
        const dirMap = { x: [1, 0, 0], y: [0, 1, 0], z: [0, 0, 1] };
        const d = dirMap[axis];
        if (!d) return null;
        try {
            const V3 = st.joint.position.constructor;
            let a = angle;
            if (snap15) {
                const s = 15 * Math.PI / 180;
                a = Math.round(a / s) * s;
            }
            const axisV = new V3(d[0], d[1], d[2]);
            const qDelta = new st.Q().setFromAxisAngle(axisV, a);

            const qNew = qDelta.clone().multiply(st.qStartWorld);
            const qLocal = st.qParentWorldInv.clone().multiply(qNew);
            st.joint.quaternion.copy(qLocal);

            const deg = (r) => r * 180 / Math.PI;
            const out = { deg: [deg(st.joint.rotation.x), deg(st.joint.rotation.y), deg(st.joint.rotation.z)], angle: a };

            if (mirror && st.mirrorJoint) {
                const mAxis = reflectAxis(axisV, st.mirrorN);
                const qDeltaM = new st.Q().setFromAxisAngle(mAxis, -a);
                const qNewM = qDeltaM.clone().multiply(st.qMirrorStart);
                const qLocalM = st.qMirrorParentInv.clone().multiply(qNewM);
                st.mirrorJoint.quaternion.copy(qLocalM);
                out.mirrorDeg = [deg(st.mirrorJoint.rotation.x), deg(st.mirrorJoint.rotation.y), deg(st.mirrorJoint.rotation.z)];
            }
            return out;
        } catch { return null; }
    }

    function worldAxisToLocal(joint, ax, ay, az) {
        try {
            joint.parent?.updateMatrixWorld?.(true);
            const V3 = joint.position.constructor;
            const v = new V3(ax, ay, az);
            if (joint.parent?.quaternion) {
                const pq = new joint.parent.quaternion.constructor();
                joint.parent.getWorldQuaternion(pq);
                qInv(pq);
                v.applyQuaternion(pq);
            }
            return v;
        } catch { return null; }
    }

    function clampOffsetToRest(j, restName) {
        const rest = ensureRest();
        const r = rest?.[restName];
        if (!r) return;
        j.position.x = r.px + Math.min(2, Math.max(-2, j.position.x - r.px));
        j.position.y = r.py + Math.min(2, Math.max(-2, j.position.y - r.py));
        j.position.z = r.pz + Math.min(2, Math.max(-2, j.position.z - r.pz));
    }

    function addWorldOffset(part, axisName, amount) {
        const def = PARTS[part];
        if (!def) throw new Error('unknown part: ' + part);
        const mesh = getMesh();
        if (!mesh) throw new Error('player/mesh not available');
        const j = findJoint(mesh, def.joints[0]);
        if (!j) throw new Error('joint "' + def.joints[0] + '" not found');
        const axes = { x: [1, 0, 0], y: [0, 1, 0], z: [0, 0, 1] };
        if (!axes[axisName]) throw new Error('unknown axis: ' + axisName);
        const v = worldAxisToLocal(j, axes[axisName][0], axes[axisName][1], axes[axisName][2]);
        if (!v) throw new Error('no world→local conversion');
        j.position.x += v.x * amount;
        j.position.y += v.y * amount;
        j.position.z += v.z * amount;
        clampOffsetToRest(j, def.joints[0]);
        return getOffset(part);
    }

    function addScreenOffset(part, camRight, camUp, dxWorld, dyWorld) {
        const def = PARTS[part];
        if (!def) throw new Error('unknown part: ' + part);
        const mesh = getMesh();
        if (!mesh) throw new Error('player/mesh not available');
        const j = findJoint(mesh, def.joints[0]);
        if (!j) throw new Error('joint "' + def.joints[0] + '" not found');
        const rx = worldAxisToLocal(j, camRight.x, camRight.y, camRight.z);
        const uy = worldAxisToLocal(j, camUp.x, camUp.y, camUp.z);
        if (!rx || !uy) throw new Error('no world→local conversion');
        j.position.x += rx.x * dxWorld + uy.x * dyWorld;
        j.position.y += rx.y * dxWorld + uy.y * dyWorld;
        j.position.z += rx.z * dxWorld + uy.z * dyWorld;
        clampOffsetToRest(j, def.joints[0]);
        return getOffset(part);
    }

    window.MF_Pose = {
        setPart, getPose, applyPoseObj, reset,
        getScale, setScale,
        getOffset, setOffset,
        beginRotateWorld, applyRotateWorld, applyAxisRotateWorld, endRotateWorld, addWorldOffset, addScreenOffset,
        save, apply, remove, applyPreset,
        pickPart,
        list() { return Object.keys(loadPoses()); },
        get presets() { return Object.keys(PRESETS); },
        captureRest,
        PARTS
    };
    window.__MF_Pose = true;

    void 0;
})();

//# sourceURL=MF:src/Studio/MF_Pose.js

/* ==== mf module: src/Studio/MF_Gizmo.js ==== */

(function () {
    'use strict';
    if (window.__MF_Gizmo) return;
    const TAG = 'minifeather gizmo';

    const AXIS_COLORS = { x: 0xff4d4d, y: 0x4dff88, z: 0x4d9fff };
    const SHAFT_LEN = 0.6;

    const SHAFT_R = 0.022;

    const HEAD_LEN = 0.16;

    const HEAD_R = 0.06;

    const RING_R = 0.42;

    const RING_TUBE = 0.028;

    const state = {
        root: null,

        arrows: null,

        rings: null,

        joint: null,
        onDelta: null,
        dragging: null,

        dragCtx: null,

        ctors: null,
        scene: null,
        size: 1
    };

    function grabCtors() {
        if (state.ctors) return state.ctors;
        try {

            const probe = window.MF_Pose?.getPose?.();
            const ent = (function () {
                const g = globalThis.miniblox?.player ? globalThis.miniblox : null;
                return g;
            })();

            const mesh = findPlayerMesh();
            if (!mesh) return null;
            let arm = null;
            mesh.traverse(o => { if (!arm && o?.isMesh && o.geometry) arm = o; });
            if (!arm) return null;

            const srcMat = Array.isArray(arm.material) ? arm.material[0] : arm.material;
            if (!srcMat?.constructor) return null;
            state.ctors = {
                Mesh: arm.constructor,
                Group: mesh.constructor?.name === 'Group' ? mesh.constructor : arm.parent?.constructor,
                BufferGeometry: arm.geometry.constructor,
                BufferAttribute: arm.geometry.attributes.position.constructor,
                Material: srcMat.constructor
            };

            let g = arm;
            while (g && !(g.children && !g.geometry && g.isObject3D !== false)) g = g.parent;
            if (g) state.ctors.Group = g.constructor;
            return state.ctors;
        } catch { return null; }
    }

    function findPlayerMesh() {
        try {
            const P = window.MF_Pose;

            const game = globalThis.miniblox?.player ? globalThis.miniblox : reactGame();
            const me = game?.player;
            if (!me) return null;
            const e = game?.world?.getPlayerById?.(me.id) || game?.world?.players?.get?.(me.id) || game?.world?.entities?.get?.(me.id) || me;
            return e?.mesh || null;
        } catch { return null; }
    }

    function reactGame() {
        try {
            const react = document.querySelector('#react');
            if (react) for (const root of Object.values(react)) {
                const g = root?.updateQueue?.baseState?.element?.props?.game;
                if (g?.player) return g;
            }
        } catch {}
        return null;
    }

    function makeCylinder(ctors, radius, height, radialSegs) {
        const geo = new ctors.BufferGeometry();
        const pos = [];
        const idx = [];
        const half = 0;

        for (let i = 0; i <= radialSegs; i++) {
            const a = (i / radialSegs) * Math.PI * 2;
            const c = Math.cos(a), s = Math.sin(a);
            pos.push(c * radius, half, s * radius);

            pos.push(c * radius, half + height, s * radius);
        }
        for (let i = 0; i < radialSegs; i++) {
            const b = i * 2;
            idx.push(b, b + 1, b + 2, b + 1, b + 3, b + 2);
        }
        geo.setAttribute('position', new ctors.BufferAttribute(new Float32Array(pos), 3));
        geo.setIndex(new ctors.BufferAttribute(new Uint16Array(idx), 1));
        try { geo.computeVertexNormals(); } catch {}
        return geo;
    }

    function makeCone(ctors, radius, height, segs) {
        const geo = new ctors.BufferGeometry();
        const pos = [0, height, 0];
        const idx = [];
        for (let i = 0; i < segs; i++) {
            const a = (i / segs) * Math.PI * 2;
            pos.push(Math.cos(a) * radius, 0, Math.sin(a) * radius);
        }
        for (let i = 0; i < segs; i++) {
            const a0 = 1 + i, a1 = 1 + ((i + 1) % segs);
            idx.push(0, a1, a0);
        }

        const center = pos.length / 3;
        pos.push(0, 0, 0);
        for (let i = 0; i < segs; i++) {
            const a0 = 1 + i, a1 = 1 + ((i + 1) % segs);
            idx.push(center, a0, a1);
        }
        geo.setAttribute('position', new ctors.BufferAttribute(new Float32Array(pos), 3));
        geo.setIndex(new ctors.BufferAttribute(new Uint16Array(idx), 1));
        try { geo.computeVertexNormals(); } catch {}
        return geo;
    }

    function makeTorus(ctors, radius, tubeR, tubularSegs, radialSegs) {
        const geo = new ctors.BufferGeometry();
        const pos = [];
        const idx = [];
        for (let i = 0; i <= tubularSegs; i++) {
            const u = (i / tubularSegs) * Math.PI * 2;
            const cu = Math.cos(u), su = Math.sin(u);
            for (let j = 0; j <= radialSegs; j++) {
                const v = (j / radialSegs) * Math.PI * 2;
                const cv = Math.cos(v), sv = Math.sin(v);
                pos.push(
                    (radius + tubeR * cv) * cu,
                    tubeR * sv,
                    (radius + tubeR * cv) * su
                );
            }
        }
        for (let i = 0; i < tubularSegs; i++) {
            for (let j = 0; j < radialSegs; j++) {
                const a = i * (radialSegs + 1) + j;
                const b = a + radialSegs + 1;
                idx.push(a, b, a + 1, b, b + 1, a + 1);
            }
        }
        geo.setAttribute('position', new ctors.BufferAttribute(new Float32Array(pos), 3));
        geo.setIndex(new ctors.BufferAttribute(new Uint16Array(idx), 1));
        try { geo.computeVertexNormals(); } catch {}
        return geo;
    }

    function makeArrowMesh(ctors, color) {
        const shaft = makeCylinder(ctors, SHAFT_R, SHAFT_LEN, 8);
        const head = makeCone(ctors, HEAD_R, HEAD_LEN, 10);

        const mat = new ctors.Material();

        const matOpts = { transparent: false };
        let m1, m2;
        try {
            m1 = new ctors.Mesh(shaft, mat);
            m2 = new ctors.Mesh(head, mat);
        } catch { return null; }
        m2.position.y = SHAFT_LEN;
        const g = new ctors.Group();
        g.add(m1);
        g.add(m2);

        try { if (mat.color?.set) mat.color.set(color); } catch {}
        try {

            if ('emissive' in mat && mat.emissive?.set) mat.emissive.set(color);
            if ('emissiveIntensity' in mat) mat.emissiveIntensity = 0.9;
            if ('fog' in mat) mat.fog = false;
            mat.needsUpdate = true;
        } catch {}
        return { group: g, mat };
    }

    function attach(joint, onDelta) {
        const ctors = grabCtors();
        if (!ctors || !joint) return false;
        detach();
        try {

            const scene = findScene(joint) || findPlayerMesh()?.parent;
            if (!scene || !scene.add) return false;
            // para el guard de update(): el ancestro más alto de verdad, no el
            // fallback intermedio, o el gizmo se soltaría solo al primer tick
            state.scene = findScene(joint) || scene;
            state.joint = joint;
            state.onDelta = onDelta;
            state.root = new ctors.Group();
            state.arrows = {};
            const dirs = { x: [1, 0, 0], y: [0, 1, 0], z: [0, 0, 1] };
            for (const axis of ['x', 'y', 'z']) {
                const arrow = makeArrowMesh(ctors, AXIS_COLORS[axis]);
                if (!arrow) continue;

                const [dx, dy, dz] = dirs[axis];

                if (axis === 'x') arrow.group.rotation.z = -Math.PI / 2;
                else if (axis === 'z') arrow.group.rotation.x = Math.PI / 2;

                arrow.group.userData = arrow.group.userData || {};
                arrow.group.userData.__mfAxis = axis;
                state.root.add(arrow.group);
                state.arrows[axis] = { group: arrow.group, mat: arrow.mat, dir: dirs[axis] };
            }
            state.root.userData = state.root.userData || {};
            state.root.userData.__mfGizmo = true;

            state.rings = {};
            const ringDirs = { x: [1, 0, 0], y: [0, 1, 0], z: [0, 0, 1] };
            for (const axis of ['x', 'y', 'z']) {
                const torus = makeTorus(ctors, RING_R, RING_TUBE, 48, 8);
                if (!torus) continue;
                const mat = new ctors.Material();
                const mesh = new ctors.Mesh(torus, mat);

                if (axis === 'x') mesh.rotation.z = Math.PI / 2;
                else if (axis === 'z') mesh.rotation.x = Math.PI / 2;
                mesh.userData = mesh.userData || {};
                mesh.userData.__mfRing = axis;
                state.root.add(mesh);
                state.rings[axis] = { mesh, mat, dir: ringDirs[axis] };
                try {
                    if (mat.color?.set) mat.color.set(AXIS_COLORS[axis]);
                    if ('emissive' in mat && mat.emissive?.set) mat.emissive.set(AXIS_COLORS[axis]);
                    if ('emissiveIntensity' in mat) mat.emissiveIntensity = 0.7;
                    if ('transparent' in mat) mat.transparent = true;
                    if ('opacity' in mat) mat.opacity = 0.55;
                    if ('fog' in mat) mat.fog = false;
                    if ('depthWrite' in mat) mat.depthWrite = false;
                    mat.needsUpdate = true;
                } catch {}
            }

            state.root.traverse(o => {
                if (o?.isMesh) {
                    o.renderOrder = 999;
                    try {
                        const mats = Array.isArray(o.material) ? o.material : [o.material];
                        for (const m of mats) {
                            if ('depthTest' in m) m.depthTest = false;
                            if ('transparent' in m) m.transparent = true;
                            if ('opacity' in m) m.opacity = 0.95;
                        }
                    } catch {}
                }
            });
            scene.add(state.root);
            update();
            state.size = 1;
            return true;
        } catch (e) {
            // fallo a mitad de construcción: no dejar un root fantasma con
            // visible() en true y joint apuntando a nada
            detach();
            console.warn(TAG + ' attach failed:', e?.message || e);
            return false;
        }
    }

    function update() {
        if (!state.root || !state.joint) return;
        try {
            // el rig puede despawnearse o reconstruirse (cambio de skin) con el
            // gizmo puesto: si el joint ya no cuelga de la escena, soltar antes
            // de seguir arrastrando el cadáver
            if (state.scene && findScene(state.joint) !== state.scene) { detach(); return; }
            state.joint.updateMatrixWorld?.(true);
            const V3 = state.joint.position.constructor;
            const p = new V3();
            state.joint.getWorldPosition(p);
            state.root.position.copy(p);
            state.root.rotation.set(0, 0, 0);
            state.root.updateMatrixWorld?.(true);
        } catch {}
    }

    function findScene(node) {
        let n = node;
        let guard = 0;
        while (n?.parent && guard++ < 64) n = n.parent;
        return n?.add ? n : null;
    }

    function setMode(mode) {
        if (!state.root) return;
        const showArrows = mode !== 'rotate';
        const showRings = mode !== 'move';
        try {
            for (const axis of ['x', 'y', 'z']) {
                if (state.arrows?.[axis]) state.arrows[axis].group.visible = showArrows;
                if (state.rings?.[axis]) state.rings[axis].mesh.visible = showRings;
            }
            state.mode = mode;
        } catch {}
    }

    function detach() {
        if (state.root) {
            try { state.root.parent?.remove(state.root); } catch {}

            try {
                state.root.traverse(o => {
                    if (o?.isMesh && o.geometry?.dispose) o.geometry.dispose();
                });
            } catch {}
        }
        state.root = null; state.arrows = null; state.joint = null;
        state.onDelta = null; state.dragging = null; state.dragCtx = null;
        state.scene = null;
    }

    function visible() { return !!state.root; }

    // rect de referencia para proyectar: el mismo canvas que usa beginDrag y
    // pickPart. faltaba esta función entera — pick/pickRing/dragDelta llevaban
    // años devolviendo null por un ReferenceError silencioso
    function effectiveRect() {
        return (getGameCanvas() || document.body).getBoundingClientRect();
    }

    function pick(clientX, clientY, camera) {
        if (!state.arrows || !state.joint) return null;
        const cam = camera || getStudioCamera();
        if (!cam) return null;
        update();
        try {
            const V3 = cam.position.constructor;
            const rect = effectiveRect();
            const ndcX = ((clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
            const ndcY = -((clientY - rect.top) / Math.max(1, rect.height)) * 2 + 1;
            cam.updateMatrixWorld?.();
            const origin = new V3().setFromMatrixPosition(cam.matrixWorld);
            const dir = new V3(ndcX, ndcY, 0.5).unproject(cam).sub(origin).normalize();

            state.joint.updateMatrixWorld?.(true);
            const jp = new V3();
            state.joint.getWorldPosition(jp);
            const len = (SHAFT_LEN + HEAD_LEN) * state.size;

            let best = null;
            const tmp = new V3(), tip = new V3();
            for (const axis of ['x', 'y', 'z']) {
                const ar = state.arrows[axis];
                if (!ar || ar.group.visible === false) continue;
                const d = ar.dir;
                tip.set(jp.x + d[0] * len, jp.y + d[1] * len, jp.z + d[2] * len);

                tmp.set((jp.x + tip.x) / 2, (jp.y + tip.y) / 2, (jp.z + tip.z) / 2);
                const toMid = tmp.clone().sub(origin);
                const t = toMid.dot(dir);
                if (t < 0.05) continue;
                const closest = dir.clone().multiplyScalar(t).add(origin);
                const dist = closest.distanceTo(tmp);

                const worldPerPx = (2 * t * Math.tan(35 * Math.PI / 180)) / Math.max(1, rect.height);
                if (dist < Math.max(0.06, worldPerPx * 14)) {
                    if (!best || dist < best.dist) best = { axis, dist };
                }
            }
            return best?.axis || null;
        } catch { return null; }
    }

    function beginDrag(axis, camera) {
        const cam = camera || getStudioCamera();
        if (!cam || !state.arrows?.[axis] || !state.joint) return false;
        update();
        try {
            const V3 = cam.position.constructor;
            const rect = (getGameCanvas() || document.body).getBoundingClientRect();
            cam.updateMatrixWorld?.();
            state.joint.updateMatrixWorld?.(true);
            const jp = new V3();
            state.joint.getWorldPosition(jp);
            const d = state.arrows[axis].dir;
            const p0 = projectPoint(jp, cam, rect);
            const p1 = projectPoint(new V3(jp.x + d[0], jp.y + d[1], jp.z + d[2]), cam, rect);
            if (!p0 || !p1) return false;
            const ax = p1.x - p0.x, ay = p1.y - p0.y;
            const lenSq = ax * ax + ay * ay;
            if (lenSq < 1e-6) return false;
            state.dragCtx = { axis, ax, ay, lenSq };
            return true;
        } catch {
            state.dragCtx = null;
            return false;
        }
    }

    function dragDeltaFromStart(dxTotal, dyTotal) {
        const c = state.dragCtx;
        if (!c) return 0;
        return (dxTotal * c.ax + dyTotal * c.ay) / c.lenSq;
    }

    function endDrag() { state.dragCtx = null; }

    function dragDelta(axis, dxPx, dyPx, camera) {
        const cam = camera || getStudioCamera();
        if (!cam) return 0;
        update();
        try {
            const V3 = cam.position.constructor;
            const V2 = V3;

            state.joint?.updateMatrixWorld?.(true);
            const jp = new V3();
            state.joint.getWorldPosition(jp);
            const camPos = new V3().setFromMatrixPosition(cam.matrixWorld);
            const dist = camPos.distanceTo(jp);
            const rect = effectiveRect();

            const d = state.arrows[axis].dir;
            const p0 = projectPoint(jp, cam, rect);
            const p1 = projectPoint(
                new V3(jp.x + d[0], jp.y + d[1], jp.z + d[2]), cam, rect
            );
            if (!p0 || !p1) return 0;
            const ax = p1.x - p0.x, ay = p1.y - p0.y;
            const lenSq = ax * ax + ay * ay;
            if (lenSq < 1e-6) return 0;

            const amount = (dxPx * ax + dyPx * ay) / lenSq;
            return amount;
        } catch { return 0; }
    }

    function pickRing(clientX, clientY, camera) {
        if (!state.rings || !state.joint) return null;
        const cam = camera || getStudioCamera();
        if (!cam) return null;
        update();
        try {
            const V3 = cam.position.constructor;
            const rect = effectiveRect();
            const ndcX = ((clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
            const ndcY = -((clientY - rect.top) / Math.max(1, rect.height)) * 2 + 1;
            cam.updateMatrixWorld?.();
            const origin = new V3().setFromMatrixPosition(cam.matrixWorld);
            const dir = new V3(ndcX, ndcY, 0.5).unproject(cam).sub(origin).normalize();

            state.joint.updateMatrixWorld?.(true);
            const jp = new V3();
            state.joint.getWorldPosition(jp);

            let best = null;
            for (const axis of ['x', 'y', 'z']) {
                const r = state.rings[axis];
                if (!r || r.mesh.visible === false) continue;
                const d = r.dir;

                const denom = dir.x * d[0] + dir.y * d[1] + dir.z * d[2];
                if (Math.abs(denom) < 0.08) continue;
                const toC = jp.clone().sub(origin);
                const t = toC.dot(d) / denom;
                if (t < 0.05) continue;
                const hit = dir.clone().multiplyScalar(t).add(origin);
                const dist = hit.distanceTo(jp);
                const R = RING_R * state.size;

                const camDist = origin.distanceTo(jp);
                const worldPerPx = (2 * camDist * Math.tan(35 * Math.PI / 180)) / Math.max(1, rect.height);
                const tol = RING_TUBE + worldPerPx * 10;
                const band = Math.abs(dist - R);

                const score = band - t * 0.01;
                if (band < tol && (!best || score < best.score)) {
                    best = { axis, score };
                }
            }
            return best?.axis || null;
        } catch { return null; }
    }

    function ringDragDelta(axis, startXY, curXY, camera) {
        const cam = camera || getStudioCamera();
        if (!cam || !state.rings?.[axis]) return 0;
        update();
        try {
            const V3 = cam.position.constructor;
            const rect = effectiveRect();
            cam.updateMatrixWorld?.();
            const origin = new V3().setFromMatrixPosition(cam.matrixWorld);

            state.joint.updateMatrixWorld?.(true);
            const jp = new V3();
            state.joint.getWorldPosition(jp);

            const d = state.rings[axis].dir;
            const axisV = new V3(d[0], d[1], d[2]);

            const helper = Math.abs(d[1]) > 0.9 ? new V3(1, 0, 0) : new V3(0, 1, 0);
            const u = helper.clone().sub(axisV.clone().multiplyScalar(helper.dot(axisV))).normalize();
            const v = axisV.clone().cross(u);

            const angleAt = (cx, cy) => {
                const ndcX = ((cx - rect.left) / Math.max(1, rect.width)) * 2 - 1;
                const ndcY = -((cy - rect.top) / Math.max(1, rect.height)) * 2 + 1;
                const dir = new V3(ndcX, ndcY, 0.5).unproject(cam).sub(origin).normalize();
                const denom = dir.dot(axisV);
                if (Math.abs(denom) < 1e-4) return null;
                const toC = jp.clone().sub(origin);
                const t = toC.dot(axisV) / denom;
                if (t < 0.05) return null;
                const hit = dir.clone().multiplyScalar(t).add(origin).sub(jp);
                return Math.atan2(hit.dot(v), hit.dot(u));
            };

            const a0 = angleAt(startXY.x, startXY.y);
            const a1 = angleAt(curXY.x, curXY.y);
            if (a0 == null || a1 == null) return 0;
            let delta = a1 - a0;

            while (delta > Math.PI) delta -= Math.PI * 2;
            while (delta < -Math.PI) delta += Math.PI * 2;
            return delta;
        } catch { return 0; }
    }

    function projectPoint(world, cam, rect) {
        try {
            const V3 = cam.position.constructor;
            const v = world.clone();
            v.project(cam);
            if (v.z > 1 || v.z < -1) return null;
            return {
                x: rect.left + (v.x + 1) / 2 * rect.width,
                y: rect.top + (1 - v.y) / 2 * rect.height
            };
        } catch { return null; }
    }

    function getStudioCamera() {
        const g = reactGame();
        return g?.gameScene?.camera || g?.camera || null;
    }

    function getGameCanvas() {
        const g = reactGame();
        const c = g?.gameScene?.renderer?.domElement || g?.renderer?.domElement;
        if (c) return c;
        let best = null;
        try {
            for (const cv of document.querySelectorAll('canvas')) {
                if (!best || cv.width * cv.height > best.width * best.height) best = cv;
            }
        } catch {}
        return best;
    }

    window.MF_Gizmo = { attach, detach, pick, beginDrag, dragDeltaFromStart, endDrag, dragDelta, visible, pickRing, ringDragDelta, setMode };
    window.__MF_Gizmo = true;

    void 0;
})();

