  function bindLocalizedFileInputs() {
    if (!panel) return;
    panel.querySelectorAll('.mf-file-input').forEach(input => {
      const name = input.closest('.mf-file-picker')?.querySelector('[data-file-name]');
      if (!name) return;
      const updateName = () => {
        name.textContent = input.files?.[0]?.name || t('noFileSelected');
        name.title = input.files?.[0]?.name || '';
      };
      input.addEventListener('change', updateName);
      updateName();
    });
  }

  async function copyMemeId(value) {
    try {
      await navigator.clipboard.writeText(value);
      return true;
    } catch (_) {
      const input = document.createElement('textarea');
      input.value = value;
      input.setAttribute('readonly', '');
      input.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0;';
      document.body.appendChild(input);
      input.select();
      let copied = false;
      try {
        copied = document.execCommand('copy');
      } catch (_) {}
      input.remove();
      return copied;
    }
  }

  function openFreelookSettings() {
    if (!panel) return;
    const existing = panel.querySelector('.mf-freelook-backdrop');
    existing?.remove();
    const backdrop = document.createElement('div');
    backdrop.className = 'mf-tt-backdrop mf-freelook-backdrop';
    const currentMode =
      settings.freelookMode === 'toggle'
        ? 'toggle'
        : 'hold';
    const currentBind =
      String(settings.freelookBind || '');
    backdrop.innerHTML = `
      <div
        class="mf-tt-dialog"
        role="dialog"
        aria-modal="true"
      >
        <div class="mf-tt-head">
          <div class="mf-tt-title">
            Freelook Settings
          </div>
          <button
            type="button"
            class="mf-close"
            data-fl-close
          >
            ×
          </button>
        </div>
        <div class="mf-tt-row">
          <span>Activation Mode</span>
        </div>
        <div class="mf-grid-2">
          <button
            type="button"
            class="mf-btn secondary ${currentMode === 'hold' ? 'active' : ''}"
            data-fl-mode="hold"
          >
            Hold
          </button>
          <button
            type="button"
            class="mf-btn secondary ${currentMode === 'toggle' ? 'active' : ''}"
            data-fl-mode="toggle"
          >
            Toggle
          </button>
        </div>
        <div class="mf-tt-row">
          <span>Keybind</span>
        </div>
        <div class="mf-tt-bind-box">
          <span class="mf-muted">
            Freelook Key
          </span>
          <span
            class="mf-tt-bind-code"
            data-fl-bind-code
          >
            ${currentBind || 'Not Bound'}
          </span>
        </div>
        <div class="mf-tt-bind-actions">
          <button
            type="button"
            class="mf-btn secondary"
            data-fl-bind
          >
            Set Keybind
          </button>
          <button
            type="button"
            class="mf-btn danger"
            data-fl-unbind
          >
            Remove
          </button>
        </div>
        <div class="mf-tt-hint">
          Hold mode keeps freelook active while the key is held.
          Toggle mode switches freelook on and off each time the key is pressed.
        </div>
        <button
          type="button"
          class="mf-btn primary mf-tt-save"
          data-fl-save
        >
          Save
        </button>
      </div>
    `;
    panel.appendChild(backdrop);
    const bindCode =
      backdrop.querySelector('[data-fl-bind-code]');
    const bindButton =
      backdrop.querySelector('[data-fl-bind]');
    let binding = false;
    const updateModeButtons = () => {
      backdrop
        .querySelectorAll('[data-fl-mode]')
        .forEach(button => {
          button.classList.toggle(
            'active',
            button.dataset.flMode === settings.freelookMode
          );
        });
    };
    backdrop
      .querySelectorAll('[data-fl-mode]')
      .forEach(button => {
        button.addEventListener('click', () => {
          settings.freelookMode =
            button.dataset.flMode === 'toggle'
              ? 'toggle'
              : 'hold';
          guiSettings.freelookMode =
            settings.freelookMode;
          updateModeButtons();
        });
      });
    const stopBinding = () => {
      binding = false;
      document.dispatchEvent(
        new CustomEvent(
          'minifeather:freelook-binding',
          {
            detail: JSON.stringify({
              active: false
            })
          }
        )
      );
      if (bindButton) {
        bindButton.textContent = 'Set Keybind';
      }
    };
    bindButton?.addEventListener('click', () => {
      binding = true;
      document.dispatchEvent(
        new CustomEvent(
          'minifeather:freelook-binding',
          {
            detail: JSON.stringify({
              active: true
            })
          }
        )
      );
      bindButton.textContent =
        'Press a Key...';
    });
    backdrop
      .querySelector('[data-fl-unbind]')
      ?.addEventListener('click', () => {
        stopBinding();
        settings.freelookBind = '';
        guiSettings.freelookBind = '';
        if (bindCode) {
          bindCode.textContent = 'Not Bound';
        }
        document.dispatchEvent(
          new CustomEvent(
            'minifeather:freelook-config',
            {
              detail: JSON.stringify({
                enabled:
                  !!settings.freelook,
                bind: '',
                mode:
                  settings.freelookMode
              })
            }
          )
        );
        saveSettings();
      });
    const keyHandler = event => {
      if (!binding) return;
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation();
      if (
        event.code === 'Escape' ||
        event.code === 'Backspace' ||
        event.code === 'Delete'
      ) {
        settings.freelookBind = '';
        guiSettings.freelookBind = '';
        if (bindCode) {
          bindCode.textContent = 'Not Bound';
        }
      } else {
        settings.freelookBind = event.code;
        guiSettings.freelookBind = event.code;
        if (bindCode) {
          bindCode.textContent = event.code;
        }
      }
      stopBinding();
    };
    document.addEventListener(
      'keydown',
      keyHandler,
      true
    );
    const cleanup = () => {
      stopBinding();
      document.removeEventListener(
        'keydown',
        keyHandler,
        true
      );
      backdrop.remove();
    };
    backdrop
      .querySelector('[data-fl-close]')
      ?.addEventListener('click', cleanup);
    backdrop
      .querySelector('[data-fl-save]')
      ?.addEventListener('click', () => {
        saveSettings();
        document.dispatchEvent(
          new CustomEvent(
            'minifeather:freelook-config',
            {
              detail: JSON.stringify({
                enabled:
                  !!settings.freelook,
                bind:
                  String(settings.freelookBind || ''),
                mode:
                  settings.freelookMode
              })
            }
          )
        );
        cleanup();
      });
    backdrop.addEventListener(
      'mousedown',
      event => {
        if (event.target === backdrop) {
          cleanup();
        }
      }
    );
    updateModeButtons();
  }

  function openBlockHighlightSettings() {
    if (!panel) return;

    const existing =
      panel.querySelector('.mf-block-highlight-backdrop');

    existing?.remove();

    const backdrop = document.createElement('div');

    backdrop.className =
      'mf-tt-backdrop mf-block-highlight-backdrop';

    const color =
      settings.blockHighlightColor || '#ffffff';

    const thickness =
      Number(settings.blockHighlightThickness) || 1;

    backdrop.innerHTML = `
      <div
        class="mf-tt-dialog"
        role="dialog"
        aria-modal="true"
      >
        <div class="mf-tt-head">
          <div class="mf-tt-title">
            Block Highlight Settings
          </div>
          <button
            type="button"
            class="mf-close"
            data-bh-close
          >
            ×
          </button>
        </div>
        <div class="mf-tt-row">
          <span>Highlight Color</span>
        </div>
        <div style="
          display:flex;
          align-items:center;
          gap:10px;
          margin-bottom:16px;
        ">
          <input
            type="color"
            data-bh-color
            value="${color}"
            style="
              width:52px;
              height:40px;
              padding:3px;
              border-radius:10px;
              border:1px solid var(--mf-border);
              background:transparent;
              cursor:pointer;
            "
          >
          <input
            type="text"
            class="mf-input"
            data-bh-color-text
            value="${color}"
            maxlength="7"
            placeholder="#ffffff"
          >
        </div>
        <div class="mf-tt-row" style="margin-top:12px;">
          <span>Rainbow Mode</span>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-rainbow
          >
            ${settings.blockHighlightRainbow ? 'On' : 'Off'}
          </button>
        </div>
        <div class="mf-tt-row">
          <span>Thickness</span>
          <span
            class="mf-tt-scale-value"
            data-bh-thickness-value
          >
            ${thickness}
          </span>
        </div>
        <input
          class="mf-tt-range"
          data-bh-thickness
          type="range"
          min="1"
          max="6"
          step="1"
          value="${thickness}"
        >
        <div class="mf-grid-2" style="margin-top:12px;">
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="1"
          >
            Thin
          </button>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="2"
          >
            Medium
          </button>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="3"
          >
            Thick
          </button>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="4"
          >
            Extra Thick
          </button>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="5"
          >
            Ultra
          </button>
          <button
            type="button"
            class="mf-btn secondary"
            data-bh-preset="6"
          >
            Max
          </button>
        </div>
        <div class="mf-tt-hint">
          Changes are applied immediately while this window is open.
        </div>
        <button
          type="button"
          class="mf-btn primary mf-tt-save"
          data-bh-save
        >
          Save
        </button>
      </div>
    `;

    panel.appendChild(backdrop);

    const colorInput =
      backdrop.querySelector('[data-bh-color]');

    const colorText =
      backdrop.querySelector('[data-bh-color-text]');

    const thicknessInput =
      backdrop.querySelector('[data-bh-thickness]');

    const thicknessValue =
      backdrop.querySelector('[data-bh-thickness-value]');

    const apply = () => {
      const selectedColor =
        colorInput?.value || '#ffffff';

      const selectedThickness =
        Math.max(
          1,
          Math.min(
            6,
            Number(thicknessInput?.value) || 1
          )
        );

      settings.blockHighlightColor =
        selectedColor;

      settings.blockHighlightThickness =
        selectedThickness;

      guiSettings.blockHighlightColor =
        selectedColor;

      guiSettings.blockHighlightThickness =
        selectedThickness;

      if (colorText) {
        colorText.value = selectedColor;
      }

      if (thicknessValue) {
        thicknessValue.textContent =
          String(selectedThickness);
      }

      document.dispatchEvent(
          new CustomEvent(
              'minifeather:block-highlight-config',
              {
                  detail: JSON.stringify({
                      enabled:
                          !!settings.blockHighlight,
                      color:
                          selectedColor,
                      thickness:
                          selectedThickness,
                      rainbow:
                          !!settings.blockHighlightRainbow
                  })
              }
          )
      );
    };
    const rainbowBtn =
      backdrop.querySelector('[data-bh-rainbow]');
    rainbowBtn?.addEventListener(
      'click',
      () => {
        settings.blockHighlightRainbow =
          !settings.blockHighlightRainbow;
        guiSettings.blockHighlightRainbow =
          settings.blockHighlightRainbow;
        if (rainbowBtn) {
          rainbowBtn.textContent =
            settings.blockHighlightRainbow
              ? 'On'
              : 'Off';
        }
        saveSettings(true);
        apply();
      }
    );

    colorInput?.addEventListener(
      'input',
      apply
    );

    colorText?.addEventListener(
      'change',
      () => {
        let value =
          colorText.value.trim();

        if (!/^#[0-9a-fA-F]{6}$/.test(value)) {
          value = '#ffffff';
        }

        colorInput.value = value;

        apply();
      }
    );

    thicknessInput?.addEventListener(
      'input',
      apply
    );

    backdrop
      .querySelectorAll('[data-bh-preset]')
      .forEach(button => {
        button.addEventListener(
          'click',
          () => {
            thicknessInput.value =
              button.dataset.bhPreset;

            apply();
          }
        );
      });

    const cleanup = () => {
      saveSettings();
      backdrop.remove();
    };

    backdrop
      .querySelector('[data-bh-close]')
      ?.addEventListener(
        'click',
        cleanup
      );

    backdrop
      .querySelector('[data-bh-save]')
      ?.addEventListener(
        'click',
        cleanup
      );

    backdrop.addEventListener(
      'mousedown',
      event => {
        if (event.target === backdrop) {
          cleanup();
        }
      }
    );
  }

